:root{
  --bg:#f7f8fb; --surface:#ffffff; --soft:#f1f3f8; --text:#0f172a; --muted:#5b6474; --line:#e3e7ef;
  --accent:#4f46e5; --accent-2:#9333ea; --accent-soft:#eef0ff; --amber:#b45309; --amber-soft:#fff7e6;
  --good:#047857; --good-soft:#e8f8f1; --bad:#c81e1e; --bad-soft:#fdeeee;
  --code-bg:#0d1117; --code-bar:#151a23; --code-text:#e6edf3; --code-dim:#9aa4b2; --code-hl:#1a2233; --code-line:#232a36;
  --shadow:0 1px 2px rgba(15,23,42,.04),0 6px 20px rgba(15,23,42,.06);
  color-scheme:light;
}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){
  --bg:#0a0c12; --surface:#11141c; --soft:#181c26; --text:#e6e9f0; --muted:#8b93a7; --line:#232836;
  --accent:#8b8cf8; --accent-2:#c084fc; --accent-soft:#1c1e3a; --amber:#fbbf24; --amber-soft:#2a2110;
  --good:#34d399; --good-soft:#0f2a20; --bad:#f87171; --bad-soft:#2c1515;
  --code-bg:#0b0e14; --code-bar:#121720; --code-hl:#172033; --code-line:#1e2430;
  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 28px rgba(0,0,0,.28); color-scheme:dark;}}
:root[data-theme="dark"]{
  --bg:#0a0c12; --surface:#11141c; --soft:#181c26; --text:#e6e9f0; --muted:#8b93a7; --line:#232836;
  --accent:#8b8cf8; --accent-2:#c084fc; --accent-soft:#1c1e3a; --amber:#fbbf24; --amber-soft:#2a2110;
  --good:#34d399; --good-soft:#0f2a20; --bad:#f87171; --bad-soft:#2c1515;
  --code-bg:#0b0e14; --code-bar:#121720; --code-hl:#172033; --code-line:#1e2430;
  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 28px rgba(0,0,0,.28); color-scheme:dark;}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:72px}
body{margin:0;position:relative;background:var(--bg);color:var(--text);font:16px/1.7 Inter,system-ui,-apple-system,Segoe UI,sans-serif;-webkit-font-smoothing:antialiased;overflow-x:hidden}
body::before{content:"";position:absolute;top:0;left:0;right:0;height:560px;z-index:-1;pointer-events:none;
  background:radial-gradient(55% 70% at 12% 0%,color-mix(in srgb,var(--accent) 16%,transparent),transparent 70%),
             radial-gradient(45% 60% at 92% 8%,color-mix(in srgb,var(--accent-2) 13%,transparent),transparent 70%)}
.wrap{max-width:880px;margin:0 auto;padding:0 20px}
code,pre,.mono,kbd{font-family:"JetBrains Mono",ui-monospace,Consolas,monospace}
code,pre,kbd,.code,.CodeMirror,.CodeMirror-hints{font-variant-ligatures:none;font-feature-settings:"liga" 0,"calt" 0}
:not(pre)>code{font-size:.86em;background:var(--soft);border:1px solid var(--line);padding:.05em .35em;border-radius:6px}
a{color:var(--accent)}
h1{font-size:clamp(2.3rem,7vw,3.5rem);line-height:1.08;letter-spacing:-.04em;margin:14px 0 14px;font-weight:700}
h2{font-size:1.7rem;letter-spacing:-.025em;margin:0 0 .8rem;line-height:1.25}
h3{font-size:1.08rem;margin:2rem 0 .6rem}
p{margin:.55rem 0}
ul,ol{padding-left:1.3rem;margin:.5rem 0}
li{margin:.25rem 0}
section{padding:60px 0;border-top:1px solid var(--line)}
.num{display:inline-block;font:600 .72rem "JetBrains Mono",monospace;color:var(--accent);background:var(--accent-soft);padding:3px 10px;border-radius:99px;letter-spacing:.08em;margin-bottom:12px}
.muted{color:var(--muted)}
.small{font-size:.9rem}
.grad{background:linear-gradient(95deg,var(--accent),var(--accent-2));-webkit-background-clip:text;background-clip:text;color:transparent}
kbd{display:inline-block;font-size:.72rem;padding:1px 6px;border:1px solid var(--line);border-bottom-width:2px;border-radius:5px;background:var(--surface);color:var(--text)}

/* nav */
nav{position:sticky;top:0;z-index:30;background:color-mix(in srgb,var(--bg) 80%,transparent);backdrop-filter:saturate(1.4) blur(12px);-webkit-backdrop-filter:saturate(1.4) blur(12px);border-bottom:1px solid var(--line)}
nav .wrap{display:flex;gap:2px;align-items:center;padding-top:9px;padding-bottom:9px}
nav .links{display:flex;gap:2px;overflow-x:auto;scrollbar-width:none;min-width:0;flex:1}
nav .links::-webkit-scrollbar{display:none}
nav .brand{flex:none;font:700 .85rem Inter,sans-serif;margin-right:10px;display:flex;align-items:center;gap:8px;color:var(--text);text-decoration:none}
nav .brand i{width:22px;height:22px;border-radius:7px;background:linear-gradient(135deg,var(--accent-fill),var(--accent-2-fill));display:grid;place-items:center;color:#fff;font:700 .68rem "JetBrains Mono",monospace;font-style:normal}
nav .links a{flex:none;font-size:.84rem;color:var(--muted);text-decoration:none;padding:5px 11px;border-radius:8px;font-weight:500;transition:background .15s,color .15s}
nav .links a:hover{color:var(--text);background:var(--soft)}
nav .links a.on{color:var(--accent);background:var(--accent-soft)}
nav button{margin-left:8px;flex:none;width:34px;height:34px;border:1px solid var(--line);background:var(--surface);color:var(--text);border-radius:9px;cursor:pointer;font-size:1rem;display:grid;place-items:center}
nav button:hover{border-color:var(--accent);color:var(--accent)}
#prog{position:absolute;left:0;bottom:-1px;height:2px;width:0;background:linear-gradient(90deg,var(--accent),var(--accent-2))}
@media (max-width:620px){nav .brand span{display:none}}

/* hero */
header{padding:72px 0 52px}
.tag{display:inline-flex;align-items:center;gap:8px;font:600 .74rem "JetBrains Mono",monospace;color:var(--accent);letter-spacing:.08em;padding:5px 12px;border:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));border-radius:99px;background:color-mix(in srgb,var(--surface) 70%,transparent)}
.tag::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 25%,transparent)}
.lead{font-size:1.15rem;color:var(--muted);max-width:620px}
.meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:24px}
.meta span{font-size:.84rem;color:var(--muted);padding:6px 13px;border:1px solid var(--line);background:var(--surface);border-radius:99px;box-shadow:var(--shadow)}
.meta b{color:var(--text);font-weight:600}

/* blocks */
.formula{font:600 1.15rem "JetBrains Mono",monospace;padding:20px;border-radius:14px;background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow);text-align:center;margin:20px 0;color:var(--accent)}
.note{border-left:3px solid var(--accent);background:var(--accent-soft);padding:12px 16px;border-radius:0 12px 12px 0;margin:16px 0;color:var(--text)}
.note.warn{border-color:var(--bad);background:var(--bad-soft)}
table{width:100%;border-collapse:separate;border-spacing:0;font-size:.92rem;margin:14px 0;background:var(--surface);border:1px solid var(--line);border-radius:12px;overflow:hidden}
th,td{text-align:left;padding:10px 14px;border-bottom:1px solid var(--line);vertical-align:top}
tr:last-child td{border-bottom:none}
th{font-size:.72rem;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);font-weight:600;background:var(--soft)}
.tw{overflow-x:auto}
.tw table{min-width:480px}
.good{color:var(--good);font-weight:600} .bad{color:var(--bad);font-weight:600}

/* cells */
.cells{display:flex;flex-wrap:wrap;gap:6px}
.cw{display:flex;flex-direction:column;align-items:center;gap:3px;min-width:40px}
.c{min-width:40px;height:44px;padding:0 6px;border-radius:10px;display:grid;place-items:center;font:600 1.05rem "JetBrains Mono",monospace;border:1.5px solid var(--line);background:var(--surface);box-shadow:0 1px 2px rgba(0,0,0,.04);transition:all .2s}
.c.sp{color:var(--muted)}
.c.read{border-color:var(--amber);background:var(--amber-soft);color:var(--amber);transform:translateY(-2px)}
.c.swap{border-color:transparent;background:linear-gradient(135deg,var(--accent-fill),var(--accent-2-fill));color:#fff;transform:translateY(-3px);box-shadow:0 6px 16px color-mix(in srgb,var(--accent) 35%,transparent)}
.c.done{border-color:color-mix(in srgb,var(--accent) 40%,transparent);background:var(--accent-soft);color:var(--accent)}
.c.copy{border-style:dashed;color:var(--muted)}
.c.new{border-color:transparent;background:linear-gradient(135deg,var(--accent-fill),var(--accent-2-fill));color:#fff}
.c.slot{border-style:dashed;color:transparent;box-shadow:none}
.c.fix{color:var(--muted);background:var(--soft)}
.i{font:500 .7rem "JetBrains Mono",monospace;color:var(--muted)}
.pt{height:18px;font:700 .68rem "JetBrains Mono",monospace;color:var(--accent)}
.empty{font:500 .85rem "JetBrains Mono",monospace;color:var(--muted);padding:10px 12px;border:1.5px dashed var(--line);border-radius:10px}
.row{display:grid;grid-template-columns:120px 1fr;gap:12px;align-items:center;margin:12px 0}
.row .lb{font:500 .78rem "JetBrains Mono",monospace;color:var(--muted)}

/* visualizer */
.viz{border:1px solid var(--line);border-radius:16px;background:var(--surface);margin:22px 0;overflow:hidden;box-shadow:var(--shadow)}
.seg{display:flex;gap:4px;padding:6px;background:var(--soft);border-bottom:1px solid var(--line);overflow-x:auto}
.seg button{flex:1;min-width:120px;border:none;background:none;padding:9px 10px;border-radius:10px;font:600 .85rem Inter,sans-serif;color:var(--muted);cursor:pointer;transition:all .15s}
.seg button:hover{color:var(--text)}
.seg button.on{background:var(--surface);color:var(--accent);box-shadow:0 1px 3px rgba(0,0,0,.1)}
.vbody{padding:20px}
.vin{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:18px}
.vin input{font:500 .95rem "JetBrains Mono",monospace;padding:7px 12px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--text);width:190px;outline:none}
.vin input:focus,textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 20%,transparent)}
.chip{font:500 .78rem "JetBrains Mono",monospace;border:1px solid var(--line);background:var(--surface);color:var(--muted);border-radius:99px;padding:4px 11px;cursor:pointer;transition:all .15s}
.chip:hover,.chip.on{color:var(--accent);border-color:var(--accent);background:var(--accent-soft)}
.stage{display:flex;flex-direction:column;gap:14px;min-height:120px}
.msg{margin-top:16px;padding:12px 16px;background:var(--soft);border-left:3px solid var(--accent);border-radius:0 10px 10px 0;font-size:.93rem;min-height:48px}
.ctrl{display:flex;gap:8px;align-items:center;margin-top:16px}
.btn{font:600 .85rem Inter,sans-serif;border:1px solid var(--line);background:var(--surface);color:var(--text);border-radius:10px;padding:7px 14px;cursor:pointer;transition:all .15s}
.btn:hover:not(:disabled){border-color:var(--accent);color:var(--accent)}
.btn:disabled{opacity:.35;cursor:default}
.btn.pri{background:linear-gradient(135deg,var(--accent-fill),var(--accent-2-fill));border-color:transparent;color:#fff;box-shadow:0 4px 14px color-mix(in srgb,var(--accent) 30%,transparent)}
.btn.pri:hover:not(:disabled){color:#fff;filter:brightness(1.08)}
.count{margin-left:auto;font:500 .8rem "JetBrains Mono",monospace;color:var(--muted)}
.viz details{border-top:1px solid var(--line);padding:0 20px}
.viz summary{padding:12px 0;font-size:.85rem;color:var(--muted);cursor:pointer}
.viz details table{border-radius:10px}
tr.cur td{background:var(--amber-soft)}

/* code + editor */
.code{margin:16px 0;border-radius:14px;background:var(--code-bg);overflow:hidden;border:1px solid var(--code-line);box-shadow:var(--shadow);transition:border-color .15s,box-shadow .15s}
.code.ed:focus-within{border-color:color-mix(in srgb,var(--accent) 65%,var(--code-line));box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 22%,transparent),var(--shadow)}
.code .bar{display:flex;align-items:center;gap:10px;padding:8px 12px;font:500 .75rem "JetBrains Mono",monospace;color:var(--code-dim);background:var(--code-bar);border-bottom:1px solid var(--code-line)}
.code .dots{display:flex;gap:6px;flex:none}
.code .dots i{width:10px;height:10px;border-radius:50%;background:#ff5f57}.code .dots i+i{background:#febc2e}.code .dots i+i+i{background:#28c840}
.code .fn{color:#c9d1d9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.code .mod{display:none;color:#fbbf24;font-size:.7rem;white-space:nowrap}
.code.dirty .mod{display:inline}
.code .sp{flex:1}
.code .ib{background:transparent;border:1px solid #2a3140;color:var(--code-dim);border-radius:7px;padding:2px 9px;cursor:pointer;font:inherit;transition:all .15s}
.code .ib:hover{color:#fff;border-color:#4b5563}
.sw{display:inline-flex;align-items:center;gap:7px;cursor:pointer;user-select:none;position:relative}
.sw input{position:absolute;opacity:0;width:1px;height:1px}
.sw .tr{width:30px;height:17px;border-radius:99px;background:#2a3140;position:relative;transition:background .2s;flex:none}
.sw .tr::after{content:"";position:absolute;top:2px;left:2px;width:13px;height:13px;border-radius:50%;background:#7d8590;transition:all .2s}
.sw input:checked+.tr{background:linear-gradient(135deg,#6366f1,#a855f7)}
.sw input:checked+.tr::after{left:15px;background:#fff}
.sw input:focus-visible+.tr{outline:2px solid #a5b4fc;outline-offset:2px}
.sw .sl{color:var(--code-dim)}
.sw input:checked~.sl{color:#c9d1d9}
.sw .sl::after{content:" off"}
.sw input:checked~.sl::after{content:" on"}
.code pre{margin:0;padding:12px 0;overflow-x:auto;font-size:.84rem;line-height:1.6;color:var(--code-text);counter-reset:l}
.code .ln{display:block;padding-right:16px}
.code .ln::before{counter-increment:l;content:counter(l);display:inline-block;width:2.8em;padding-right:1em;text-align:right;color:#3d4656;user-select:none}
.code .ln.hl{background:var(--code-hl);box-shadow:inset 2px 0 #a5b4fc}
.k{color:#c4b5fd}.s{color:#86efac}.cm{color:#8b949e;font-style:italic}.t{color:#fcd34d}.f{color:#93c5fd}.n{color:#fdba74}
.status{display:flex;justify-content:space-between;gap:12px;padding:4px 12px;font:500 .7rem "JetBrains Mono",monospace;color:var(--code-dim);background:var(--code-bar);border-top:1px solid var(--code-line);white-space:nowrap;overflow:hidden}
.status .doc{overflow:hidden;text-overflow:ellipsis}
.status .doc b{color:#a5b4fc;font-weight:600}

.code .CodeMirror{height:auto;background:var(--code-bg);color:var(--code-text);font:.84rem/1.65 "JetBrains Mono",ui-monospace,Consolas,monospace;padding:6px 0}
.code .CodeMirror-gutters{background:var(--code-bg);border-right:none}
.code .CodeMirror-linenumber{color:#3d4656;padding:0 14px 0 10px}
.code .CodeMirror-focused .CodeMirror-activeline-gutter .CodeMirror-linenumber{color:#9aa4b2}
.code .CodeMirror-cursor{border-left:2px solid #a5b4fc}
.code .CodeMirror-selected{background:rgba(129,140,248,.18)}
.code .CodeMirror-focused .CodeMirror-selected,.code .CodeMirror-line::selection,.code .CodeMirror-line>span::selection,.code .CodeMirror-line>span>span::selection{background:rgba(129,140,248,.32)}
.code .CodeMirror-activeline-background{background:transparent}
.code .CodeMirror-focused .CodeMirror-activeline-background{background:rgba(255,255,255,.035)}
.code .cm-hlline{background:var(--code-hl);box-shadow:inset 2px 0 #a5b4fc}
.cm-s-lesson .cm-keyword{color:#c4b5fd}.cm-s-lesson .cm-string,.cm-s-lesson .cm-string-2{color:#86efac}
.cm-s-lesson .cm-comment{color:#64748b;font-style:italic}.cm-s-lesson .cm-number,.cm-s-lesson .cm-atom{color:#fdba74}
.cm-s-lesson .cm-type,.cm-s-lesson .cm-variable-3{color:#fcd34d}.cm-s-lesson .cm-def{color:#93c5fd}
.cm-s-lesson .cm-variable{color:#e6edf3}.cm-s-lesson .cm-variable-2{color:#bfdbfe}.cm-s-lesson .cm-property{color:#93c5fd}
.cm-s-lesson .cm-operator{color:#94a3b8}.cm-s-lesson .cm-meta{color:#f9a8d4}.cm-s-lesson .cm-builtin{color:#fcd34d}
.cm-s-lesson .CodeMirror-matchingbracket{color:#fff!important;background:rgba(165,180,252,.28);border-radius:2px}
.cm-s-lesson .CodeMirror-nonmatchingbracket{color:#f87171!important}

/* suggestion popup */
.CodeMirror-hints.lesson{background:#10151e;border:1px solid #2a3140;border-radius:12px;box-shadow:0 16px 40px rgba(0,0,0,.45);padding:5px;font:.8rem "JetBrains Mono",ui-monospace,monospace;max-height:17em;min-width:280px;max-width:min(520px,92vw);z-index:60}
.CodeMirror-hints.lesson .CodeMirror-hint{color:#c9d1d9;border-radius:7px;padding:4px 8px;display:flex;align-items:center;gap:9px;white-space:nowrap;line-height:1.5}
.CodeMirror-hints.lesson li.CodeMirror-hint-active{background:linear-gradient(90deg,#2b2f6b,#25224d);color:#fff}
.hk{width:18px;height:18px;border-radius:5px;display:grid;place-items:center;font:700 .64rem Inter,sans-serif;flex:none}
.hk.m{background:#33295e;color:#c4b5fd}.hk.f{background:#1d3550;color:#93c5fd}.hk.v{background:#123d2c;color:#86efac}
.hk.k{background:#1e2a4a;color:#a5b4fc}.hk.t{background:#45360f;color:#fcd34d}.hk.s{background:#4a1d3a;color:#f9a8d4}
.hn{overflow:hidden;text-overflow:ellipsis}.hn b{color:#a5b4fc;font-weight:700}.hn i{color:#7d8590;font-style:normal}
.hd{margin-left:auto;padding-left:18px;color:#6b7686;font-size:.72rem}

/* tabs */
.tabs{display:flex;gap:4px;background:var(--soft);padding:5px;border-radius:12px;overflow-x:auto;margin-top:18px;border:1px solid var(--line)}
.tabs button{flex:1;min-width:110px;border:none;background:none;border-radius:9px;padding:9px;font:600 .85rem Inter,sans-serif;color:var(--muted);cursor:pointer;transition:all .15s}
.tabs button:hover{color:var(--text)}
.tabs button.on{background:var(--surface);color:var(--accent);box-shadow:0 1px 3px rgba(0,0,0,.1)}
.pane{display:none;padding-top:12px}.pane.on{display:block;animation:fade .25s ease}
@keyframes fade{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0}
.facts div{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:12px 14px;font-size:.82rem;color:var(--muted);box-shadow:var(--shadow)}
.facts b{display:block;font:600 1.05rem "JetBrains Mono",monospace;color:var(--text);margin-bottom:2px}

/* details */
details.d{border:1px solid var(--line);border-radius:12px;background:var(--surface);margin:8px 0;padding:0 16px;transition:box-shadow .15s,border-color .15s}
details.d:hover{border-color:color-mix(in srgb,var(--accent) 35%,var(--line))}
details.d[open]{box-shadow:var(--shadow)}
details.d>summary{list-style:none;cursor:pointer;padding:13px 0;font-weight:600;display:flex;gap:10px}
details.d>summary::-webkit-details-marker{display:none}
details.d>summary::before{content:"+";font:600 1rem "JetBrains Mono",monospace;color:var(--accent);width:14px;flex:none;transition:transform .2s}
details.d[open]>summary::before{content:"−"}
details.d>summary .q{color:var(--muted);font:600 .8rem "JetBrains Mono",monospace;flex:none;padding-top:2px}
details.d .b{padding:0 0 16px 24px}

/* chat */
.chat{display:flex;flex-direction:column;gap:8px}
.chat p{margin:0;padding:10px 14px;border-radius:14px;max-width:88%;background:var(--soft)}
.chat .me{align-self:flex-end;background:var(--accent-soft)}
.chat .who{display:block;font:600 .68rem "JetBrains Mono",monospace;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px}
.chat .iv .who{color:var(--amber)} .chat .me .who{color:var(--accent)}

/* playground */
.pg-tasks{display:flex;gap:6px;flex-wrap:wrap;margin:16px 0 4px}
#pg .CodeMirror-scroll{min-height:340px}
.keys{display:flex;gap:6px 16px;flex-wrap:wrap;font-size:.8rem;color:var(--muted);margin:10px 0}
.expect{border:1px solid var(--line);border-radius:12px;background:var(--surface);overflow:hidden;box-shadow:var(--shadow)}
.expect .eh{font:600 .72rem "JetBrains Mono",monospace;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);padding:8px 14px;background:var(--soft);border-bottom:1px solid var(--line)}
.expect pre{margin:0;padding:12px 14px;font-size:.85rem;color:var(--good);white-space:pre-wrap}
#pg textarea{font:.85rem/1.6 "JetBrains Mono",monospace;min-height:340px;background:var(--code-bg);color:var(--code-text);border:none;border-radius:0;margin:0}

/* revision */
.sheet{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.sheet div{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px;font-size:.9rem;box-shadow:var(--shadow)}
.sheet h4{margin:0 0 6px;font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:var(--accent)}
.sheet ul{margin:0}
.chk{display:grid;gap:6px}
.chk label{display:flex;gap:12px;padding:10px 14px;cursor:pointer;font-size:.95rem;border:1px solid var(--line);border-radius:12px;background:var(--surface);transition:all .15s}
.chk label:hover{border-color:color-mix(in srgb,var(--accent) 40%,var(--line))}
.chk label:has(input:checked){background:var(--good-soft);border-color:color-mix(in srgb,var(--good) 40%,var(--line))}
.chk input{accent-color:var(--accent);margin-top:6px}
.stars{display:flex;gap:2px}
.stars button{background:none;border:none;font-size:1.3rem;color:var(--line);cursor:pointer;padding:0 2px;transition:transform .1s}
.stars button:hover{transform:scale(1.15)}
.stars button.on{color:#f59e0b}
.rate{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--line);font-size:.95rem}
textarea{width:100%;min-height:90px;margin-top:14px;font:inherit;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--text);outline:none}
footer{padding:48px 0 90px;color:var(--muted);font-size:.85rem;text-align:center}

@media (max-width:620px){
  .wrap{padding:0 16px}
  .facts{grid-template-columns:1fr}
  .sheet{grid-template-columns:1fr}
  .row{grid-template-columns:1fr;gap:4px}
  .c{min-width:32px;height:38px;font-size:.95rem}.cw{min-width:32px}
  .code .dots,.sw .sl{display:none}
  .status .doc{display:none}
  section{padding:48px 0}
}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}}

/* pool visualizer */
.pool-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:16px}
.pcode{background:var(--code-bg);border-radius:12px;padding:10px 0;font:.8rem/1.9 "JetBrains Mono",monospace;color:var(--code-text);overflow-x:auto;border:1px solid var(--code-line)}
.pl{padding:0 14px 0 8px;white-space:pre;opacity:.4;transition:opacity .2s,background .2s}
.pl.done{opacity:1}
.pl.cur{background:var(--code-hl);box-shadow:inset 3px 0 #a5b4fc}
.pn{display:inline-block;width:1.8em;color:#3d4656;user-select:none}
.pmem{display:flex;flex-direction:column;gap:10px}
.area{border:1.5px dashed color-mix(in srgb,var(--accent) 45%,var(--line));border-radius:12px;padding:8px 10px;background:color-mix(in srgb,var(--accent-soft) 60%,transparent)}
.area.heap{border-color:var(--line);background:var(--soft)}
.ah{font:600 .68rem "JetBrains Mono",monospace;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-bottom:6px}
.objs{display:flex;flex-wrap:wrap;gap:8px;min-height:40px}
.pobj{display:flex;flex-direction:column;gap:1px;padding:6px 10px;border-radius:10px;background:var(--surface);border:1.5px solid var(--oc);min-width:96px;transition:transform .2s,box-shadow .2s}
.pobj.hot{transform:translateY(-2px);box-shadow:0 6px 18px color-mix(in srgb,var(--oc) 35%,transparent)}
.pobj b{font:600 .95rem "JetBrains Mono",monospace}
.oid{font:700 .65rem "JetBrains Mono",monospace;color:var(--oc)}
.refs{font:500 .7rem "JetBrains Mono",monospace;color:var(--muted)}
.vars{display:flex;flex-wrap:wrap;gap:6px}
.pvar{font:600 .74rem "JetBrains Mono",monospace;padding:3px 9px;border-radius:99px;border:1px solid var(--oc);color:var(--oc);background:var(--surface)}
.pvar.hot{background:var(--oc);color:#fff}
#poolviz table,#mx table{margin-top:12px}

/* method explorer */
.vin select{font:500 .88rem "JetBrains Mono",monospace;padding:7px 10px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--text);max-width:100%}
.vin input.arg{width:120px}
#mxargs{display:flex;gap:8px;flex-wrap:wrap}
#mxs{width:220px}
#mxout code{font-size:.85rem}

/* char inspector */
.cgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:8px}
.cu{display:flex;flex-direction:column;align-items:center;gap:1px;padding:8px 6px;border:1.5px solid var(--line);border-radius:12px;background:var(--surface)}
.cu.sur{border-color:var(--amber);background:var(--amber-soft)}
.cu .ci{font:500 .66rem "JetBrains Mono",monospace;color:var(--muted)}
.cu .cc{font:600 1.35rem/1.3 "JetBrains Mono",monospace}
.cu .cn{font:600 .8rem "JetBrains Mono",monospace;color:var(--accent)}
.cu .cx{font:500 .68rem "JetBrains Mono",monospace;color:var(--muted)}
.cu .ct{font:500 .62rem Inter,sans-serif;color:var(--muted);text-align:center}
@media (max-width:720px){.pool-grid{grid-template-columns:1fr}}

/* lesson 02 */
.band{margin:48px 0 0;padding:40px 28px;border-radius:22px;border:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 14%,var(--surface)),color-mix(in srgb,var(--accent-2) 12%,var(--surface)));box-shadow:var(--shadow)}
.band h2{font-size:2rem;margin-top:14px}
.diagram{background:var(--code-bg);color:var(--code-text);border:1px solid var(--code-line);border-radius:14px;padding:16px 18px;font-size:.82rem;line-height:1.6;overflow-x:auto;margin:16px 0}
.mem{display:grid;grid-template-columns:1fr 2fr 1fr;gap:10px;margin:18px 0}
.mcol{border:1px solid var(--line);border-radius:14px;background:var(--surface);padding:12px;box-shadow:var(--shadow)}
.mcol p{margin:6px 0 0}
.mh{font:600 .72rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);margin-bottom:8px}
.mh span{color:var(--muted);text-transform:none;letter-spacing:0;font-weight:500}
.mh.sm{color:var(--good)}
.mvar{font:600 .85rem "JetBrains Mono",monospace;padding:6px 10px;border:1px solid var(--line);border-radius:8px;margin:6px 0;background:var(--soft)}
.mvar i{color:var(--muted);font-style:normal;font-weight:400}
.mpool{border:1.5px dashed var(--good);background:var(--good-soft);border-radius:12px;padding:10px;margin-bottom:10px}
.mobj{font:600 .85rem "JetBrains Mono",monospace;padding:8px 10px;border-radius:10px;border:1.5px solid var(--good);background:var(--surface)}
.mobj.out{border-color:var(--amber);background:var(--amber-soft)}
.mobj.meta{border-color:var(--line);background:var(--soft);font-weight:500;font-size:.76rem;margin:6px 0}
.mby{display:block;font-weight:400;font-size:.72rem;color:var(--muted)}
.two{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:16px 0}
.card{border:1px solid var(--line);border-top:3px solid var(--accent);border-radius:14px;background:var(--surface);padding:14px 18px;font-size:.9rem;box-shadow:var(--shadow)}
.card.good{border-top-color:var(--good)}.card.bad{border-top-color:var(--bad)}
.card h4{margin:0 0 6px;font-size:.76rem;text-transform:uppercase;letter-spacing:.06em}
.card ul{margin:0}
.steps{counter-reset:st;list-style:none;padding:0}
.steps li{counter-increment:st;position:relative;padding:5px 0 5px 40px}
.steps li::before{content:counter(st);position:absolute;left:0;top:5px;width:26px;height:26px;border-radius:50%;background:var(--accent-soft);color:var(--accent);font:600 .8rem/26px "JetBrains Mono",monospace;text-align:center}
.timeline{border-left:2px solid var(--line);margin:14px 0 14px 8px;padding-left:20px}
.timeline div{position:relative;margin:0 0 14px}
.timeline div::before{content:"";position:absolute;left:-27px;top:7px;width:12px;height:12px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px var(--accent-soft)}
.timeline>div>b{display:block;font-family:"JetBrains Mono",monospace}
.timeline span{font-size:.92rem}
.spoil{display:inline-block;padding:1px 8px;border-radius:6px;background:var(--soft);color:transparent;text-shadow:0 0 8px var(--muted);cursor:pointer;user-select:none;transition:all .2s}
.spoil.show{color:var(--text);text-shadow:none;background:var(--good-soft);cursor:default;user-select:auto}
.mref sup{font:600 .62rem "JetBrains Mono",monospace;color:var(--accent);margin-left:1px}
.mref td:first-child{white-space:nowrap;font-weight:600}
.capctl{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:14px}
.capctl select,.capctl input{font:500 .85rem "JetBrains Mono",monospace;padding:7px 10px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--text)}
.capctl input{width:150px}
.capcells{display:flex;flex-wrap:wrap;gap:3px;min-height:30px}
.capcells .cb{width:24px;height:30px;display:grid;place-items:center;border:1.5px dashed var(--line);border-radius:6px;font:600 .8rem "JetBrains Mono",monospace}
.capcells .cb.on{border-style:solid;border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}
.capstat{display:flex;gap:18px;flex-wrap:wrap;margin-top:12px;font:500 .82rem "JetBrains Mono",monospace;color:var(--muted)}
.capstat b{color:var(--text)}
@media (max-width:720px){.mem,.two{grid-template-columns:1fr}.band{padding:28px 18px}}
/* lessons 03–04 */
.c.win{border-color:var(--good);background:var(--good-soft);color:var(--good)}
.c.miss{border-color:var(--bad);background:var(--bad-soft);color:var(--bad)}
.pt{white-space:nowrap}
.algo select{max-width:100%;font:500 .85rem Inter,sans-serif;padding:7px 10px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--text)}
.av-stage{min-height:84px;overflow-x:auto;padding:4px 0}
.av-vars{display:flex;gap:18px;flex-wrap:wrap;margin-top:10px;font:500 .82rem "JetBrains Mono",monospace;color:var(--muted)}
.av-vars b{color:var(--text)}
.av-vars:empty{display:none}
#aviz .av-in{width:230px}

/* redesign v2 */
html{scroll-padding-top:84px}
body{font-feature-settings:"cv02","cv03","cv04","cv11";text-rendering:optimizeLegibility}
::selection{background:color-mix(in srgb,var(--accent) 26%,transparent)}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:6px}
*{scrollbar-width:thin;scrollbar-color:color-mix(in srgb,var(--muted) 40%,transparent) transparent}
h2{font-size:1.85rem;letter-spacing:-.03em;font-weight:700}
h3{font-size:1.1rem;letter-spacing:-.01em}
section{padding:68px 0;border-top:none;position:relative}
section::before{content:"";position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--line) 15%,var(--line) 85%,transparent)}
.num{font-size:.7rem;padding:4px 10px;border:1px solid color-mix(in srgb,var(--accent) 25%,transparent);background:color-mix(in srgb,var(--accent-soft) 70%,transparent)}
h2 .anchor{margin-left:.35em;font-weight:500;color:var(--muted);text-decoration:none;opacity:0;transition:opacity .15s,color .15s}
h2:hover .anchor,h2 .anchor:focus-visible{opacity:1}
h2 .anchor:hover{color:var(--accent)}
p,li{text-wrap:pretty}
h1,h2,h3{text-wrap:balance}

/* hero */
header{padding:84px 0 56px;position:relative}
header::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
  background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:44px 44px;
  -webkit-mask-image:radial-gradient(60% 70% at 30% 20%,#000,transparent 75%);mask-image:radial-gradient(60% 70% at 30% 20%,#000,transparent 75%);opacity:.55}
h1{font-size:clamp(2.4rem,7vw,3.9rem);letter-spacing:-.045em}
.lessons{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:32px}
.lcard{position:relative;display:flex;flex-direction:column;gap:4px;padding:18px 20px 16px;border:1px solid var(--line);border-radius:16px;background:color-mix(in srgb,var(--surface) 88%,transparent);text-decoration:none;color:var(--text);box-shadow:var(--shadow);overflow:hidden;transition:transform .2s,border-color .2s,box-shadow .2s}
.lcard::before{content:"";position:absolute;inset:0 0 auto;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent-2));opacity:0;transition:opacity .2s}
.lcard:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--accent) 40%,var(--line));box-shadow:0 12px 32px color-mix(in srgb,var(--accent) 14%,transparent)}
.lcard:hover::before{opacity:1}
.lcard .ln{font:600 .7rem "JetBrains Mono",monospace;letter-spacing:.08em;color:var(--accent)}
.lcard b{font-size:1.05rem;letter-spacing:-.01em}
.lcard .d{font-size:.86rem;color:var(--muted);line-height:1.5}
.lcard i{font-style:normal;font:500 .72rem "JetBrains Mono",monospace;color:var(--muted);margin-top:6px}
.lcard .go{position:absolute;right:18px;top:16px;color:var(--muted);transition:transform .2s,color .2s}
.lcard:hover .go{transform:translateX(3px);color:var(--accent)}

/* lesson bands */
.band{position:relative;overflow:hidden;padding:48px 32px 40px;margin-top:72px;border-radius:24px}
.band::after{position:absolute;right:-6px;bottom:-34px;font:800 9.5rem/1 Inter,sans-serif;letter-spacing:-.06em;color:transparent;-webkit-text-stroke:1.5px color-mix(in srgb,var(--accent) 28%,transparent);pointer-events:none}
#deep::after{content:"02"}#probs::after{content:"03"}#arrays::after{content:"04"}
.band h2{font-size:2.3rem;letter-spacing:-.04em;position:relative}
.band p{position:relative;max-width:620px}

/* content blocks */
.note{position:relative;padding:13px 16px 13px 46px;border-left:none;border:1px solid color-mix(in srgb,var(--accent) 22%,var(--line));border-radius:14px}
.note::before{content:"i";position:absolute;left:15px;top:14px;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font:700 .72rem/1 "JetBrains Mono",monospace;color:#fff;background:linear-gradient(135deg,var(--accent-fill),var(--accent-2-fill))}
.note.warn{border:1px solid color-mix(in srgb,var(--bad) 28%,var(--line))}
.note.warn::before{content:"!";background:var(--bad)}
table{border-radius:14px;box-shadow:var(--shadow)}
tbody tr,table tr{transition:background .12s}
table tr:not(:first-child):hover td{background:color-mix(in srgb,var(--accent-soft) 45%,transparent)}
th{background:color-mix(in srgb,var(--soft) 80%,var(--surface))}
.card,.sheet div,.mcol,.facts div{border-radius:16px;transition:border-color .2s,transform .2s}
.card:hover,.sheet div:hover{border-color:color-mix(in srgb,var(--accent) 35%,var(--line))}
.viz{border-radius:18px}
.btn{border-radius:10px;transition:background .15s,border-color .15s,color .15s,transform .1s}
.btn:active:not(:disabled){transform:translateY(1px)}
details.d{border-radius:14px}
details.d>summary{display:block;position:relative;padding-left:26px}
details.d>summary .q{display:inline-block;margin-right:8px}
details.d>summary::before{content:"";position:absolute;left:3px;top:21px;width:8px;height:8px;margin:0;border-right:2px solid var(--accent);border-bottom:2px solid var(--accent);transform:rotate(-45deg);transition:transform .2s}
details.d[open]>summary::before{content:"";transform:rotate(45deg);top:18px}
details.d[open]>.b{animation:fade .25s ease}
.code{border-radius:16px}

/* sidebar contents */
#toc{display:none}
#tocBtn{display:none}
@media (min-width:1200px){
  body{padding-left:272px}
  nav{margin-left:-272px}
  nav .wrap{max-width:none;padding-left:24px;padding-right:24px}
  nav .links{display:none}
  nav .brand{margin-right:auto}  nav #courseSel{margin-right:auto}
  #toc{display:flex}
}
#toc{position:fixed;z-index:25;top:53px;left:0;bottom:0;width:272px;flex-direction:column;border-right:1px solid var(--line);background:color-mix(in srgb,var(--bg) 92%,transparent);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
