.fig figcaption{font-size:.9rem;color:var(--muted);line-height:1.6;margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}
.fig figcaption b{color:var(--text)}
.fig .zone{fill:var(--soft);stroke:var(--line);stroke-width:1.5}
.fig .zone.perm{fill:var(--amber-soft)}
.fig .pool{fill:var(--good-soft);stroke:var(--good);stroke-width:1.5;stroke-dasharray:6 4}
.fig .var{fill:var(--surface);stroke:var(--line);stroke-width:1.5}
.fig .obj{fill:var(--surface);stroke:var(--good);stroke-width:2}
.fig .obj.heap{stroke:var(--amber)}.fig .obj.acc{stroke:var(--accent)}.fig .obj.sm{stroke-width:1.5}
.fig .step{fill:var(--surface);stroke-width:1.5}.fig .step.g{stroke:var(--good)}.fig .step.h{stroke:var(--amber)}
.fig .cell{fill:var(--surface);stroke:var(--line);stroke-width:1.5}.fig .hdr{fill:var(--soft);stroke:var(--line);stroke-width:1.5}
.fig .cell.sh{stroke:var(--amber);fill:var(--amber-soft)}.fig .cell.nw{stroke:var(--accent);fill:var(--accent-soft)}
.fig .dot{fill:var(--accent)}
.fig .sep{stroke:var(--line);stroke-width:1.5;stroke-dasharray:4 5}
.fig .ft{fill:currentColor;font:600 13px "JetBrains Mono",ui-monospace,monospace}
.fig .fts{fill:currentColor;font:600 11.5px "JetBrains Mono",ui-monospace,monospace}
.fig .fs{fill:var(--muted);font:500 11px Inter,system-ui,sans-serif}
.fig .fst{fill:currentColor;font:600 12px Inter,system-ui,sans-serif}
.fig .fhd{fill:currentColor;font:700 12px "JetBrains Mono",ui-monospace,monospace}
.fig .zl{fill:var(--muted);font:700 10.5px Inter,system-ui,sans-serif;letter-spacing:.09em}
.fig .zl.g{fill:var(--good)}.fig .zl.v{fill:var(--accent)}
.fig .a{fill:none;stroke:var(--muted);stroke-width:1.7}
.fig .a.g{stroke:var(--good)}.fig .a.h{stroke:var(--amber)}.fig .a.ac{stroke:var(--accent)}.fig .a.no{stroke:var(--bad)}.fig .a.d{stroke-dasharray:5 4}
.fig .mg{fill:var(--good)}.fig .mh{fill:var(--amber)}.fig .ma{fill:var(--accent)}.fig .mn{fill:var(--muted)}
.fig .pok{fill:var(--good-soft);stroke:color-mix(in srgb,var(--good) 45%,transparent)}.fig .pno{fill:var(--bad-soft);stroke:color-mix(in srgb,var(--bad) 45%,transparent)}
.fig .mr{fill:var(--bad)}.fig .used{fill:var(--accent-soft);stroke:var(--accent);stroke-width:1.5}.fig .free{fill:none;stroke:var(--muted);stroke-width:1.2;stroke-dasharray:4 3}.fig .split{stroke:var(--line);stroke-width:1.2;stroke-dasharray:3 3}
.fig .rt{font:600 11.5px "JetBrains Mono",ui-monospace,monospace}.fig .rt.ok{fill:var(--good)}.fig .rt.no{fill:var(--bad)}
/* L3 figures */
.fig .win{fill:none;stroke:var(--accent);stroke-width:2.5}

/* learning layer: teaching blocks, quizzes, progress, review, search */
#found::after{content:"00"}#oop::after{content:"05"}
.tldr{margin:6px 0 18px;padding:14px 18px;border-radius:14px;background:linear-gradient(135deg,color-mix(in srgb,var(--accent-soft) 85%,transparent),color-mix(in srgb,var(--accent-soft) 35%,transparent));border:1px solid color-mix(in srgb,var(--accent) 22%,var(--line));font-size:.98rem}
.tldr>b:first-child{display:block;font:600 .68rem "JetBrains Mono",monospace;letter-spacing:.09em;text-transform:uppercase;color:var(--accent);margin-bottom:2px}
