.ia .iah::before{content:"";width:8px;height:8px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--accent-2))}
.ia>p{margin:0;padding:14px 18px 6px}
.ia .fu{padding:4px 18px 14px;font-size:.92rem}
.ia .fu>b{display:block;font-size:.78rem;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin:6px 0 2px}
.ia .fu li{color:var(--text)}
.takeaways{list-style:none;padding:0;counter-reset:tk;display:grid;gap:8px}
.takeaways li{counter-increment:tk;position:relative;margin:0;padding:10px 14px 10px 46px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.takeaways li::before{content:counter(tk);position:absolute;left:14px;top:11px;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font:700 .72rem/1 "JetBrains Mono",monospace;color:var(--accent);background:var(--accent-soft)}
/* quiz */
.quiz{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;margin:12px 0 4px}
.qhead{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;padding:12px 16px;border:1px solid var(--line);border-radius:14px;background:var(--surface);position:sticky;top:64px;z-index:5;box-shadow:var(--shadow)}
.qscore{font-size:.92rem;color:var(--muted)}.qscore b{color:var(--text);font-size:1.05rem}
.qbar{flex-basis:100%;height:4px;border-radius:4px;background:var(--soft);overflow:hidden}.qbar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--accent),var(--accent-2));transition:width .3s}
