.lcard .lp{display:block;height:4px;border-radius:4px;background:var(--soft);overflow:hidden;margin-top:8px}.lcard .lp i{display:block;height:100%;background:linear-gradient(90deg,var(--good),color-mix(in srgb,var(--good) 60%,var(--accent)))}
/* review hub */
.rq{display:grid;grid-template-columns:minmax(0,1fr);gap:8px}
.rq .ri{display:flex;flex-wrap:wrap;gap:8px 12px;align-items:center;padding:10px 14px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
