@property --ang{syntax:"<angle>";inherits:false;initial-value:0deg}
@keyframes gradflow{to{background-position:200% center}}
@keyframes rise{from{opacity:0;transform:translateY(.45em) rotate(2deg);filter:blur(6px)}to{opacity:1;transform:none;filter:none}}
@keyframes fadeup{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes beam{to{--ang:360deg}}
@keyframes marq{to{transform:translateX(-50%)}}
