#java-egg .steam-t{font:800 44px "Inter Tight",Inter,sans-serif;fill:#f97316;stroke:#fff;stroke-width:1.5;paint-order:stroke;opacity:0;animation:je-t 1s ease-out 1s both}
#java-egg .cup-t{font:800 20px "JetBrains Mono",monospace;fill:#7c2d12}
@keyframes je-in{from{opacity:0;translate:0 120px;scale:.6}}
@keyframes je-out{to{opacity:0;translate:0 -60px;scale:.9}}
@keyframes je-st{0%{stroke-dashoffset:160;opacity:0}20%{opacity:1}100%{stroke-dashoffset:-160;opacity:0}}
@keyframes je-t{from{opacity:0;translate:0 20px}}
@media (prefers-reduced-motion:reduce){#diwali,#diwaliLow,#xmas,#fest{display:none}}
