/* v16 inferno: while the fire rider's flames climb a tree its leaves glow ember-orange and the bark chars (after the .night rule, so it wins) */
:is(#jungle,#jungleL).burning{--jl0:#120402;--jl1:#2a0904;--jl2:#561306;--jl3:#9a2a08;--jl4:#ff8a2a;--jb0:#0b0503;--jb1:#1d0d06;--jb3:#3a1a0a;--jb2:#070302;--jw:#160904;z-index:69}

/* v17 Halloween roaming ghosts: a canvas behind the page content */
#hwg{position:fixed;inset:0;width:100vw;height:100vh;z-index:-1;pointer-events:none}
@media (prefers-reduced-motion:reduce){#hwg{display:none}}
@media print{#hwg{display:none!important}}

/* v19 GPU fire layer: between the haunted backdrop (#riderLow) and the 3D rider (same z, earlier in the DOM) */
#fireGL{position:fixed;inset:0;width:100vw;height:100vh;z-index:70;pointer-events:none}
@media print{#fireGL{display:none!important}}

/* v21 opening title card of the fire rider: flickers in like a film title, burns, fades */
.ride-title{position:fixed;left:0;right:0;top:38%;z-index:72;text-align:center;pointer-events:none;animation:rt-in 4.4s ease both}
.ride-title b{display:block;font:800 clamp(30px,6vw,86px)/1 "Inter Tight",Inter,sans-serif;letter-spacing:.32em;padding-left:.32em;background:linear-gradient(180deg,#fff7d6 0%,#ffc25a 42%,#e2470f 78%,#7a1606 100%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 22px rgba(255,110,20,.55))}
.ride-title i{display:block;margin-top:14px;font:500 clamp(11px,1.2vw,15px)/1 "JetBrains Mono",monospace;letter-spacing:.6em;padding-left:.6em;color:rgba(255,214,170,.75);font-style:normal;text-transform:uppercase}
@keyframes rt-in{0%{opacity:0;transform:scale(1.12)}10%{opacity:1}14%{opacity:.25}17%{opacity:1}21%{opacity:.6}24%,72%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.96) translateY(-14px)}}
@media (prefers-reduced-motion:reduce){.ride-title{display:none}}
.ride-title::before{content:"";position:absolute;left:0;right:0;top:-90px;bottom:-90px;z-index:-1;background:radial-gradient(ellipse 58% 56% at 50% 52%,rgba(4,4,10,.92),rgba(4,4,10,.62) 48%,transparent 74%)}

/* v22 scroll rider: reading progress along the bottom of the content column */
#scrollRider{position:fixed;bottom:8px;height:46px;z-index:40;pointer-events:none}
#scrollRider::before{content:"";position:absolute;left:-6px;right:-6px;bottom:2px;height:7px;border-radius:7px;background:rgba(8,8,16,.72);box-shadow:0 0 0 1px rgba(255,255,255,.06),0 4px 14px rgba(0,0,0,.45)}
#scrollRider .sr-trail{position:absolute;left:0;right:0;bottom:4px;height:3px;border-radius:3px;transform-origin:0 50%;background:linear-gradient(90deg,rgba(122,22,6,.0),#7a1606 8%,#e2470f 70%,#ffb347);box-shadow:0 0 10px rgba(255,110,20,.55),0 -2px 8px rgba(255,140,40,.35)}
#scrollRider .sr-trail i{position:absolute;left:0;right:0;bottom:2px;height:9px;background:repeating-linear-gradient(90deg,transparent 0 5px,rgba(255,170,60,.55) 5px 7px,transparent 7px 12px);-webkit-mask:linear-gradient(transparent,#000);mask:linear-gradient(transparent,#000);animation:sr-lick .5s linear infinite;opacity:.8}
@keyframes sr-lick{to{background-position:12px 0}}
#scrollRider .sr-bike{position:absolute;left:0;bottom:4px;width:62px;height:42px;will-change:transform;filter:drop-shadow(0 0 6px rgba(255,120,30,.55))}
#scrollRider .sr-bike svg{width:100%;height:100%;overflow:visible;transition:transform .25s}
#scrollRider.back .sr-bike svg{transform:scaleX(-1)}
#scrollRider .sr-w{transform-box:view-box}
#scrollRider.moving .sr-w{animation:sr-spin .35s linear infinite}
#scrollRider.back.moving .sr-w{animation-direction:reverse}
@keyframes sr-spin{to{transform:rotate(360deg)}}
#scrollRider .sr-fl{transform-box:fill-box;transform-origin:50% 100%;animation:sr-fl .3s ease-in-out infinite alternate}
@keyframes sr-fl{to{transform:scale(1.15,1.25) skewX(-8deg)}}
#scrollRider .sr-ex{opacity:0}#scrollRider.moving .sr-ex{opacity:1;animation:sr-fl .15s infinite alternate}
#scrollRider.fin .sr-bike{animation:sr-fin 1.4s ease}
@keyframes sr-fin{30%{filter:drop-shadow(0 0 22px rgba(255,150,40,1))}}
html.cine #scrollRider{opacity:0}
@media (max-width:700px){#scrollRider{display:none}}
@media print{#scrollRider{display:none!important}}
@media (prefers-reduced-motion:reduce){#scrollRider *{animation:none!important}}

/* v23 Memory Lab (reuses the runner's .rz-* look; an editable code pane on the left) */
#mlApp .ml-ex{display:flex;flex-wrap:wrap;gap:6px;margin:4px 0 12px}
.ml .rz-main{grid-template-columns:minmax(0,1fr) minmax(0,1.15fr)}
.ml-ed{position:relative;background:var(--code-bg);min-height:320px;overflow:hidden}
.ml-ed textarea{position:relative;z-index:1;display:block;width:100%;height:100%;min-height:320px;resize:vertical;margin:0;border:0;outline:0;background:transparent;color:#d6dbe7;caret-color:#fff;font:13px/1.75 "JetBrains Mono",monospace;padding:12px 14px 12px 52px;white-space:pre;overflow:auto;tab-size:4;font-variant-ligatures:none;box-sizing:border-box}
.ml-ed textarea:focus-visible{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--accent) 60%,transparent)}
.ml-gut{position:absolute;left:0;top:0;bottom:0;width:42px;overflow:hidden;padding-top:12px;font:13px/1.75 "JetBrains Mono",monospace;color:var(--code-dim);opacity:.92;text-align:right;pointer-events:none;user-select:none}
.ml-gut div{padding-right:10px}.ml-gut .cur{color:#fff}.ml-gut .err{color:#ff7b72}
.ml-bar{position:absolute;left:0;right:0;top:12px;height:22.75px;background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 38%,transparent),color-mix(in srgb,var(--accent) 10%,transparent));border-left:3px solid var(--accent);transition:transform .35s cubic-bezier(.2,.8,.2,1),opacity .2s;pointer-events:none;opacity:0}
.ml-bar.on{opacity:1}.ml-bar.err{background:rgba(255,80,80,.22);border-left-color:#ff5f57}
.ml .rz-v em{font-style:normal;color:var(--accent);opacity:.8;margin-right:5px;font-size:.72rem}
.ml .rz-v b.nul{color:var(--muted);font-weight:500}
.ml .rz-cells .rz-ref{display:inline-block;width:9px;height:9px}
.rz-o.garb{border-style:dashed;border-color:var(--bad);opacity:.6;animation:ml-garb .9s ease}
@keyframes ml-garb{40%{transform:scale(1.06) rotate(-2deg)}}
.ml .rz-msg.err{color:var(--bad);background:var(--bad-soft)}
@media (max-width:860px){.ml .rz-main{grid-template-columns:1fr}}

/* v23 Algorithm race */
#raceApp .rc-ctl{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center;margin:4px 0 12px;font-size:.86rem}
#raceApp label{display:flex;align-items:center;gap:6px;color:var(--muted)}
#raceApp select{font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:5px 8px}
.rc-sp input{width:110px;accent-color:var(--accent)}
.rc-lanes{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.rc-lane{border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden;transition:border-color .4s,box-shadow .4s,opacity .4s}
.rc-h{display:flex;flex-wrap:wrap;align-items:baseline;align-content:flex-start;gap:4px 10px;padding:10px 14px 6px;min-height:62px;box-sizing:border-box}
.rc-h b{font:700 1rem "Inter Tight",Inter,sans-serif}
.rc-o{font:500 .72rem "JetBrains Mono",monospace;color:var(--muted)}
.rc-win{margin-left:auto;font:700 .8rem Inter,sans-serif;color:#16a34a;opacity:0;transform:scale(.6);transition:.4s cubic-bezier(.2,1.4,.4,1)}
.rc-lane.won{border-color:#22c55e;box-shadow:0 0 0 3px rgba(34,197,94,.25),var(--shadow)}
.rc-lane.won .rc-win{opacity:1;transform:none}
.rc-lane.lost{opacity:.82}
.rc-lane canvas{display:block;width:calc(100% - 20px);height:190px;margin:0 10px}
.rc-ct{display:flex;flex-wrap:wrap;gap:6px 16px;padding:8px 14px;font:500 .78rem Inter,sans-serif;color:var(--muted);border-top:1px solid var(--line)}
.rc-ct b{font:700 .9rem "JetBrains Mono",monospace;color:var(--text)}
.rc-bar{height:3px;background:var(--line)}.rc-bar i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),var(--accent-2));transform-origin:0 50%;transform:scaleX(0)}
.rc-why{margin-top:12px;padding:12px 16px;border-radius:12px;background:var(--soft);border:1px solid var(--line);font-size:.92rem;min-height:44px}
.rc-why ul{margin:8px 0 6px;padding-left:20px}.rc-why li{margin:3px 0}
@media (max-width:760px){.rc-lanes{grid-template-columns:1fr}}

/* OOP labs v24 (Lesson 05 concept visualisations: #olObj #olInit #olAccess #olStatic #olFragile #olDispatch #olDiamond #olHash #olSealed #olRecord) */
/* .an hosts (Lesson 01 analogies, playground, #stBuild) use the same header (review 2026-11-03: it was unstyled there) */
.ol .ol-head,.an .ol-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 12px;padding:13px 20px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,color-mix(in srgb,var(--accent-soft) 70%,transparent),transparent)}
.ol .ol-head b,.an .ol-head b{font:700 .95rem "Inter Tight",Inter,sans-serif;color:var(--text)}
.ol .ol-head b::before{content:"◆ ";color:var(--accent)}
.ol .ol-head span,.an .ol-head span{font-size:.85rem;color:var(--muted)}
.ol h5{margin:0 0 8px;font:700 .66rem Inter,sans-serif;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}
.ol .ol-cmds{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:14px}
.ol .chip{font-size:.8rem}
.ol .chip:disabled{opacity:.35;cursor:default}
.ol .msg.err{border-left-color:var(--bad);background:var(--bad-soft)}
.ol .ol-empty{color:var(--muted);font-style:italic;font-size:.85rem;padding:8px 0}
.ol code.ol-stmt,.ol .ol-decl{display:block;font:600 .85rem "JetBrains Mono",monospace;background:var(--code-bg);color:#d6dbe7;padding:9px 14px;border-radius:10px;overflow-x:auto;white-space:pre;font-variant-ligatures:none}
.ol .ol-decl{margin-bottom:14px}
.ol-code{background:var(--code-bg);color:#d6dbe7;border-radius:10px;padding:8px 0;font:12.5px/1.7 "JetBrains Mono",monospace;overflow-x:auto;font-variant-ligatures:none}
.ol-code .ol-l{white-space:pre;padding:0 12px;border-left:3px solid transparent;transition:background .3s,border-color .3s,opacity .3s}
.ol-code .ol-l.cur{background:color-mix(in srgb,var(--accent) 30%,transparent);border-left-color:var(--accent-2)}
.ol-code .ol-l.skip{opacity:.4;text-decoration:line-through;background:rgba(255,255,255,.04)}
.ol .ol-tog{display:inline-flex;align-items:center;gap:6px;font-size:.85rem;padding:5px 10px;border:1px solid var(--line);border-radius:10px;background:var(--surface);cursor:pointer}
.ol .ol-tog select,.ol .ol-dsel select{font:500 .82rem "JetBrains Mono",monospace;padding:4px 6px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)}
.ol .ol-tog input{accent-color:var(--accent)}

/* object lab + static lab: stack/class column, heap column, arrows */
.ol-mem{position:relative;display:grid;grid-template-columns:minmax(0,190px) minmax(0,1fr);gap:56px;padding:14px;border:1px solid var(--line);border-radius:14px;background:var(--soft)}
.ol-mem.st{grid-template-columns:minmax(0,1fr) minmax(0,260px)}
.ol-arw{position:absolute;inset:0;pointer-events:none;overflow:visible;z-index:2}
.ol-arw path{fill:none;stroke:var(--accent);stroke-width:1.8;opacity:.85}
.ol-arw path.d{stroke-dasharray:5 4;stroke:var(--muted);opacity:.7}
.ol-arw marker path{fill:var(--accent);stroke:none;stroke-dasharray:none;opacity:1}
.ol-vars{display:flex;flex-direction:column;gap:10px}
.ol-var{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--line);border-radius:10px;background:var(--surface);font:600 .85rem "JetBrains Mono",monospace}
.ol-var b{font-size:.75rem;padding:2px 7px;border-radius:99px}
.ol-var b.ref{background:var(--accent-soft);color:var(--accent)}
.ol-var b.nul{background:var(--soft);color:var(--muted)}
.ol-heap{display:flex;flex-direction:column;align-items:flex-start;gap:10px;min-height:120px}
.ol-obj{display:flex;flex-direction:column;gap:2px;min-width:150px;padding:8px 12px;border:2px solid var(--good);border-radius:11px;background:var(--surface);font:600 .82rem "JetBrains Mono",monospace;transition:opacity .4s,border-color .4s,filter .4s}
.ol-obj small{font:600 .68rem Inter,sans-serif;color:var(--muted);margin-bottom:2px}
.ol-obj.gone{border-style:dashed;border-color:var(--muted);opacity:.55;filter:grayscale(1)}
.ol-obj.pop{animation:ol-pop .55s cubic-bezier(.2,1.4,.4,1)}
.ol-obj.sweep{animation:ol-sweep .6s ease-in forwards}
@keyframes ol-pop{from{transform:scale(.6);opacity:0}to{transform:none;opacity:1}}
@keyframes ol-sweep{to{transform:scale(.4) rotate(-8deg);opacity:0}}
.ol-row2{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;margin-top:14px}
.ol-log{background:var(--code-bg);border-radius:10px;padding:8px 12px;font:12.5px/1.7 "JetBrains Mono",monospace;color:#8b93a7;min-height:60px;overflow-x:auto;white-space:pre}
.ol-log .cur{color:#d6dbe7;background:color-mix(in srgb,var(--accent) 25%,transparent);margin:0 -12px;padding:0 12px}
.ol-eq{display:flex;flex-direction:column;gap:6px;justify-content:center}
.ol-eq div{display:flex;gap:10px;align-items:center;justify-content:space-between;font-size:.82rem}
.ol-eq b{font:700 .78rem "JetBrains Mono",monospace;padding:2px 8px;border-radius:99px}
.ol-eq b.ok{background:var(--good-soft);color:var(--good)}.ol-eq b.no{background:var(--bad-soft);color:var(--bad)}
.ol-cls{position:relative;display:flex;flex-direction:column;gap:4px;padding:10px 12px;border:2px solid var(--accent);border-radius:12px;background:var(--surface);font:600 .8rem "JetBrains Mono",monospace}
.ol-cls>small{font:700 .78rem "JetBrains Mono",monospace;color:var(--text);margin-bottom:2px}
.ol-cls .sf{padding:5px 8px;border-radius:8px;background:var(--amber-soft);border:1px solid color-mix(in srgb,var(--amber) 45%,transparent)}
.ol-cls .mt{padding:3px 8px;border-radius:7px;border:1px solid var(--line);font-weight:500;font-size:.76rem;transition:background .3s,border-color .3s,opacity .3s}

/* init order */
.ol-init{display:grid;grid-template-columns:repeat(2,minmax(0,1fr)) minmax(0,220px);gap:14px}
.ol-side .ol-build{opacity:.25;transition:opacity .4s;border-color:var(--accent);margin-bottom:12px}
.ol-side .ol-build.on{opacity:1}
.ol-build .pp,.ol-build .cp{padding:4px 8px;border-radius:7px;border:1px dashed var(--line);margin-top:4px;transition:all .4s}
.ol-build .done{border-style:solid;border-color:var(--good);background:var(--good-soft)}
.ol-con{margin:0;min-height:150px;background:var(--code-bg);color:#8b93a7;border-radius:10px;padding:8px 12px;font:12px/1.6 "JetBrains Mono",monospace;white-space:pre-wrap}
.ol-con .new{color:#facc15;display:inline-block}

/* access map */
.ol-world{position:relative;padding:28px 12px 12px;border:1.5px dashed var(--line);border-radius:16px}
.ol-zt{position:absolute;top:7px;left:12px;font:700 .64rem Inter,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.ol-pkgs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.ol-pkg{position:relative;display:flex;flex-direction:column;gap:10px;padding:28px 10px 10px;border:1.5px solid var(--line);border-radius:13px;background:var(--soft)}
.ol-acc{display:flex;flex-direction:column;gap:4px;padding:9px 11px;border:2px solid var(--line);border-radius:11px;background:var(--surface)}
.ol-acc small{font:600 .74rem "JetBrains Mono",monospace;color:var(--muted)}
.ol-acc code{align-self:flex-start}
.ol-acc .ol-res{font:600 .74rem "JetBrains Mono",monospace;line-height:1.45}
.ol-acc.yes{border-color:var(--good);animation:ol-flip .45s both}.ol-acc.yes .ol-res{color:var(--good)}
.ol-acc.noo{border-color:color-mix(in srgb,var(--bad) 60%,transparent);background:color-mix(in srgb,var(--bad-soft) 60%,var(--surface));animation:ol-flip .45s both}.ol-acc.noo .ol-res{color:var(--bad)}
@keyframes ol-flip{from{transform:perspective(500px) rotateX(70deg);opacity:.3}to{transform:none;opacity:1}}

/* fragile base class */
.ol-fr{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,200px);gap:18px}
.ol-stack{display:flex;flex-direction:column;gap:6px;min-height:230px}
.ol-fr-f{padding:7px 12px;border:1px solid var(--line);border-left:4px solid var(--muted);border-radius:9px;background:var(--surface);font:600 .8rem "JetBrains Mono",monospace;opacity:.7;transition:all .3s}
.ol-fr-f.top{opacity:1;box-shadow:var(--shadow);animation:ol-pop .4s cubic-bezier(.2,1.4,.4,1)}
.ol-fr-f.ours{border-left-color:var(--accent)}.ol-fr-f.jdk{border-left-color:var(--good)}
.ol-fr-f.ol-bad{border-left-color:var(--bad);background:var(--bad-soft)}
.ol-big{font:800 3.2rem/1 "Inter Tight",Inter,sans-serif;color:var(--accent);margin-bottom:14px}
.ol-big.ol-bad{color:var(--bad)}
.ol-set{display:flex;gap:6px;flex-wrap:wrap;min-height:30px;margin-bottom:14px}
.ol-set span{font:600 .8rem "JetBrains Mono",monospace;padding:3px 9px;border-radius:99px;background:var(--good-soft);color:var(--good);animation:ol-pop .4s}
.ol-set em{color:var(--muted);font-size:.85rem}
.ol-legend{display:flex;align-items:center;gap:6px;font-size:.78rem;color:var(--muted)}
.ol-legend i{width:12px;height:12px;border-radius:3px;display:inline-block}
.ol-legend i.ours{background:var(--accent)}.ol-legend i.jdk{background:var(--good);margin-left:8px}

/* dispatch simulator */
.ol-dsel{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:16px}
.ol-dsel code.ol-stmt{flex:1 1 100%}
.ol-dsel label{font-size:.82rem;color:var(--muted);display:inline-flex;gap:6px;align-items:center}
.ol-tree{display:flex;flex-direction:column;align-items:stretch;gap:4px;margin-bottom:16px}
.ol-tree .r1{display:grid;grid-template-columns:minmax(0,1fr);max-width:340px;width:100%;margin:0 auto}
.ol-tree .r2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;max-width:700px;width:100%;margin:0 auto}
.ol-ext{text-align:center;font:600 .68rem Inter,sans-serif;color:var(--muted);letter-spacing:.05em}
.ol-ext.l{max-width:700px;width:100%;margin:0 auto;text-align:left;padding-left:22%}
.ol-cls.dz{border-color:var(--line);transition:border-color .3s,box-shadow .3s,transform .3s}
.ol-cls.dz .tagd,.ol-cls.dz .tagr{display:none;position:absolute;top:-9px;font:700 .58rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;padding:2px 7px;border-radius:99px;color:#fff}
.ol-cls.dz .tagd{right:10px;background:var(--accent)}.ol-cls.dz .tagr{left:10px;background:var(--good)}
.ol-cls.dz.decl{border-color:var(--accent)}.ol-cls.dz.decl .tagd{display:block}
.ol-cls.dz.rt{border-color:var(--good)}.ol-cls.dz.rt .tagr{display:block}
.ol-cls.dz.decl.rt{border-color:var(--accent);box-shadow:0 0 0 3px var(--good-soft)}
.ol-cls.dz.scan{transform:translateY(-2px);box-shadow:0 8px 24px color-mix(in srgb,var(--amber) 25%,transparent)}
.ol-cls.dz .mt.fld{font-style:italic}.ol-cls.dz .mt.sta{border-style:dashed}
.ol-cls.dz .mt.look{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
.ol-cls.dz .mt.hit{background:var(--good-soft);border-color:var(--good);color:var(--good);animation:ol-pop .4s}
.ol-phases{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.ol-ph{padding:10px 12px;border:1px solid var(--line);border-radius:12px;background:var(--soft);opacity:.45;transition:opacity .3s,border-color .3s;font-size:.84rem;min-width:0}
.ol-ph>b{display:block;font:700 .68rem Inter,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:6px}
.ol-ph.on{opacity:1}.ol-ph.ol-ok{border-color:var(--good)}.ol-ph.ol-bad{border-color:var(--bad);background:var(--bad-soft)}
.ol-ph .st{margin:3px 0;animation:ol-in .35s both}.ol-ph .st.ol-ok{color:var(--good)}
.ol-ph .e{color:var(--bad);font:600 .8rem "JetBrains Mono",monospace}
.ol-ph code{word-break:break-word}
@keyframes ol-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}

/* default-method resolver + sealed checker */
.ol-dm{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:16px;align-items:start}
.ol-dm .ol-ph{opacity:1;margin-top:12px}
.ol-dmg{position:relative;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-areas:"a b base" ". c .";gap:28px 12px;padding:6px 0}
.ol-dmg .b{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-height:52px;border:2px solid var(--line);border-radius:12px;background:var(--surface);font:700 .9rem "JetBrains Mono",monospace;transition:all .35s}
.ol-dmg .b::after{content:attr(data-s);font:500 .66rem Inter,sans-serif;color:var(--muted)}
.ol-dmg .b[data-n="A"]{grid-area:a}.ol-dmg .b[data-n="B"]{grid-area:b}.ol-dmg .b[data-n="Base"]{grid-area:base}.ol-dmg .b[data-n="C"]{grid-area:c}
.ol-dmg .b:not(.cls){border-style:dashed}
.ol-dmg .b.off{opacity:.25}
.ol-dmg .b.win{border-color:var(--good);border-style:solid;background:var(--good-soft);color:var(--good);transform:scale(1.06)}
.ol-dmg .b.ol-bad{border-color:var(--bad);background:var(--bad-soft);color:var(--bad)}
.ol-dmg.ext .b[data-n="B"]::before{content:"extends A ◂";font:600 .6rem Inter,sans-serif;color:var(--accent)}
.ol-sh{padding:10px;border:1px solid var(--line);border-radius:12px;background:var(--soft)}
.ol-shr{font:700 .9rem "JetBrains Mono",monospace;text-align:center;margin-bottom:8px}
.ol-shr small{font:600 .68rem Inter,sans-serif;color:var(--muted)}
.ol-shk{display:flex;flex-wrap:wrap;gap:6px;justify-content:center}
.ol-shk span{font:600 .78rem "JetBrains Mono",monospace;padding:4px 10px;border-radius:9px;border:2px solid;transition:all .3s}
.ol-shk .cov{border-color:var(--good);background:var(--good-soft);color:var(--good)}
.ol-shk .mis{border-color:var(--bad);background:var(--bad-soft);color:var(--bad);animation:ol-pop .4s}
.ol-shk .defc{border-color:var(--amber);background:var(--amber-soft);color:var(--amber)}
.ol-shk .unk{border-style:dashed;border-color:var(--muted);color:var(--muted)}

/* hash buckets */
.ol-pt{font:600 .85rem "JetBrains Mono",monospace}
.ol-pt input{width:52px;font:600 .85rem "JetBrains Mono",monospace;padding:4px 6px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)}
.ol-calc{font-size:.84rem;min-height:1.6em;margin-bottom:10px;color:var(--muted)}
.ol-calc b{color:var(--text)}
.ol-buckets{display:grid;grid-template-columns:repeat(16,minmax(0,1fr));gap:4px}
.ol-bk{display:flex;flex-direction:column;gap:4px;min-height:96px;padding:4px 2px;border:1px solid var(--line);border-radius:8px;background:var(--soft);transition:border-color .3s,background .3s}
.ol-bk>span{font:600 .64rem "JetBrains Mono",monospace;color:var(--muted);text-align:center}
.ol-bk>div{display:flex;flex-direction:column;gap:3px}
.ol-bk i{font:600 .62rem/1.2 "JetBrains Mono",monospace;font-style:normal;text-align:center;padding:3px 1px;border-radius:5px;background:var(--surface);border:1px solid var(--good);animation:ol-pop .35s;overflow-wrap:anywhere}
.ol-bk i small{display:block;font-size:.56rem;color:var(--muted)}
.ol-bk i.hot{background:var(--amber-soft);border-color:var(--amber)}
.ol-bk.aim{border-color:var(--accent);background:var(--accent-soft)}
.ol-bk.miss{border-color:var(--bad);background:var(--bad-soft)}
.ol-size{margin-top:10px;font-size:.85rem;color:var(--muted)}

/* record expander */
.ol-rout .ol-code{max-height:360px;overflow:auto}

@media (max-width:760px){
  .ol-mem,.ol-mem.st{grid-template-columns:minmax(0,1fr);gap:22px}.ol-arw{display:none}
  .ol-init,.ol-fr,.ol-dm,.ol-phases,.ol-pkgs,.ol-row2{grid-template-columns:minmax(0,1fr)}
  .ol-tree .r2{gap:8px}.ol-buckets{grid-template-columns:repeat(8,minmax(0,1fr))}
}
@media (prefers-reduced-motion:reduce){.ol *{animation:none!important;transition:none!important}}
