/* tablets vs whiteboard */
.an-tabs{display:flex;flex-wrap:wrap;gap:6px;min-height:80px;align-content:flex-start}
.an-tab{font:700 .85rem "JetBrains Mono",monospace;padding:10px 12px 8px;border-radius:14px 14px 4px 4px;background:linear-gradient(#a8a29e,#78716c);color:#1c1917;box-shadow:inset 0 -3px 0 rgba(0,0,0,.25);min-width:44px;text-align:center}
.an-tab.old{opacity:.4;filter:grayscale(1);transform:rotate(-4deg) translateY(4px)}
.an-wb{min-height:80px;display:flex;align-items:center;padding:12px 16px;border-radius:8px;background:#fff;border:6px solid #cbd5e1;box-shadow:inset 0 0 0 1px #e2e8f0}
.an-wb span{font:700 1.3rem "Comic Sans MS","Segoe Print",cursive;color:#1d4ed8;letter-spacing:.06em}
.an-stat{margin-top:8px;font-size:.8rem;color:var(--muted)}
.an-stat b{color:var(--text)}
/* twins */
.an-people{display:flex;flex-wrap:wrap;gap:16px;justify-content:center;align-items:center;margin-bottom:14px;min-height:150px}
.an-person{display:flex;flex-direction:column;align-items:center;gap:4px;padding:12px 18px;border-radius:16px;border:2px solid var(--line);background:var(--surface);transition:all .3s}
.an-person.hot{border-color:var(--accent);box-shadow:0 0 0 4px var(--accent-soft)}
.an-person.talk{border-color:var(--good);box-shadow:0 0 0 4px var(--good-soft)}
.an-face{font-size:2.4rem;line-height:1}
.an-person b{font:700 .9rem "JetBrains Mono",monospace}
.an-tags{display:flex;gap:4px}.an-tags span{font:700 .72rem "JetBrains Mono",monospace;padding:2px 8px;border-radius:99px;background:var(--amber-soft);color:var(--amber);border:1px solid color-mix(in srgb,var(--amber) 45%,transparent)}
.an-note{font-size:.82rem;color:var(--muted);max-width:180px}
/* caterpillar */
.an-track{display:flex;flex-wrap:wrap;gap:3px;padding:16px 6px 8px}
.an-cell{position:relative;display:flex;flex-direction:column;align-items:center;width:38px;padding:7px 0 3px;border-radius:10px;font:700 1rem "JetBrains Mono",monospace;background:var(--soft);border:1px solid var(--line);transition:all .3s}
.an-cell small{font-size:.6rem;color:var(--muted);font-weight:500}
.an-cell.body{background:#86efac;border-color:#16a34a;color:#052e16;border-radius:16px}
.an-cell.body small{color:#166534}
.an-cell.head::after{content:"🐛";position:absolute;top:-14px;right:-6px;font-size:1.1rem;transform:scaleX(-1)}
.an-cell.tail{box-shadow:inset 4px 0 0 #15803d}
.an-cell.warn{background:var(--bad-soft);border-color:var(--bad);color:var(--bad)}
.an-best{font-size:.88rem;color:var(--muted)}.an-best b{color:var(--good)}
/* lockers */
.an-lockers{position:relative;padding:30px 4px 6px;overflow-x:auto}
.an-runner{position:absolute;top:2px;left:0;font-size:1.3rem;transition:transform .45s cubic-bezier(.4,0,.2,1)}
.an-lrow{display:flex;gap:4px}
.an-locker{flex:0 0 auto;display:flex;flex-direction:column;align-items:center;width:52px;padding:6px 0;border-radius:6px;background:linear-gradient(#94a3b8,#64748b);color:#f8fafc;border:2px solid #475569;transition:all .3s}
.an-locker small{font:700 .7rem "JetBrains Mono",monospace;background:#0f172a;padding:0 6px;border-radius:4px}
.an-locker b{font:800 1rem "JetBrains Mono",monospace;margin:4px 0;min-height:1.3em}
.an-locker em{font:500 .58rem "JetBrains Mono",monospace;font-style:normal;opacity:.8}
.an-locker.hot{background:linear-gradient(#a78bfa,#7c3aed);border-color:#5b21b6;transform:translateY(-4px)}
.an-locker.walked{background:linear-gradient(#fcd34d,#d97706);border-color:#92400e}
.an-locker.vac{background:var(--soft);border-style:dashed;border-color:var(--line);color:var(--muted)}
/* cinema */
.an-hall{padding:14px;border-radius:14px;background:linear-gradient(#111827,#1f2937);color:#e5e7eb}
.an-screen{margin:0 auto 18px;width:70%;text-align:center;font:700 .66rem Inter,sans-serif;letter-spacing:.3em;padding:4px;border-radius:0 0 50% 50%/0 0 100% 100%;background:linear-gradient(#e0f2fe,#7dd3fc);color:#0c4a6e}
.an-rows{display:flex;flex-direction:column;gap:6px;align-items:center}
.an-row{display:flex;gap:5px;align-items:center;padding:3px 6px;border-radius:10px;transition:background .3s}
.an-row.hot{background:rgba(167,139,250,.25)}
.an-rl{font:700 .7rem "JetBrains Mono",monospace;color:#cbd5e1;background:none;border:1px solid #475569;border-radius:6px;padding:3px 6px;cursor:pointer;min-width:52px}
.an-seat{width:34px;height:30px;border-radius:8px 8px 4px 4px;border:0;background:#dc2626;color:#fee2e2;font:700 .72rem "JetBrains Mono",monospace;cursor:pointer;box-shadow:inset 0 -5px 0 #991b1b;transition:transform .15s}
.an-seat:hover{transform:translateY(-2px)}
.an-seat.hot{background:#facc15;color:#422006;box-shadow:inset 0 -5px 0 #a16207}
/* guess */
.an-range{position:relative;height:46px;margin:22px 6px 10px;border-radius:10px;background:var(--soft);border:1px solid var(--line)}
.an-band{position:absolute;top:0;bottom:0;left:0;width:100%;border-radius:10px;background:var(--accent-soft);border:2px solid var(--accent);transition:left .5s,width .5s}
.an-pin{position:absolute;top:-16px;translate:-50% 0;font:800 .8rem "JetBrains Mono",monospace;padding:2px 7px;border-radius:7px;background:var(--text);color:var(--surface);transition:left .5s}
.an-pin:empty{display:none}
.an-guesses{display:flex;flex-wrap:wrap;gap:6px;font:600 .78rem "JetBrains Mono",monospace}
.an-guesses span{padding:3px 9px;border-radius:99px;background:var(--soft);border:1px solid var(--line)}
.an-guesses span.hit{background:var(--good-soft);border-color:var(--good);color:var(--good)}
/* town clock */
.an-town{display:flex;gap:18px;align-items:flex-end;flex-wrap:wrap;justify-content:center;padding:14px;border-radius:14px;background:linear-gradient(#e0f2fe,var(--soft));border:1px solid var(--line);margin-bottom:14px}
.an-tower{display:flex;flex-direction:column;align-items:center;padding:10px 16px 12px;border-radius:12px 12px 0 0;background:linear-gradient(#a8a29e,#78716c);color:#1c1917;min-width:120px}
.an-face2{font-size:2.2rem}
.an-tower b{font:800 1.2rem "JetBrains Mono",monospace;background:#fff;padding:0 8px;border-radius:6px}
.an-tower small{font:600 .66rem "JetBrains Mono",monospace;margin-top:4px}
.an-folk{display:flex;gap:10px;flex-wrap:wrap}
.an-folkp{display:flex;flex-direction:column;align-items:center;gap:2px;padding:8px 12px;border-radius:12px;background:var(--surface);border:2px solid var(--line);color:var(--text);transition:all .3s}
.an-folkp b{font:700 .8rem "JetBrains Mono",monospace}
.an-folkp span{font:700 .82rem "JetBrains Mono",monospace}
.an-folkp small{font-size:.68rem;color:var(--muted)}
.an-folkp.hot{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.an-folkp.look small{color:var(--good);font-weight:700}
/* strips */
.an-strip{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:baseline;margin:16px 0;padding:11px 16px;border-radius:12px;border:1px dashed color-mix(in srgb,var(--accent) 45%,var(--line));background:color-mix(in srgb,var(--accent-soft) 45%,transparent);font-size:.92rem}
.an-strip>b:first-child{font:700 .7rem "JetBrains Mono",monospace;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);white-space:nowrap}
@media (max-width:760px){.an-two,.an-three{grid-template-columns:minmax(0,1fr)}.an-cell{width:30px}.an-seat{width:26px}}
@media (prefers-reduced-motion:reduce){.an *{animation:none!important;transition:none!important}}
@media print{.an{display:none}}
.an h5.cd{text-transform:none;letter-spacing:0;font:600 .76rem "JetBrains Mono",monospace}
.an input[type=number],.an .an-cin{font:600 .85rem "JetBrains Mono",monospace;padding:5px 8px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)}

