html.no-motion .cr,html.no-motion .cr *{animation:none!important;transition:none!important}
html.no-motion .rz *{animation:none!important;transition:none!important}
html.no-motion .rz-arw path.new{stroke-dashoffset:0}
html.no-motion .ms-zzz i{animation:none;opacity:1}
