#motionBtn,#fxBtn{font-size:.95rem}
html.no-motion #motionBtn{color:var(--accent);border-color:var(--accent)}
html.no-motion *::before,html.no-motion *::after{animation:none!important;transition:none!important}

/* bubble sort lesson v28 (Lesson 06: .bs-lab Bubble Lab, #anValet, #bsStable, #bsInv, #bsChart, #bsRace) */
#bsort::after{content:"06"}
.bs-opts{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:14px}
.bs-opts .ol-tog b{font:600 .8rem "JetBrains Mono",monospace;min-width:1.6em}
.bs-opts input[type=range]{width:90px;accent-color:var(--accent)}
.bs-cu{font:500 .82rem "JetBrains Mono",monospace;padding:6px 10px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--text);width:190px;max-width:100%}
.bs-seg{border:1px solid var(--line);border-radius:12px;padding:4px;background:var(--soft)}
.bs-seg button{min-width:0}
.bs-main{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:16px;align-items:start}
.bs-stage{position:relative;padding:12px 10px 4px;border:1px solid var(--line);border-radius:14px;background:var(--soft)}
.bs-bars{position:relative;height:190px}
.bs-b{position:absolute;left:0;bottom:0;height:100%;width:calc(100% / var(--n));padding:0 3px;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;transition:transform .38s cubic-bezier(.45,0,.3,1)}
.bs-b b{order:-1;text-align:center;font:600 .74rem "JetBrains Mono",monospace;color:var(--muted);margin-bottom:3px;white-space:nowrap;overflow:hidden}
.bs-b i{display:block;border-radius:6px 6px 3px 3px;background:linear-gradient(180deg,var(--accent),var(--accent-2));opacity:.85;transition:background .25s,opacity .25s,box-shadow .25s}
.bs-b.hot i{background:#facc15;opacity:1;box-shadow:0 0 0 2px color-mix(in srgb,#facc15 40%,transparent)}
.bs-b.hot.bad i{background:#fb923c}
.bs-b.sw i{background:#ef4444;opacity:1}
.bs-b.waste i{background:repeating-linear-gradient(135deg,#ef4444 0 5px,color-mix(in srgb,#ef4444 45%,transparent) 5px 10px);opacity:1}
.bs-b.fin i{background:linear-gradient(180deg,#22c55e,#16a34a);opacity:.95}
.bs-b.hot b,.bs-b.sw b{color:var(--text)}
.bs-ptrs{position:relative;height:24px}
.bs-p{position:absolute;left:0;top:4px;width:calc(100% / var(--n));text-align:center;font:700 .74rem "JetBrains Mono",monospace;color:var(--accent);transition:transform .3s}
.bs-p::before{content:"▲";display:block;font-size:.55rem;line-height:1}
.bs-bound,.bs-lohi{position:absolute;bottom:20px;height:200px;border-left:2px dashed var(--accent-2);font:700 .62rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--accent-2);padding-left:4px;pointer-events:none}
.bs-lohi{border-left-style:dotted;border-color:var(--muted);color:var(--muted)}
.bs-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(96px,1fr));gap:8px;margin-top:10px}
.bs-stats div{padding:7px 10px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}
.bs-stats small{display:block;font:600 .66rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.bs-stats b{font:700 1rem "JetBrains Mono",monospace}
.bs-stats .bs-w b{color:#ef4444}
.bs-wtag{display:inline-block;font-size:.78rem;padding:1px 8px;border-radius:99px;background:color-mix(in srgb,#ef4444 15%,transparent);color:#ef4444}
.bs-stack{margin-top:10px;padding:10px;border:1px solid var(--line);border-radius:12px;background:var(--soft);max-height:220px;overflow:auto}
.bs-stack h5{margin:0 0 6px;font:700 .66rem Inter,sans-serif;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}
.bs-stack div{font:600 .78rem "JetBrains Mono",monospace;padding:4px 9px;margin-bottom:3px;border-radius:7px;border:1px solid var(--line);background:var(--surface)}
.bs-stack div.top{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}
.bs-vn{font:700 .85rem "Inter Tight",Inter,sans-serif;margin-bottom:6px}
.bs-code{max-height:380px;overflow:auto;font-size:11.5px}
.bs-tbl{margin-top:14px;max-height:280px;overflow:auto}
.bs-tbl td,.bs-tbl th{font-size:.82rem;padding:5px 10px}
.bs-tbl tr.cur td{background:var(--accent-soft)}
.bs-yes{color:#ef4444}
.bs-lab .ctrl{flex-wrap:wrap}
.bs-spd{display:inline-flex;align-items:center;gap:6px}
.bs-spd input{width:80px;accent-color:var(--accent)}
/* valet */
.bs-lane{position:relative;padding:14px 0 34px;border-radius:14px;background:repeating-linear-gradient(90deg,transparent 0 calc(20% - 2px),color-mix(in srgb,var(--muted) 40%,transparent) calc(20% - 2px) 20%),var(--soft);border:1px solid var(--line)}
.bs-cars{position:relative;height:84px}
.bs-car{position:absolute;left:0;top:0;width:20%;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;transition:transform .55s cubic-bezier(.45,0,.3,1)}
.bs-car>div{display:flex;justify-content:center}
.bs-car svg{width:100%;height:auto;display:block}
.bs-car small{font:600 .72rem "JetBrains Mono",monospace;color:var(--muted);margin-top:2px}
.bs-car.hot small{color:var(--text)}
.bs-car.hot>div{filter:drop-shadow(0 0 6px #facc15)}
.bs-car.sw>div{filter:drop-shadow(0 0 7px #ef4444)}
.bs-car.fin small{color:#16a34a;font-weight:700}
.bs-car.fin small::after{content:" ✓"}
.bs-valet{position:absolute;left:0;bottom:4px;width:20%;display:flex;flex-direction:column;align-items:center;transition:transform .45s cubic-bezier(.45,0,.3,1)}
.bs-valet svg{width:12px;height:20px;fill:var(--accent)}
.bs-valet span{font:700 .58rem Inter,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}
.bs-sign{position:absolute;right:8px;bottom:6px;font:800 .62rem Inter,sans-serif;letter-spacing:.12em;padding:2px 8px;border-radius:6px;background:#16a34a;color:#fff;opacity:0;transition:opacity .3s}
.bs-sign.on{opacity:1}
/* stability */
.bs-cards{position:relative;height:74px;margin:16px 0 10px}
.bs-card{position:absolute;left:0;top:0;width:calc(100% / var(--n));padding:0 4px;transition:transform .45s cubic-bezier(.45,0,.3,1)}
.bs-card b,.bs-card small{display:block;text-align:center}
.bs-card b{font:700 1.3rem "JetBrains Mono",monospace;padding:8px 0 2px;border:2px solid var(--c);border-bottom:none;border-radius:12px 12px 0 0;background:color-mix(in srgb,var(--c) 14%,var(--surface))}
.bs-card small{font:800 .72rem Inter,sans-serif;color:#fff;background:var(--c);border-radius:0 0 12px 12px;padding:2px 0}
.bs-card.tA{--c:#2a78d6}.bs-card.tB{--c:#eb6834}.bs-card.tC{--c:#1baf7a}
.bs-card.hot b{box-shadow:0 0 0 3px #facc15}
.bs-verdict{display:flex;flex-wrap:wrap;gap:8px;align-items:center;min-height:8px}
.bs-verdict p{flex-basis:100%;margin:4px 0 0}
.bs-ok,.bs-no{font:600 .82rem "JetBrains Mono",monospace;padding:3px 10px;border-radius:99px;background:color-mix(in srgb,#22c55e 15%,transparent);color:#16a34a}
.bs-no{background:color-mix(in srgb,#ef4444 15%,transparent);color:#ef4444}
/* inversions */
.bs-inv{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;align-items:start}
.bs-row{display:flex;gap:6px;flex-wrap:wrap}
.bs-row span{min-width:38px;text-align:center;padding:8px 0;font:700 1rem "JetBrains Mono",monospace;border:2px solid var(--line);border-radius:10px;background:var(--surface);transition:border-color .2s,background .2s}
.bs-row span.hot{border-color:#facc15}
.bs-row span.sw{border-color:#ef4444;background:color-mix(in srgb,#ef4444 12%,var(--surface))}
.bs-ic{margin-top:12px;font-size:.88rem}
.bs-grid{display:grid;gap:3px;justify-content:start}
.bs-gh,.bs-gc{font:600 .72rem "JetBrains Mono",monospace;color:var(--muted);display:flex;align-items:center;justify-content:center;height:28px}
.bs-cell{height:28px;border-radius:6px;border:1px solid var(--line);background:var(--surface);transition:background .3s,border-color .3s}
.bs-cell.off{visibility:hidden}
.bs-cell.on{background:#ef4444;border-color:#ef4444}
.bs-cell.gone{background:#22c55e;border-color:#22c55e}
/* chart */
#bsChart{--bs-s1:#2a78d6;--bs-s2:#eb6834;--bs-s3:#1baf7a;--bs-s4:#eda100;--bs-s5:#e87ba4;--bs-s6:#008300}
#bsChart.bs-dk{--bs-s1:#3987e5;--bs-s2:#d95926;--bs-s3:#199e70;--bs-s4:#c98500;--bs-s5:#d55181;--bs-s6:#008300}
.bs-legend{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}
.bs-lg{display:inline-flex;align-items:center;gap:6px;font:500 .78rem Inter,sans-serif;padding:4px 10px;border-radius:99px;border:1px solid var(--line);background:var(--surface);color:var(--muted);cursor:pointer}
.bs-lg i{width:14px;height:3px;border-radius:2px;background:var(--c)}
.bs-lg.on{color:var(--text);border-color:color-mix(in srgb,var(--c) 60%,var(--line))}
.bs-lg:not(.on) i{opacity:.3}
.bs-lg.ref{cursor:default}.bs-lg.ref i{background:none;border-top:2px dashed var(--muted);height:0}
.bs-plot{position:relative}
.bs-svg{display:block;width:100%;height:300px;touch-action:pan-y}
.bs-gl{stroke:var(--line);stroke-width:1}
.bs-ax,.bs-rl{fill:var(--muted);font:500 11px Inter,sans-serif}
.bs-rl{font-weight:600}
.bs-ref{fill:none;stroke:var(--muted);stroke-width:1.2;stroke-dasharray:4 4;opacity:.75}
.bs-line{fill:none;stroke-width:2;stroke-linejoin:round;stroke-linecap:round}
.bs-cross{stroke:var(--muted);stroke-width:1}
.bs-tip{position:absolute;top:8px;min-width:170px;padding:8px 10px;border-radius:10px;border:1px solid var(--line);background:var(--surface);box-shadow:var(--shadow);font-size:.78rem;pointer-events:none;z-index:2}
.bs-tip div{display:flex;align-items:center;gap:6px}
.bs-tip i{width:10px;height:3px;border-radius:2px}
.bs-tip span{margin-left:auto;font:600 .78rem "JetBrains Mono",monospace;padding-left:10px}
.bs-tip .r{color:var(--muted);margin-top:3px}
.bs-data{margin-top:10px}.bs-data summary{cursor:pointer;color:var(--muted);font-size:.85rem}
.bs-data table td,.bs-data table th{font-size:.78rem;padding:4px 8px}
/* race */
.bs-lanes{display:flex;flex-direction:column;gap:8px}
.bs-lane2{display:grid;grid-template-columns:minmax(0,210px) minmax(0,1fr);gap:12px;align-items:center;padding:8px 10px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.bs-lane2.won{border-color:#22c55e}
.bs-ln b{display:block;font:700 .85rem "Inter Tight",Inter,sans-serif}
