/* foundations labs v35 (Lesson 00: #fdPipe #fdKit #fdTypes #fdCast #fdFlow #fdOverload; classes fd-) */
.fd .fd-hooks{display:flex;flex-wrap:wrap;gap:6px;padding:12px 20px 0}
.fd .fd-hooks span{font-size:.79rem;padding:4px 10px;border-radius:99px;background:var(--soft);border:1px solid var(--line)}
.fd .fd-hooks b{color:var(--accent)}
.fd .fd-lbl{font:600 .8rem "JetBrains Mono",monospace;color:var(--muted)}
.fd .msg{margin-top:12px}
.fd .fd-console{margin-top:12px;background:var(--code-bg);border-radius:10px;padding:8px 12px;font:12.5px/1.7 "JetBrains Mono",monospace;color:#8b93a7;font-variant-ligatures:none}
.fd .fd-console span{display:block;opacity:.7}
.fd .fd-out{color:#d6dbe7;min-height:1.7em}
/* pipeline */
.fd-pipe{display:flex;flex-direction:column;gap:14px}
.fd-row{padding:12px;border-radius:14px;background:var(--soft);border:1px solid var(--line)}
.fd-track{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:10px;align-items:center}
.fd-card{border:2px solid var(--line);border-radius:12px;background:var(--surface);padding:10px 12px;opacity:.45;transition:all .35s;min-width:0}
.fd-card b{font:700 .9rem "JetBrains Mono",monospace;display:block;margin-bottom:6px}
.fd-card pre{margin:0 0 6px;background:var(--code-bg);color:#d6dbe7;border-radius:8px;padding:8px 10px;font:12px/1.55 "JetBrains Mono",monospace;overflow-x:auto;font-variant-ligatures:none}
.fd-card.cls pre{color:#fde68a}
.fd-card small{font-size:.74rem;color:var(--muted)}
.fd-arr{display:flex;flex-direction:column;align-items:center;opacity:.4;transition:opacity .35s;padding:0 4px}
.fd-arr span{font:700 .82rem "JetBrains Mono",monospace;padding:3px 10px;border-radius:99px;background:var(--accent-fill);color:#fff}
.fd-arr i{font-style:normal;font-size:1.6rem;line-height:1.2;color:var(--accent)}
.fd-arr em{font-size:.7rem;color:var(--muted);font-style:normal;white-space:nowrap}
.fd-machs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.fd-mach{border:2px solid var(--line);border-radius:12px;background:var(--surface);padding:10px 12px;opacity:.45;transition:all .35s;text-align:center;min-width:0}
.fd-mach b{display:block;font-size:.92rem}
.fd-mach span{display:inline-block;margin-top:6px;font:700 .72rem "JetBrains Mono",monospace;padding:2px 9px;border-radius:99px;background:var(--accent-soft);color:var(--accent)}
.fd-mach em{display:none;margin-top:6px;font:600 .7rem Inter,sans-serif;font-style:normal;color:var(--good)}
.fd-mach.jit em{display:block}
.fd-stages{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.fd-stage{border:2px solid var(--line);border-radius:12px;background:var(--surface);padding:9px 10px;opacity:.45;transition:all .35s;min-width:0}
.fd-stage b{display:block;font-size:.86rem}
.fd-stage small{font-size:.72rem;color:var(--muted)}
.fd-pipe [data-k].on{opacity:1}
.fd-pipe [data-k].hot{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.fd-pipe .fd-arr.hot span{box-shadow:0 0 0 3px var(--accent-soft)}
.fd-heat{display:grid;grid-template-columns:auto minmax(0,1fr) auto auto;gap:10px;align-items:center;margin-top:12px;font-size:.82rem;color:var(--muted);opacity:.5;transition:opacity .3s}
.fd-heat.on{opacity:1}
.fd-bar{height:10px;border-radius:99px;background:var(--line);overflow:hidden}
.fd-bar i{display:block;height:100%;width:0;border-radius:99px;background:linear-gradient(90deg,#60a5fa,#f59e0b,#ef4444);transition:width .9s cubic-bezier(.2,.8,.2,1)}
.fd-heat b{font:700 .85rem "JetBrains Mono",monospace;color:var(--text);min-width:5ch;text-align:right}
.fd-heat em{font-style:normal;font-weight:600;font-size:.74rem;padding:2px 8px;border-radius:99px;background:var(--soft);border:1px solid var(--line)}
.fd-heat.hot em{background:var(--bad-soft);color:var(--bad);border-color:transparent}
.fd-mem{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:12px}
.fd-mem div{border:2px dashed var(--line);border-radius:12px;padding:8px 10px;text-align:center;min-width:0}
.fd-mem.hot div{border-color:var(--accent);border-style:solid}
.fd-mem b{display:block;font-size:.86rem}.fd-mem small{font-size:.72rem;color:var(--muted)}
/* nested kit */
.fd-nest{padding:4px 0}
.fd-box{border:2px solid var(--line);border-radius:16px;padding:12px 14px;background:var(--surface);cursor:pointer;transition:all .3s;outline:none}
.fd-box.jre{margin-top:10px;background:var(--soft)}
.fd-box.jvm{margin-top:10px;background:var(--surface)}
.fd-box>b{font:800 1rem "Inter Tight",Inter,sans-serif}
.fd-box>small{margin-left:8px;font-size:.78rem;color:var(--muted)}
.fd-tools{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}
.fd-tools span{font:600 .74rem "JetBrains Mono",monospace;padding:2px 8px;border-radius:7px;background:var(--code-bg);color:#d6dbe7}
.fd-box.on{border-color:var(--accent);box-shadow:0 0 0 4px var(--accent-soft)}
.fd-box:focus-visible{border-color:var(--accent)}
.fd-who .chip.on,.fd-asks .chip.on,.fd-cases .chip.on,.fd-calls .chip.on,.fd [data-d].on{background:var(--accent-soft);color:var(--accent);border-color:color-mix(in srgb,var(--accent) 55%,var(--line))}
/* types */
.fd-bars{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px;margin-bottom:12px}
.fd-tbar{display:grid;grid-template-columns:auto minmax(0,1fr);gap:2px 10px;align-items:center;text-align:left;padding:8px 10px;border:2px solid var(--line);border-radius:12px;background:var(--surface);color:var(--text);cursor:pointer;font:inherit;transition:all .25s}
.fd-tbar b{font:700 .9rem "JetBrains Mono",monospace;grid-row:span 2}
.fd-tbar small{font-size:.7rem;color:var(--muted)}
.fd-bits{display:block;height:9px;border-radius:99px;background:var(--line);position:relative;overflow:hidden}
.fd-bits i{position:absolute;left:0;top:0;bottom:0;width:calc(var(--w) / 64 * 100%);border-radius:99px;background:linear-gradient(90deg,var(--accent),var(--accent-2,var(--accent)))}
.fd-bits.none i{background:repeating-linear-gradient(90deg,var(--muted) 0 3px,transparent 3px 6px);opacity:.6}
.fd-tbar.on{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.fd-tgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px}
.fd-tgrid div{padding:8px 10px;border-radius:10px;background:var(--soft);border:1px solid var(--line);min-width:0}
.fd-tgrid small{display:block;font:700 .62rem Inter,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:2px}
.fd-tgrid b{font-weight:600;font-size:.86rem;overflow-wrap:anywhere}
.fd-why{margin-top:10px;padding:8px 12px;border-radius:10px;background:var(--good-soft);border-left:3px solid var(--good);font-size:.88rem}
.fd-tinfo{margin-bottom:16px}
/* cast */
.fd-conv{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:10px;align-items:stretch;margin-top:4px}
.fd-val{border:2px solid var(--line);border-radius:14px;background:var(--surface);padding:10px 12px;min-width:0;display:flex;flex-direction:column;gap:4px}
.fd-val small{font:700 .7rem "JetBrains Mono",monospace;color:var(--muted)}
.fd-val b{font:700 1.15rem "JetBrains Mono",monospace;overflow-wrap:anywhere}
.fd-bitrow{display:flex;flex-wrap:wrap;gap:2px;margin-top:4px}
.fd-bitrow:empty{display:none}
.fd-bitrow i{font:700 .62rem "JetBrains Mono",monospace;font-style:normal;width:11px;padding:2px 0;text-align:center;border-radius:3px;background:var(--line);color:var(--muted)}
.fd-bitrow i.on{background:#22c55e;color:#052e16}
.fd-bitrow i.cut{opacity:.3;text-decoration:line-through}
.fd-pipe2{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-width:96px;position:relative}
.fd-pipe2 i{display:block;width:60px;height:14px;border-radius:99px;background:var(--accent);opacity:.9;clip-path:polygon(0 50%,15% 0,100% 0,100% 100%,15% 100%)}
.fd-conv.narrow .fd-pipe2 i{clip-path:polygon(0 0,85% 0,100% 50%,85% 100%,0 100%);background:var(--bad)}
.fd-conv.wrap .fd-pipe2 i{background:#f59e0b;border-radius:50%;width:16px;clip-path:none}
.fd-conv.int .fd-pipe2 i,.fd-conv.hidden .fd-pipe2 i{background:var(--muted)}
.fd-pipe2 span{font:600 .7rem Inter,sans-serif;color:var(--muted);text-align:center}
.fd-conv.wide .fd-val.to{border-color:var(--good)}
.fd-conv.narrow .fd-val.to,.fd-conv.wrap .fd-val.to{border-color:var(--bad)}
/* switch ladder */
.fd-ladder{position:relative;display:flex;flex-direction:column;gap:8px;padding:4px 0 4px 26px;margin-top:4px}
.fd-case{display:flex;flex-wrap:wrap;align-items:center;gap:8px 14px;padding:9px 12px;border:2px solid var(--line);border-radius:12px;background:var(--surface);transition:all .3s}
.fd-case code{font:600 .86rem "JetBrains Mono",monospace;min-width:7ch}
.fd-case .fd-do{font:500 .82rem "JetBrains Mono",monospace;color:var(--muted)}
.fd-case .fd-brk{margin-left:auto;display:inline-flex;align-items:center;gap:5px;font:600 .76rem Inter,sans-serif;padding:3px 9px;border-radius:8px;border:1px dashed var(--line);background:var(--soft);color:var(--muted);cursor:pointer}
.fd-case .fd-brk:has(input:checked){border-style:solid;border-color:#b45309;background:#fef3c7;color:#92400e}
.fd-case em.fd-brk{visibility:hidden}
.fd-case.on{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,var(--surface))}
.fd-case .fd-arrowk{display:none}
