/* ui polish v38 (2026-10-24): accessible tokens per theme (text colours ≥ 4.5:1 on bg/surface/soft), *-fill tokens (the darker
   solids that carry white text on chips, buttons and badges in every theme), --hi (the inset top highlight of raised controls),
   stroke icons in the nav, the course menu (.csw, replaces the native select), restrained buttons and chips.
   Prompt, audit and results: kb/site/style-audit-plan.md. */
:root{--accent-fill:#4f46e5;--accent-2-fill:#9333ea;--good-fill:#047857;--bad-fill:#c81e1e;--amber-fill:#b45309;--hi:rgba(255,255,255,.6)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--hi:rgba(255,255,255,.06)}}
:root[data-theme="dark"],:root[data-theme="midnight"],:root[data-theme="forest"],:root[data-theme="nord"],:root[data-theme="dracula"]{--hi:rgba(255,255,255,.06)}
:root[data-theme="light"],:root[data-theme="sunset"],:root[data-theme="ocean"],:root[data-theme="sepia"]{--hi:rgba(255,255,255,.6)}
:root[data-theme="forest"]{--accent-fill:#15803d;--accent-2-fill:#4d7c0f}
:root[data-theme="nord"]{--accent-fill:#4c6a94;--accent-2-fill:#8a5f8a;--good-fill:#4f7d3a;--bad-fill:#bf4a52;--amber-fill:#8a6a2a}
:root[data-theme="dracula"]{--accent-fill:#7c3aed;--accent-2-fill:#c026d3;--good-fill:#15803d;--amber-fill:#a16207}
:root[data-theme="sunset"]{--accent-fill:#be123c;--accent-2-fill:#c2410c;--good-fill:#15803d;--amber-fill:#c2410c}
:root[data-theme="ocean"]{--accent-fill:#0e7490;--accent-2-fill:#1d4ed8;--amber-fill:#a3470a}
:root[data-theme="sepia"]{--accent-fill:#8f4a26;--accent-2-fill:#8a6508;--good-fill:#456d0c;--bad-fill:#b42318;--amber-fill:#7f5500}
/* nav: quiet icon buttons, one search pill, the course menu */
nav .wrap{gap:4px}
nav button{margin-left:2px;width:32px;height:32px;border:1px solid transparent;background:transparent;color:var(--muted);border-radius:9px;font-size:1rem;box-shadow:none;transition:background .15s,color .15s,border-color .15s}
nav button:hover{background:var(--soft);color:var(--text);border-color:var(--line)}
nav button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
nav button svg{width:18px;height:18px;display:block}
nav button[aria-pressed="true"]:not(#fxBtn){color:var(--text)}
#fxBtn:not(.fx-on){opacity:.6;filter:grayscale(1)}
#cmdBtn{width:auto;height:32px;padding:0 6px 0 9px;gap:7px;margin-left:6px;margin-right:2px;border-color:var(--line);background:var(--surface);color:var(--muted);box-shadow:0 1px 2px rgba(15,23,42,.05),inset 0 1px 0 var(--hi)}
#cmdBtn:hover{color:var(--text);background:var(--surface);border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
#cmdBtn em{font:600 .64rem "JetBrains Mono",monospace;font-style:normal;color:var(--muted);padding:1px 6px;border-radius:6px;background:var(--soft);border:1px solid var(--line)}
nav .brand.sel{margin-right:0}nav .brand.sel span{display:none}
.csw{position:relative;flex:none;margin:0 8px 0 -2px}
nav .csw-b,.csw-b{display:inline-flex;align-items:center;gap:4px;width:auto;height:30px;margin:0;padding:0 6px 0 8px;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--text);font:700 .85rem Inter,sans-serif;cursor:pointer;transition:background .15s,border-color .15s}
nav .csw-b svg,.csw-b svg{width:14px;height:14px;color:var(--muted);transition:transform .2s}
.csw-b:hover,.csw-b[aria-expanded="true"]{background:var(--soft);border-color:var(--line)}
.csw-b[aria-expanded="true"] svg{transform:rotate(180deg)}
.csw-b:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.csw-m{position:absolute;left:0;top:calc(100% + 8px);min-width:260px;white-space:nowrap;padding:6px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:0 20px 50px -16px rgba(0,0,0,.4),0 2px 10px rgba(0,0,0,.08);z-index:70;transform-origin:top left;animation:csw-in .16s cubic-bezier(.2,.8,.2,1)}
.csw-m[hidden]{display:none}
@keyframes csw-in{from{opacity:0;transform:translateY(-4px) scale(.98)}to{opacity:1;transform:none}}
.csw-m a{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:9px;color:var(--text);text-decoration:none}
.csw-m a:hover,.csw-m a:focus-visible{background:var(--soft);outline:none}
.csw-m a i{flex:none;width:30px;height:30px;border-radius:9px;display:grid;place-items:center;font:700 .8rem "JetBrains Mono",monospace;font-style:normal;color:#fff;background:linear-gradient(135deg,var(--accent-fill),var(--accent-2-fill))}
.csw-m a i.k-sql{background:linear-gradient(135deg,#0f766e,#1d4ed8)}
.csw-m a i.k-spring{background:linear-gradient(135deg,#15803d,#0d9488)}
.k-hub{background:var(--soft);color:var(--muted);border:1px solid var(--line)}
.csw-m a i svg{width:16px;height:16px}
.csw-m a span{display:flex;flex-direction:column;line-height:1.25;min-width:0}
.csw-m a b{font:600 .86rem Inter,sans-serif}
.csw-m a small{font:500 .72rem Inter,sans-serif;color:var(--muted)}
.csw-m a>svg{margin-left:auto;width:16px;height:16px;color:var(--accent);opacity:0}
.csw-m a.on>svg{opacity:1}
.csw-h{font:600 .64rem Inter,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);padding:8px 10px 4px;margin-top:4px;border-top:1px solid var(--line)}
@media (max-width:620px){nav .brand{margin-right:0}.csw{margin-right:auto}}
/* buttons and chips: a raised neutral, a quiet ghost, one primary */
.btn{border:1px solid color-mix(in srgb,var(--line) 70%,var(--muted) 30%);background:var(--surface);color:var(--text);box-shadow:0 1px 2px rgba(15,23,42,.06),inset 0 1px 0 var(--hi)}
.btn:hover:not(:disabled){color:var(--text);border-color:color-mix(in srgb,var(--muted) 55%,var(--line));background:var(--soft)}
.btn.ghost{background:transparent;box-shadow:none;border-color:color-mix(in srgb,var(--line) 70%,transparent);color:var(--muted)}
.btn.ghost:hover:not(:disabled){background:var(--soft);color:var(--text);border-color:var(--line)}
.btn.pri,.btn.pri:hover:not(:disabled){color:#fff;background:linear-gradient(180deg,color-mix(in srgb,var(--accent-fill) 86%,#fff),var(--accent-fill) 55%,color-mix(in srgb,var(--accent-fill) 78%,var(--accent-2-fill)));border-color:color-mix(in srgb,var(--accent-fill) 82%,#000);box-shadow:inset 0 1px 0 rgba(255,255,255,.22),0 1px 2px rgba(0,0,0,.18),0 8px 20px -10px var(--accent-fill)}
.btn.pri:hover:not(:disabled){filter:brightness(1.06);box-shadow:inset 0 1px 0 rgba(255,255,255,.25),0 2px 4px rgba(0,0,0,.18),0 12px 26px -10px var(--accent-fill)}
.btn:focus-visible,.chip:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.chip{border-color:color-mix(in srgb,var(--line) 75%,var(--muted) 25%);background:var(--surface);color:var(--muted);box-shadow:inset 0 1px 0 var(--hi)}
.chip:hover{color:var(--text);border-color:var(--muted);background:var(--soft)}
.chip.on,.chip.on:hover{color:var(--accent);border-color:color-mix(in srgb,var(--accent) 55%,var(--line));background:var(--accent-soft);box-shadow:none}
footer .credits,footer .credits a{color:var(--muted);opacity:1}
#totop{color:var(--muted)}

/* ux pass v39 (2026-10-24): reading measure, body type, a three-size button system, touch targets, focus rings, editor
   type, mobile rhythm, skip link. Prompt and findings: kb/site/ux-pass-plan.md. */
@media (min-width:900px){body{font-size:17px}}
/* measure: prose is capped, visuals/code/tables/cards stay full width */
.wrap>section>p,.wrap>section>ul,.wrap>section>ol,section>p,section>ul,section>ol,.note,details.d,.band p,.b>p,.b>ul,.b>ol{max-width:72ch}
section>ul,section>ol{padding-left:1.3em}
li{margin:.25em 0}
p+p{margin-top:.8em}
h2{margin-top:.2em}
h3{margin-top:1.8rem}
/* buttons: sm 32 (toolbars, labs), md 38 (default), lg 46 (hero, pager) */
.btn{min-height:38px;padding:7px 16px;border-radius:10px;display:inline-flex;align-items:center;justify-content:center;gap:7px;white-space:nowrap;line-height:1.2}
.btn.big{min-height:46px;padding:11px 22px;border-radius:12px;font-size:.98rem}
.btn.sm,.rz-ctl .btn,.viz .btn,.ia .btn,.ol .btn,.bs-lab .btn,.fd .btn,.sq .btn,.cl .btn,.an .btn{min-height:32px;padding:4px 12px;border-radius:8px;font-size:.8rem}
.code .ib{min-height:28px;padding:3px 10px;border-radius:7px;display:inline-flex;align-items:center;gap:5px;white-space:nowrap}
