/* nav link strip reads as scrollable */
nav .links{-webkit-mask-image:linear-gradient(90deg,transparent,#000 12px,#000 calc(100% - 18px),transparent);mask-image:linear-gradient(90deg,transparent,#000 12px,#000 calc(100% - 18px),transparent);padding:0 4px}
/* mobile rhythm */
@media (max-width:480px){
