/* content: long tokens wrap, framed tables/figures with scroll shadows, 12px type floor, responsive roadmap + hero window, landscape-phone heroes, fluid large-screen column and type */
/* prose: long identifiers (ConcurrentModificationException, java.util.…) wrap inside their box instead of widening the page */
section>:is(p,ul,ol,h2,h3,h4,h5),.note,.tldr,details.d>summary,details.d>.b,.takeaways,.fig figcaption,.band>:is(h2,p),header>:is(h1,.lead),.lx-grid,.qq,.card,.sheet div,.ia>p,.ia .fu{overflow-wrap:break-word}
.secnext>span:nth-child(2){flex:1 1 0;min-width:0;overflow-wrap:break-word}
/* type floor: labels people read are 12px (eyebrows, chips, counters, table heads) */
.tag,.num,.secnext .sn-n,.secnext small,.lv,.qn,.qopt .qk,.tldr>b:first-child,.lx-grid h5,.lx-start summary span,.ia .iah,.sheet h4,.lcard .ln,.lcard i,.rmap .st,.rmap li>span:first-child,.hw-oh,.hw-run,.hw-tabs button,.mref sup{font-size:.75rem}
section>:is(p,ul,ol) kbd,.note kbd,.tldr kbd,.lead kbd,.lx-grid kbd{font-size:.75rem}
.card h4 code,.lx-grid h5 code,.lcard .d code{font-size:1em}
td sup{font-size:.82em}
.hw-note{font-size:.8rem}.hw-note code{font-size:.94em}
/* "In 30 seconds" box: same right edge as notes and prose (78ch at its .98rem ≈ 72ch of body text) */
.tldr{max-width:78ch}
/* eyebrow pill: a 14px radius reads as a pill on one line and stays tidy when it wraps on small phones */
.tag{border-radius:14px;max-width:100%;text-wrap:balance;line-height:1.45}
/* tables: the frame moves to the scroller, so a wide table scrolls inside rounded corners; edge shadows (pure CSS,
   local/scroll backgrounds built from tokens) appear only on a side that has more to show */
:is(section,.b)>.tw{margin:16px 0;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);overflow-x:auto;overscroll-behavior-x:contain;
  background:linear-gradient(90deg,var(--surface) 35%,transparent) left/36px 100% no-repeat local,linear-gradient(270deg,var(--surface) 35%,transparent) right/36px 100% no-repeat local,
    radial-gradient(farthest-side at 0 50%,color-mix(in srgb,var(--muted) 55%,transparent),transparent) left/16px 100% no-repeat scroll,radial-gradient(farthest-side at 100% 50%,color-mix(in srgb,var(--muted) 55%,transparent),transparent) right/16px 100% no-repeat scroll,var(--surface)}
:is(section,.b)>.tw>table{margin:0;border:0;border-radius:0;box-shadow:none;background:transparent;overflow:visible}
:is(section,.b)>.tw th{font-size:.75rem;background:color-mix(in srgb,var(--soft) 82%,transparent)}
:is(section,.b)>.tw th code{font-size:1em;text-transform:none;letter-spacing:0}
:is(section,.b)>.tw .cx{white-space:nowrap}
/* columns never collapse to a word per line: tables of up to 5 columns everywhere, every table where it scrolls (≤760) */
:is(section,.b)>.tw>table:not(:has(tr>:nth-child(6))) td{min-width:7.5em}
@media (max-width:760px){:is(section,.b)>.tw td{min-width:7.5em}}
/* figures: SVGs keep a legible minimum width (760-unit viewBox at 680px renders 10.5px labels at 9.4px) and scroll on narrow screens */
.fig svg{min-width:680px}
.fig .sv{overscroll-behavior-x:contain;
  background:linear-gradient(90deg,var(--surface) 35%,transparent) left/36px 100% no-repeat local,linear-gradient(270deg,var(--surface) 35%,transparent) right/36px 100% no-repeat local,
    radial-gradient(farthest-side at 0 50%,color-mix(in srgb,var(--muted) 55%,transparent),transparent) left/16px 100% no-repeat scroll,radial-gradient(farthest-side at 100% 50%,color-mix(in srgb,var(--muted) 55%,transparent),transparent) right/16px 100% no-repeat scroll,var(--surface)}
@media (max-width:480px){
  .fig{padding:14px 0 12px}
  .fig .sv{margin:0;padding:0 14px}
  .fig figcaption{margin:12px 14px 0}
}
/* where scroll-driven animations exist (and motion is allowed), a figure that scrolls also fades out at the edge that
   has more to show, so the cue is visible even over the drawing's opaque boxes; inactive when nothing overflows */
@property --sv-l{syntax:"<length>";inherits:false;initial-value:0px}
@property --sv-r{syntax:"<length>";inherits:false;initial-value:0px}
@keyframes sv-edge{from{--sv-l:0px;--sv-r:44px}8%{--sv-l:44px}92%{--sv-r:44px}to{--sv-l:44px;--sv-r:0px}}
@supports (animation-timeline:scroll()){
  @media (prefers-reduced-motion:no-preference){
    html:not(.no-motion) .fig .sv{-webkit-mask-image:linear-gradient(90deg,transparent,#000 var(--sv-l),#000 calc(100% - var(--sv-r)),transparent);mask-image:linear-gradient(90deg,transparent,#000 var(--sv-l),#000 calc(100% - var(--sv-r)),transparent);animation:sv-edge linear both;animation-timeline:scroll(self inline)}
  }
}
