  body>.wrap header .lead{font-size:calc(var(--fz)*1.082);max-width:34em}
  body>.wrap :is(.tag,.num,.qn,.lv,.secnext small,.secnext .sn-n,.tldr>b:first-child,.lx-start summary span,.lx-grid h5,.ia .iah,.lcard .ln,.lcard i,.rmap .st,.rmap li>span:first-child,.hw-bar,.hw-oh){font-size:calc(var(--fz)*.706)}
  body>.wrap :is(section>:is(p,ul,ol),.note,.tldr,.lead,.lx-grid) kbd,body>.wrap :is(.card,.sheet) h4,body>.wrap :is(section,.b)>.tw th,body>.wrap .qopt .qk{font-size:calc(var(--fz)*.706)}
  body>.wrap h2{font-size:calc(var(--fz)*1.741)}
  body>.wrap .band h2{font-size:calc(var(--fz)*2.165)}
  body>.wrap section h3{font-size:calc(var(--fz)*1.035)}
  body>.wrap .tldr{font-size:calc(var(--fz)*.922)}
  body>.wrap details.d>summary .q{font-size:calc(var(--fz)*.753)}
  body>.wrap :is(section,.b)>.tw>table,body>.wrap .qscore,body>.wrap .ia .fu{font-size:calc(var(--fz)*.866)}
  body>.wrap :is(.fig figcaption,.card,.sheet div,.rmap li){font-size:calc(var(--fz)*.847)}
  body>.wrap .secnext b{font-size:calc(var(--fz)*.941)}body>.wrap .secnext .sn-go{font-size:calc(var(--fz)*1.129)}
  body>.wrap .qopt{font-size:calc(var(--fz)*.885)}body>.wrap .qe{font-size:calc(var(--fz)*.875)}
