.ol-ph code,.ol-calc code{font-size:.75rem}
.olf-gauge,.olf-key,.olf-acts .chip,.olf-parts span,.olf-bay code{font-size:.75rem}
.ol-acc small,.ol-acc .ol-res{font-size:.78rem}
.ol-dmg.ext .b[data-n="B"]::before{font-size:.6875rem}
.ol-zt{top:6px}.ol-pkg,.ol-world{padding-top:30px}
/* hash buckets: readable keys; 8 columns until the column is wide, 4 on phones */
.ol-bk>span,.ol-bk i,.ol-bk i small{font-size:.75rem}
.ol-bk i{padding:3px 2px}
/* colour swatches */
.olf-sw{flex-wrap:wrap}
/* init order: the two classes side by side, the object and the console under them */
.ol-init{grid-template-columns:repeat(2,minmax(0,1fr))}
.ol-side{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:auto 1fr;grid-auto-flow:column;column-gap:14px}
.ol-side .ol-build{margin-bottom:0}
/* default-method resolver + sealed checker: source on top until there is room for both */
@media (max-width:860px){.ol-dm{grid-template-columns:minmax(0,1fr)}.ol-buckets{grid-template-columns:repeat(8,minmax(0,1fr))}}
/* the four pillars: tabs as a 2 × 2 grid on phones */
@media (max-width:620px){
  #olStory>.seg{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));overflow:visible}
  #olStory>.seg button{min-width:0}
  .ol-init{grid-template-columns:minmax(0,1fr)}
  .ol-side{display:block}
  .ol-side .ol-build{margin-bottom:12px}
}
@media (max-width:480px){
