  /* the two role pills on the narrow class boxes: 11 px uppercase, the only text under 12 px in these labs */
  .ol-cls.dz .tagd,.ol-cls.dz .tagr{font-size:.6875rem;letter-spacing:.02em;padding:2px 6px}
  .ol-cls.dz .tagd{right:6px}.ol-cls.dz .tagr{left:6px}
}

