.bs-b b,.bs-p,.bs-car small,.bs-card small,.bs-gh,.bs-gc,.bs-ln em,.bs-cells small,.bs-bk small,.bsx-tier,.lp-n,.mv-c small,.mv-glass small,.bs-auxp h5,.bsx-two h5,.bsx-sel span{font-size:.75rem}
