.bs-cells em{top:-11px}.bs-tn small{top:calc(100% + 1px)}
.bs-stats small,.bsx-cost small{font-size:.75rem;letter-spacing:.03em}
.bs-stats{grid-template-columns:repeat(auto-fit,minmax(120px,1fr))}
#bsPath .lp-top .btn{white-space:normal;text-align:left;max-width:100%}
/* lab tables fit the column instead of forcing the page-wide 480 px minimum */
