/* trees: never shrink the labels below 9 px; scroll sideways (with edge shadows) instead. Same shadows on lab tables that still scroll */
:is(#clCmp,.bs-lab,#bsChart,#cxLoops,#cxGrow) .tw,.cl-tree,.cl-heap{background:linear-gradient(90deg,var(--surface) 30%,transparent) left/28px 100% no-repeat local,linear-gradient(270deg,var(--surface) 30%,transparent) right/28px 100% no-repeat local,radial-gradient(farthest-side at 0 50%,color-mix(in srgb,var(--text) 22%,transparent),transparent) left/12px 100% no-repeat scroll,radial-gradient(farthest-side at 100% 50%,color-mix(in srgb,var(--text) 22%,transparent),transparent) right/12px 100% no-repeat scroll}
#clNav .cl-tree svg{min-width:calc(var(--vbw,504) * .75px)}
#clHeap .cl-heap svg{min-width:360px}
@media (max-width:860px){.cl-tab{grid-template-columns:repeat(min(var(--cols,16),8),minmax(0,1fr))}}
