.pg-lk-glass .pg3 :is(.btn.pri,.ib.pg-play),.pg-lk-glass .pg-gal .btn.pri{background:linear-gradient(135deg,var(--accent-fill),var(--accent-2-fill));border-color:color-mix(in srgb,#fff 22%,transparent);color:#fff;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.3),0 0 0 4px color-mix(in srgb,var(--accent) 14%,transparent),0 10px 28px -8px color-mix(in srgb,var(--accent) 75%,transparent)}
.pg-lk-glass .pg3 :is(.btn.pri,.ib.pg-play):hover:not(:disabled){filter:brightness(1.1);color:#fff}
