:root[data-theme="dark"],:root[data-theme="midnight"],:root[data-theme="nord"],:root[data-theme="dracula"],:root[data-theme="forest"]{--mv-swap:#a5b4fc;--mv-create:#fbbf24;--mv-wrap:#5eead4;--mv-talk:#f9a8d4;--mv-compose:#c4b5fd}
