.dp-pat-i{margin:0 0 4px;line-height:1.55}
.dp-pat-i b{font:700 .66rem "JetBrains Mono",monospace;letter-spacing:.08em;text-transform:uppercase;color:var(--mv,var(--accent));margin-right:6px}
.dp-pat-r{margin:0;color:var(--muted)}
.dp-pat-r a{color:var(--accent)}
.dp-lv{display:inline-block;font:700 .66rem "JetBrains Mono",monospace;letter-spacing:.06em;text-transform:uppercase;padding:3px 8px;border-radius:99px;margin:0 0 6px;vertical-align:middle}
.dp-lv.l1{background:var(--good-soft);color:var(--good)}.dp-lv.l2{background:var(--accent-soft);color:var(--accent)}
