pre.dp-spring{position:relative;margin:12px 0;padding:28px 14px 12px;background:var(--code-bg);color:var(--code-text);border:1px solid var(--code-line);border-radius:12px;font:12.5px/1.6 "JetBrains Mono",monospace;overflow:auto}
pre.dp-spring::before{content:"Spring · not runnable here";position:absolute;top:7px;left:14px;font:600 .64rem "JetBrains Mono",monospace;letter-spacing:.06em;color:var(--code-dim)}
