.sqs-bar .btn.warn{border-color:var(--bad);color:var(--bad);background:var(--bad-soft)}
.sqs-sp{flex:1}
.sqs-mode{display:inline-flex;padding:3px;border-radius:999px;background:var(--surface);border:1px solid var(--line)}
