.sqs-plan,.sqs-plan ul{list-style:none;margin:0;padding:0}
.sqs-plan{margin-top:10px}
.sqs-plan ul{padding-left:22px;border-left:2px solid var(--line);margin-left:10px}
.sqs-plan li>span{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px;margin:4px 0;padding:7px 10px;border-radius:10px;border:1px solid var(--line);background:var(--surface)}
.sqs-plan li>span i{font-style:normal}
.sqs-plan li>span code{font-size:.8rem}
.sqs-plan li>span em{font-style:normal;font-size:.74rem;color:var(--muted)}
.sqs-plan li.scan>span{border-color:color-mix(in srgb,var(--amber) 50%,var(--line));background:var(--amber-soft)}
.sqs-plan li.seek>span{border-color:color-mix(in srgb,var(--good) 50%,var(--line));background:var(--good-soft)}
