.sqs-plan li.temp>span{border-color:color-mix(in srgb,var(--accent) 40%,var(--line));background:var(--accent-soft)}
.sqs-hist{list-style:none;margin:0 0 12px;padding:0;display:flex;flex-direction:column;gap:4px}
.sqs-hist li{display:flex;gap:6px;align-items:stretch}
.sqs-star{border:1px solid var(--line);background:var(--surface);border-radius:8px;width:30px;cursor:pointer;color:var(--muted);flex:none}
.sqs-star.on{color:var(--amber);border-color:var(--amber)}
.sqs-load{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;text-align:left;border:1px solid var(--line);background:var(--soft);border-radius:8px;padding:6px 10px;cursor:pointer;color:var(--text)}
.sqs-load:hover{border-color:var(--accent)}
.sqs-load code{font-size:.78rem;white-space:pre-wrap;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical}
.sqs-load em{font-style:normal;font-size:.7rem;color:var(--muted)}
.sqs-er{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--soft)}
.sqs-er svg{display:block;max-width:100%;height:auto}
.sqs-er-box{fill:var(--surface);stroke:var(--line);stroke-width:1.5}
.sqs-er-hd{fill:var(--accent-soft)}
.sqs-er-name{font:700 13px "JetBrains Mono",monospace;fill:var(--text)}
.sqs-er-n{font:600 10px Inter,sans-serif;fill:var(--muted)}
.sqs-er-c{font:500 11.5px "JetBrains Mono",monospace;fill:var(--text)}
.sqs-er-c.pk{font-weight:700}.sqs-er-c.fk{fill:var(--accent)}
.sqs-er-ty{font:500 9.5px Inter,sans-serif;fill:var(--muted)}
.sqs-er-l{fill:none;stroke:var(--accent);stroke-width:1.6;opacity:.55;transition:opacity .2s,stroke-width .2s}
.sqs-er-ah{fill:var(--accent)}
.sqs-er svg.hov .sqs-er-l{opacity:.12}
