.sqs-er-t:hover .sqs-er-box{stroke:var(--accent)}
.sqs-ed .bar{flex-wrap:wrap;row-gap:6px}
.sqs-ed .bar .fn{white-space:nowrap;flex:none}
.sqs-ed .bar [data-x="viz"]{color:var(--accent)}
.sqs-safe{padding:9px 14px;border-bottom:1px solid var(--line);background:var(--amber-soft);font-size:.85rem}
.sqs-pane[data-p="viz"] .sqv{margin:0;box-shadow:none}
.sqs-pane[data-p="viz"]{max-height:none}
.sqs-erbar{display:flex;align-items:center;gap:6px;margin-bottom:8px}
.sqs-erbar .btn{padding:4px 12px;font-size:.8rem;min-width:36px}
