@media (max-width:560px){.sqs-bar .sqs-sp{display:none}.sqs-state{order:9;flex-basis:100%}}
@media (prefers-reduced-motion:reduce){.sqs-er-l,.sqs-t summary::before{transition:none}}

/* sql s00 v3 (2026-10-30): Lesson S00 labs, classes sq0- (labs-sql-s00.js). v3: #sqEngine index toggle + rows-read table/index walk, #sq00Race lanes, 3-column M:N in #sqRel, wider sales grid in #sqModels */
.sq0-vs{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.sq0-side{border:1px solid var(--line);border-radius:14px;padding:12px;background:var(--soft);min-width:0}
