.sq0-cyl{position:relative;display:flex;flex-direction:column;align-items:center;gap:2px;min-width:180px;max-width:100%;padding:18px 16px 14px;border:2px solid var(--accent);border-radius:50%/16px;background:var(--accent-soft);text-align:center;font:500 .8rem "JetBrains Mono",monospace}
.sq0-cyl b{font:700 .72rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--accent)}
.sq0-db.ok .sq0-cyl{border-color:var(--good);background:var(--good-soft)}
.sq0-db.bad .sq0-cyl{border-color:var(--bad);background:var(--bad-soft)}
.sq0-depts{display:flex;gap:6px;flex-wrap:wrap;justify-content:center}
