.sq0-depts span::before{content:"↑ "}
.sq0-dbx{font:600 .78rem Inter,sans-serif;color:var(--muted);text-align:center}
.sq0-db.ok .sq0-dbx{color:var(--good)}
.sq0-probs{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}
.sq0-probs span{font:600 .74rem Inter,sans-serif;padding:4px 10px;border-radius:99px;border:1px solid var(--line);color:var(--muted);transition:all .3s}
.sq0-probs span.seen{color:var(--text);border-color:var(--good);background:var(--good-soft)}
.sq0-probs span.on{color:#fff;background:var(--accent-fill);border-color:transparent}
.sq0-qpick,.sq0-tabs,.sq0-cols,.sq0-opts{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}
.sq0-qpick .chip{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sq0-pipe{list-style:none;margin:0 0 12px;padding:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;counter-reset:st}
.sq0-pipe li{position:relative;display:flex;flex-direction:column;align-items:center;gap:2px;padding:8px 4px;border-radius:12px;border:1px solid var(--line);background:var(--surface);opacity:.55;text-align:center;transition:all .3s}
.sq0-pipe li i{font-style:normal;font-size:1.2rem}
.sq0-pipe li b{font:700 .7rem Inter,sans-serif;line-height:1.2}
.sq0-pipe li:not(:last-child)::after{content:"›";position:absolute;right:-7px;top:50%;transform:translateY(-50%);color:var(--muted);font-weight:700;z-index:1}
.sq0-pipe li.done{opacity:1;border-color:var(--good);background:var(--good-soft)}
.sq0-pipe li.cur{opacity:1;border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft);transform:translateY(-2px)}
.sq0-pipe li.fail{opacity:1;border-color:var(--bad);background:var(--bad-soft)}
.sq0-pipe li.skip{opacity:.3;text-decoration:line-through}
.sq0-stage{min-height:60px}
.sq0-note,.sq0-ok,.sq0-skip{padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:var(--soft);font-size:.88rem}
.sq0-ok{border-color:var(--good);background:var(--good-soft)}
.sq0-skip{color:var(--muted);border-style:dashed}
.sq0-model{display:flex;flex-direction:column;gap:10px}
.sq0-rel{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.sq0-rel>div{min-width:0}
.sq0-rel .sq-grid{margin-top:0}
.sq0-code{margin:0;padding:12px 14px;border-radius:12px;background:var(--code-bg);color:#d6dbe7;font:12.5px/1.65 "JetBrains Mono",monospace;overflow-x:auto;font-variant-ligatures:none}
.sq0-ask{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px;align-items:center}
.sq0-ask b{font:700 .72rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.sq0-ask .sq-q{color:#d6dbe7}
.sq0-gw{display:flex;flex-direction:column;gap:4px;font-size:.86rem}
.sq0-gw .g{color:var(--good)}.sq0-gw .w{color:var(--bad)}.sq0-gw .e{color:var(--muted);font-size:.8rem}
.sq0-graph{width:100%;max-width:460px;height:auto;display:block;margin:0 auto}
.sq0-ge path{stroke:var(--muted);stroke-width:2;fill:none}
.sq0-ge path.buy{stroke:var(--accent);stroke-dasharray:5 4}
.sq0-gl text{font:700 9px Inter,sans-serif;fill:var(--muted);text-anchor:middle}
.sq0-gn circle{fill:var(--accent-soft);stroke:var(--accent);stroke-width:2}
.sq0-gn.car circle{fill:var(--amber-soft);stroke:var(--amber)}
.sq0-gn text{font:700 11px Inter,sans-serif;fill:var(--text);text-anchor:middle}
.sq0-pick{margin-top:14px;padding:12px;border-radius:14px;border:1px dashed var(--line)}
.sq0-score{margin-left:6px;color:var(--accent)}
.sq0-sc{margin:0 0 10px;font-weight:600}
.sq0-opts .chip.ok{color:#fff;background:var(--good-fill);border-color:transparent}
.sq0-opts .chip.no{color:var(--bad);border-color:var(--bad);background:var(--bad-soft)}
.sq0-why{min-height:1.4em;font-size:.88rem}
.sq0-why .btn{margin-left:6px}
.sq0-ktab .sq-grid{margin-top:0}
.sq0-ktab th.on,.sq0-ktab td.on{background:color-mix(in srgb,var(--accent) 14%,transparent);color:var(--text)}
.sq0-ktab tr.sq0-dup td{background:var(--bad-soft);color:var(--bad)}
.sq0-verdict{margin-top:10px;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:var(--soft);font-size:.9rem;min-height:1.4em}
.sq0-verdict.pk,.sq0-verdict.alt{border-color:var(--good);background:var(--good-soft)}
.sq0-verdict.super,.sq0-verdict.uq{border-color:var(--amber);background:var(--amber-soft)}
.sq0-verdict.none{border-color:var(--bad);background:var(--bad-soft)}
.sq0-kinds{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.sq0-kinds span{font:600 .72rem Inter,sans-serif;padding:3px 10px;border-radius:99px;border:1px dashed var(--line);color:var(--muted)}
.sq0-kinds span.on{border-style:solid;border-color:var(--good);color:var(--good);background:var(--good-soft)}
.sq0-kinds span.on::before{content:"✓ "}
.sq0-rsvg{width:100%;max-width:540px;height:auto;display:block;margin:0 auto}
.sq0-rh{font:700 11px Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;fill:var(--muted);text-anchor:middle}
.sq0-rl path{fill:none;stroke:color-mix(in srgb,var(--muted) 60%,transparent);stroke-width:2;stroke-dasharray:1;stroke-dashoffset:0;animation:sq0draw .6s ease-out backwards;transition:stroke .25s,stroke-width .25s}
