.sq0-rl path.on{stroke:var(--accent);stroke-width:3}
.sq0-rn{cursor:pointer;outline:none}
.sq0-rn rect{fill:var(--surface);stroke:var(--line);stroke-width:1.5;transition:all .25s}
.sq0-rn text{font:600 11.5px "JetBrains Mono",monospace;fill:var(--text);text-anchor:middle;pointer-events:none}
