.sq0-bucket.hit{box-shadow:0 0 0 4px color-mix(in srgb,var(--c) 40%,transparent)}
.sq0-bucket b{font:800 1rem "Inter Tight",Inter,sans-serif;color:var(--c)}
.sq0-bucket small{font:700 .66rem Inter,sans-serif;letter-spacing:.04em;text-transform:uppercase;color:var(--muted)}
.sq0-bucket em{font-style:normal;font-size:.74rem;color:var(--muted);line-height:1.3}
.sq0-in{display:flex;flex-direction:column;gap:3px;margin-top:6px}
