@media (max-width:640px){.sq0-vs{grid-template-columns:1fr}.sq0-pipe{grid-template-columns:repeat(3,minmax(0,1fr))}.sq0-pipe li:nth-child(3)::after{display:none}.sq0-ask{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){.sq0-rl path{animation:none}.sq0-file,.sq0-probs span,.sq0-pipe li,.sq0-rl path,.sq0-rn rect,.sq0-bucket{transition:none}}
