.sq0-rel{grid-template-columns:minmax(0,.9fr) minmax(0,1.5fr) minmax(0,1fr)}
.sq0-ixpick{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:-4px 0 12px;font-size:.84rem;color:var(--muted)}
.sq0-plan{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
