.sq01-shelf>b{display:block;margin-bottom:6px;font:700 .8rem "JetBrains Mono",monospace}
.sq01-shelf>div{display:flex;flex-wrap:wrap;gap:4px}
.sq01-col{font:600 .68rem "JetBrains Mono",monospace;padding:2px 7px;border-radius:7px;background:var(--surface);border:1px solid var(--line)}
.sq01-col em{font-style:normal;color:var(--muted);font-weight:500}
.sq01-colnew{background:var(--good-soft);border-color:var(--good);color:var(--good);animation:sq01-in .6s ease-out}
.sq01-colren{background:var(--amber-soft);border-color:var(--amber);color:var(--amber);animation:sq01-in .6s ease-out}
.sq01-colgone{background:var(--bad-soft);border-color:var(--bad);color:var(--bad);text-decoration:line-through;animation:sq01-fade 2.4s ease-in .6s forwards}
.sq01-newt{border-color:var(--good);background:var(--good-soft);animation:sq01-in .6s ease-out}
.sq01-gonet{border-color:var(--bad);background:var(--bad-soft)}
.sq01-gonet>b{text-decoration:line-through;color:var(--bad)}
.sq01-redt{color:var(--bad)}
@keyframes sq01-in{from{opacity:0;transform:translateY(-5px) scale(.96)}to{opacity:1;transform:none}}
@keyframes sq01-fade{from{opacity:1}to{opacity:.35}}
/* v2: gate trace */
.sq01-trace{display:flex;flex-direction:column;gap:5px;margin:0 0 10px}
.sq01-tl{padding:7px 10px;border-radius:10px;border:1px solid var(--line);background:var(--soft);font-size:.8rem;line-height:1.9}
.sq01-tl.no{border-color:var(--bad);background:var(--bad-soft)}
.sq01-tl>b{display:inline-block;min-width:96px;font:700 .68rem Inter,sans-serif;letter-spacing:.05em;text-transform:uppercase;color:var(--muted)}
.sq01-tk{display:inline-block;margin:0 4px 0 0;padding:1px 8px;border-radius:99px;font:600 .72rem "JetBrains Mono",monospace;border:1px solid var(--line);background:var(--surface)}
.sq01-tk.ok{border-color:var(--good);color:var(--good)}.sq01-tk.no{border-color:var(--bad);color:var(--bad);background:var(--surface)}
.sq01-ixn{display:inline-block;margin:0 6px 0 0;font:600 .7rem Inter,sans-serif;color:var(--muted)}
.sq01-ik{display:inline-block;margin:0 3px 2px 0;padding:0 6px;border-radius:6px;border:1px solid var(--line);background:var(--surface);font:500 .7rem "JetBrains Mono",monospace}
.sq01-ik.probe{border-color:var(--accent);background:var(--accent-soft);color:var(--accent);font-weight:700}
.sq01-ik.hit{border-color:var(--bad);background:var(--bad-soft);color:var(--bad);font-weight:700}
/* v2: FK ripple chain */
.sq01-rip{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:10px 0 0;min-height:28px}
.sq01-rc{font:700 .76rem Inter,sans-serif;padding:4px 10px;border-radius:99px;border:1px solid var(--line);background:var(--soft)}
.sq01-rc.pa{border-color:var(--accent);color:var(--accent);background:var(--accent-soft)}
.sq01-rc.fk{font-family:"JetBrains Mono",monospace;font-weight:600}
.sq01-rc.no{border-color:var(--bad);color:var(--bad);background:var(--bad-soft)}
.sq01-rc.amb{border-color:var(--amber);color:var(--amber);background:var(--amber-soft)}
.sq01-ra{font-style:normal;font-weight:700;color:var(--muted)}
/* v2: primary-key pages */
.sq01-pkm{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.sq01-pkstat{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 8px;margin-bottom:10px;font-size:.84rem}
.sq01-pkstat>span{flex-basis:100%;color:var(--muted)}
.sq01-pkstat b{font:800 1.25rem "Inter Tight",Inter,sans-serif;color:var(--accent);font-variant-numeric:tabular-nums}
.sq01-pkstat b.bad{color:var(--bad)}
.sq01-pkstat em{font-style:normal;font:600 .72rem Inter,sans-serif;color:var(--muted);margin-right:8px}
.sq01-leaves{display:flex;flex-wrap:wrap;gap:8px;min-height:64px}
.sq01-leaf{display:grid;grid-template-rows:repeat(4,22px);gap:3px;width:92px;padding:5px;border-radius:10px;border:2px solid var(--line);background:var(--soft);transition:border-color .3s}
.sq01-leaf i{grid-row:1/-1;align-self:center;text-align:center;font-size:.72rem;color:var(--muted)}
.sq01-leaf span{display:flex;align-items:center;justify-content:center;border-radius:6px;background:var(--surface);border:1px solid var(--line);font:600 .66rem "JetBrains Mono",monospace;white-space:nowrap;overflow:hidden}
.sq01-leaf span.nw{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}
.sq01-leaf.cur{border-color:var(--accent)}
.sq01-leaf.cur.split{border-color:var(--bad);background:var(--bad-soft)}
.sq01-leaf.cur.append{border-color:var(--good);background:var(--good-soft)}
@media (max-width:640px){
  .sq01-bins,.sq01-gates{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sq01-two{grid-template-columns:minmax(0,1fr)}
  .sq01-shelves{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (prefers-reduced-motion:reduce){
  .sq01-new,.sq01-chg,.sq01-colnew,.sq01-colren,.sq01-newt{animation:none}
  .sq01-gone td,.sq01-colgone{animation:none;opacity:.6}
  .sq01-g,.sq01-out,.sq01-cv,.sq01-shelf{transition:none}
}
html.no-motion .sq01-new,html.no-motion .sq01-chg,html.no-motion .sq01-colnew,html.no-motion .sq01-colren,html.no-motion .sq01-newt{animation:none}
html.no-motion .sq01-gone td,html.no-motion .sq01-colgone{animation:none;opacity:.6}
html.no-motion .sq01-g,html.no-motion .sq01-out,html.no-motion .sq01-cv,html.no-motion .sq01-shelf{transition:none}

@media (max-width:640px){.sq01-leaf{width:80px}.sq01-tl>b{display:block}}
@media (prefers-reduced-motion:reduce){.sq01-leaf{transition:none}}
html.no-motion .sq01-leaf{transition:none}

/* sql s04 v2 (2026-10-30): Lesson S04 labs, classes sq04- (labs-sql-s04.js). v2: implicit-conversion flip cards (#sq04Trap), sargability SEARCH vs SCAN with real plans (#sq04Sarg); .bad/.warn renamed sq04-bad/sq04-warn */
.sq04-chips{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 10px;align-items:center}
.sq04-h{margin:18px 0 8px;font:700 .74rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.sq04-h:first-child{margin-top:0}
.sq04-rows h5,.sq04-cs h5,.sq04-got h5{margin:0 0 6px;font:700 .72rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.sq04-in-row{display:flex;flex-wrap:wrap;gap:8px 14px;align-items:center;margin:0 0 10px}
.sq04-in-row label,.sq04-params label,.sq04-slide label{font:600 .8rem Inter,sans-serif;color:var(--muted);display:inline-flex;align-items:center;gap:6px}
.sq04-in-row input,.sq04-in-row select,.sq04-params input{font:500 .85rem "JetBrains Mono",monospace;padding:6px 9px;border-radius:8px;border:1px solid var(--line);background:var(--surface);color:var(--text);max-width:100%}
.sq04-in-row input:focus,.sq04-in-row select:focus,.sq04-params input:focus{outline:2px solid var(--accent);outline-offset:1px}
.sq04-pre{display:inline-flex;flex-wrap:wrap;gap:6px}
.sq04-params{display:flex;flex-wrap:wrap;gap:8px 14px;margin:0 0 10px;min-height:0}
.sq04-sqlq{margin:12px 0 0;overflow-x:auto;white-space:pre}
.sq04-res{display:inline-block;margin-left:4px;padding:1px 8px;border-radius:99px;background:var(--accent-soft);color:var(--accent)}

/* rows lab */
.sq04-rows{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:10px;align-items:start}
.sq04-rl,.sq04-ro{display:flex;flex-direction:column;gap:3px}
.sq04-r{padding:4px 10px;border-radius:8px;border:1px solid var(--line);background:var(--soft);font:500 .8rem "JetBrains Mono",monospace;min-height:26px;transition:opacity .45s,transform .6s cubic-bezier(.3,.7,.3,1),background .3s,border-color .3s}
.sq04-r.on{border-color:var(--accent);background:var(--accent-soft)}
.sq04-r.fold{opacity:.35;transform:translateX(18px) scale(.96);transition-delay:calc(var(--i)*40ms)}
.sq04-r.res{border-color:var(--good);background:var(--good-soft)}
.sq04-r.done{border-color:var(--line)}
.sq04-r.res.done{border-color:var(--good)}
.sq04-rbox{align-self:center;display:flex;flex-direction:column;align-items:center;gap:4px;text-align:center}
.sq04-rbox b{font:700 .78rem "JetBrains Mono",monospace;padding:6px 10px;border-radius:10px;background:var(--accent);color:#fff;max-width:150px;word-break:break-word}
.sq04-rbox i{font-style:normal;color:var(--muted);font-size:1.2rem}
.sq04-rout.one .sq04-ro{justify-content:center;min-height:140px}
.sq04-big{font:700 1.6rem "JetBrains Mono",monospace;padding:18px 14px;border-radius:14px;border:2px solid var(--good);background:var(--good-soft);text-align:center;color:var(--text)}

/* shared entrance animation (disabled for reduced motion below) */
.sq04-in{animation:sq04-in .45s cubic-bezier(.2,1.2,.4,1) both;animation-delay:calc(var(--i,0)*55ms)}
@keyframes sq04-in{from{opacity:0;transform:translateY(8px) scale(.92)}to{opacity:1;transform:none}}

/* string lab */
.sq04-chars{display:flex;flex-wrap:wrap;gap:4px;margin:6px 0;min-height:52px;align-items:flex-start}
.sq04-c{display:inline-flex;flex-direction:column;align-items:center;min-width:30px;padding:4px 2px 2px;border-radius:8px;border:1px solid var(--line);background:var(--soft);transition:background .3s,border-color .3s,color .3s,transform .3s}
.sq04-c b{font:600 .95rem "JetBrains Mono",monospace;line-height:1.3;color:var(--text)}
.sq04-c i{font:500 .62rem "JetBrains Mono",monospace;font-style:normal;color:var(--muted)}
.sq04-c.sp b{color:var(--muted)}
.sq04-c.hit{background:var(--accent-soft);border-color:var(--accent)}
.sq04-c.chg{background:var(--good-soft);border-color:var(--good)}
.sq04-c.cnt{background:var(--accent-soft);border-color:var(--accent)}
.sq04-c.del{background:var(--bad-soft);border-color:var(--bad)}
.sq04-c.del b{text-decoration:line-through;color:var(--bad)}
.sq04-chars.out .sq04-c{background:var(--surface)}
.sq04-chars.out .sq04-c.chg{background:var(--good-soft)}
.sq04-arrow{text-align:center;color:var(--muted);font-size:1.1rem;line-height:1}
.sq04-num{font:700 1.4rem "JetBrains Mono",monospace;padding:6px 16px;border-radius:12px;border:2px solid var(--good);background:var(--good-soft)}

/* sliders, number line, groups */
.sq04-slide{display:flex;flex-wrap:wrap;gap:8px 16px;align-items:center;margin-bottom:10px}
.sq04-slide input[type=range]{flex:1 1 200px;min-width:120px;accent-color:var(--accent)}
.sq04-slide.two label{flex:1 1 220px}
.sq04-slide label b{font:700 .95rem "JetBrains Mono",monospace;color:var(--text);min-width:3.4ch;display:inline-block}
.sq04-line{position:relative;height:74px;margin:10px 14px 6px}
.sq04-line:before{content:"";position:absolute;left:0;right:0;top:34px;height:3px;border-radius:2px;background:var(--line)}
.sq04-ticks span{position:absolute;top:28px;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:6px}
.sq04-ticks i{width:2px;height:15px;background:var(--muted);opacity:.5}
.sq04-ticks b{font:600 .68rem "JetBrains Mono",monospace;color:var(--muted)}
.sq04-dot{position:absolute;top:24px;width:22px;height:22px;margin-left:-11px;border-radius:50%;transition:left .55s cubic-bezier(.3,.7,.3,1);box-shadow:var(--shadow)}
.sq04-dot.x{background:var(--accent);z-index:2;border:3px solid var(--surface)}
.sq04-dot.y{background:var(--good);top:4px;z-index:1;border:3px solid var(--surface)}
.sq04-dot.y:after{content:"";position:absolute;left:8px;top:22px;width:2px;height:16px;background:var(--good)}
.sq04-fgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px}
.sq04-fc{display:flex;flex-direction:column;gap:2px;align-items:flex-start;text-align:left;padding:8px 10px;border-radius:10px;border:1px solid var(--line);background:var(--soft);cursor:pointer;color:var(--text);font:inherit;transition:border-color .2s,background .2s}
.sq04-fc code{font-size:.74rem;background:none;padding:0;color:var(--muted)}
.sq04-fc b{font:700 1.05rem "JetBrains Mono",monospace}
.sq04-fc.on{border-color:var(--good);background:var(--good-soft)}
.sq04-dots{display:flex;flex-wrap:wrap;gap:8px;min-height:44px;margin:4px 0 10px}
.sq04-grp{display:flex;flex-wrap:wrap;gap:3px;padding:5px 6px;border-radius:10px;border:2px solid var(--accent);background:var(--accent-soft);max-width:100%}
.sq04-grp i{width:11px;height:11px;border-radius:50%;background:var(--accent)}
.sq04-grp.rest{border-color:var(--amber);background:var(--amber-soft);border-style:dashed}
.sq04-grp.rest i{background:var(--amber)}
.sq04-tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px}
.sq04-tiles div{display:flex;flex-direction:column;gap:2px;padding:8px 12px;border-radius:10px;border:1px solid var(--line);background:var(--soft)}
.sq04-tiles span{font:600 .74rem "JetBrains Mono",monospace;color:var(--muted)}
.sq04-tiles b{font:700 1.3rem "JetBrains Mono",monospace}
.sq04-tiles em{font:500 .72rem Inter,sans-serif;font-style:normal;color:var(--muted)}

/* date lab */
.sq04-chain{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:4px 0 10px}
.sq04-step{display:flex;flex-direction:column;gap:1px;padding:7px 12px;border-radius:10px;border:1px solid var(--line);background:var(--soft)}
.sq04-step:last-child{border-color:var(--good);background:var(--good-soft)}
.sq04-step span{font:600 .64rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
.sq04-step b{font:700 .92rem "JetBrains Mono",monospace}
.sq04-step em{font:500 .72rem Inter,sans-serif;font-style:normal;color:var(--muted)}
.sq04-hop{font:500 .78rem "JetBrains Mono",monospace;color:var(--accent);display:flex;align-items:center;gap:4px}
.sq04-cal{margin:0 0 6px;max-width:300px}
.sq04-calh{font:700 .8rem "JetBrains Mono",monospace;margin-bottom:4px}
.sq04-cg{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;font:500 .74rem "JetBrains Mono",monospace;text-align:center}
.sq04-cg u{text-decoration:none;color:var(--muted);font-size:.64rem;padding:2px 0}
.sq04-cg span{padding:4px 0;border-radius:6px;background:var(--soft);color:var(--text)}
.sq04-cg span.fin{background:var(--good);color:#fff;font-weight:700}
.sq04-cg span.start{box-shadow:inset 0 0 0 2px var(--accent)}
.sq04-toks{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:6px;margin-bottom:8px}
.sq04-tok{display:flex;flex-direction:column;gap:1px;align-items:flex-start;text-align:left;padding:7px 10px;border-radius:10px;border:1px solid var(--line);background:var(--soft);cursor:pointer;color:var(--text);font:inherit}
.sq04-tok code{font-size:.76rem;background:none;padding:0;color:var(--accent)}
.sq04-tok b{font:700 1rem "JetBrains Mono",monospace}
.sq04-tok em{font:500 .68rem Inter,sans-serif;font-style:normal;color:var(--muted)}
.sq04-tok:hover{border-color:var(--accent)}
.sq04-fout{font:500 .9rem "JetBrains Mono",monospace}
.sq04-yr{position:relative;height:52px;margin:6px 8px 0}
.sq04-yr:before{content:"";position:absolute;left:0;right:0;top:14px;height:3px;background:var(--line);border-radius:2px}
.sq04-yr .bar{position:absolute;top:11px;height:9px;border-radius:5px;background:var(--accent-fill);border:1px solid var(--accent);transition:left .5s,width .5s}
.sq04-yr .pt{position:absolute;top:8px;width:15px;height:15px;margin-left:-7px;border-radius:50%;background:var(--accent);border:2px solid var(--surface);transition:left .5s}
.sq04-yr .pt.b{background:var(--good)}
.sq04-yr .pt i{position:absolute;top:-22px;left:50%;transform:translateX(-50%);font:600 .62rem "JetBrains Mono",monospace;font-style:normal;color:var(--muted);white-space:nowrap}
.sq04-yr .mo{position:absolute;left:0;right:0;top:32px;display:flex;justify-content:space-between;font:600 .62rem "JetBrains Mono",monospace;color:var(--muted)}
.sq04-spt{margin-top:4px;font:500 .95rem Inter,sans-serif}
.sq04-spt b{font:700 1.3rem "JetBrains Mono",monospace;color:var(--good)}

/* case lab */
.sq04-cs{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.6fr);gap:14px;align-items:start}
.sq04-cars{display:flex;flex-direction:column;gap:3px}
.sq04-car{display:flex;justify-content:space-between;gap:8px;padding:4px 10px;border-radius:8px;border:1px solid var(--line);background:var(--soft);cursor:pointer;color:var(--text);font:500 .8rem "JetBrains Mono",monospace;transition:border-color .25s,background .25s,opacity .25s}
.sq04-car span{color:var(--muted)}
.sq04-car.done{opacity:.6}
.sq04-car.on{border-color:var(--accent);background:var(--accent-soft);opacity:1}
.sq04-ladder{display:flex;flex-direction:column;gap:6px;padding-top:22px}
.sq04-rung{display:grid;grid-template-columns:auto minmax(0,1fr) auto;grid-template-areas:"w c t" "o o o";gap:2px 8px;align-items:center;padding:8px 12px;border-radius:12px;border:1px solid var(--line);background:var(--soft);transition:background .35s,border-color .35s,opacity .35s}
.sq04-rung .w{grid-area:w;font:700 .7rem "JetBrains Mono",monospace;color:var(--accent)}
.sq04-rung code{grid-area:c;background:none;padding:0;font-size:.8rem;word-break:break-word}
.sq04-rung .t{grid-area:t;font:700 .68rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}
.sq04-rung .o{grid-area:o;font:500 .78rem Inter,sans-serif;color:var(--muted)}
.sq04-rung.no{opacity:.75}.sq04-rung.no .t{color:var(--bad)}
.sq04-rung.yes{border-color:var(--good);background:var(--good-soft)}.sq04-rung.yes .t{color:var(--good)}
.sq04-rung.skip{opacity:.65;border-style:dashed}
.sq04-rung.skip code,.sq04-rung.skip .o{color:var(--muted)}
.sq04-got{margin-top:12px}
.sq04-gl{display:flex;flex-wrap:wrap;gap:5px}
.sq04-gl span{display:inline-flex;gap:8px;align-items:baseline;padding:3px 10px;border-radius:99px;border:1px solid var(--good);background:var(--good-soft);font:500 .78rem "JetBrains Mono",monospace}
.sq04-gl span b{font-weight:600;color:var(--muted)}
.sq04-gl span.nul{border-color:var(--amber);background:var(--amber-soft)}

/* null + cast tables */
.sq04-nt,.sq04-ct,.sq04-zero{overflow-x:auto}
.sq04-nt table,.sq04-ct table,.sq04-zero table{border-collapse:collapse;width:100%;font:500 .8rem "JetBrains Mono",monospace}
.sq04-nt th,.sq04-ct th,.sq04-zero th{text-align:left;padding:5px 9px;border-bottom:2px solid var(--line);font:700 .68rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}
.sq04-nt th code,.sq04-zero th code{text-transform:none;letter-spacing:0;font-size:.72rem}
.sq04-nt td,.sq04-ct td,.sq04-zero td{padding:5px 9px;border-bottom:1px solid var(--line);vertical-align:top}
.sq04-nt td.nul{background:var(--amber-soft)}
.sq04-nt td.res{background:var(--good-soft);font-weight:700}
.sq04-nt td.res.nul{background:var(--amber-soft)}
.sq04-nt{perspective:600px}
.sq04-avg{margin:10px 0 0;font:500 .84rem Inter,sans-serif;color:var(--muted)}
.sq04-avg b{color:var(--text)}
.sq04-zero td.sq04-bad{background:var(--bad-soft);color:var(--bad);font-weight:700}
.sq04-ct tr.sq04-bad td{background:var(--bad-soft)}
.sq04-ct tr.sq04-warn td{background:var(--amber-soft)}
.sq04-ct td:last-child{font:500 .78rem Inter,sans-serif}
.sq04-ct td:nth-child(2),.sq04-ct td:nth-child(5){color:var(--muted)}

/* sort lab */
.sq04-sortbox{display:grid;grid-template-columns:minmax(120px,200px) minmax(0,1fr);gap:16px;align-items:start}
.sq04-sl{position:relative;width:100%}
.sq04-sv{position:absolute;left:0;right:0;top:0;height:40px;display:flex;align-items:center;padding:0 14px;border-radius:10px;border:1px solid var(--good);background:var(--good-soft)}
.sq04-sv.txt{border-color:var(--amber);background:var(--amber-soft)}
.sq04-sv b{font:700 1rem "JetBrains Mono",monospace}
.sq04-cmp{display:flex;flex-direction:column;gap:8px;font:500 .84rem Inter,sans-serif}
.sq04-cmp div{padding:8px 12px;border-radius:10px;border:1px solid var(--line);background:var(--soft)}

@media (max-width:640px){
  .sq04-rows{grid-template-columns:1fr;}
  .sq04-rbox{flex-direction:row;justify-content:center}
  .sq04-rbox i{transform:rotate(90deg)}
  .sq04-cs{grid-template-columns:1fr}
  .sq04-ladder{padding-top:0}
  .sq04-sortbox{grid-template-columns:1fr}
