.sq13-sum span,.sq13-wsum span,.sq13-sres span,.sq13-plans>span{font:600 .76rem Inter,sans-serif;padding:3px 10px;border-radius:99px;background:var(--soft);color:var(--muted)}
.sq13-sum b,.sq13-wsum b,.sq13-sres b{color:var(--text)}
.sq13-sum .s-d,.sq13-wsum .s-d{background:var(--bad-soft);color:var(--bad)}
.sq13-sum .s-m{background:var(--good-soft);color:var(--good)}
.sq13-sum .s-d b,.sq13-sum .s-m b,.sq13-wsum .s-d b{color:inherit}
.sq13-wsum,.sq13-sres,.sq13-plans{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.sq13-plans{margin-left:auto}
.sq13-planbox{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center;margin:6px 0}
.sq13-plan{display:inline-block;font:500 .78rem "JetBrains Mono",monospace;padding:4px 10px;border-radius:8px;border:1px solid var(--line);background:var(--soft);overflow-wrap:anywhere}
.sq13-plan b{font-weight:700}
.sq13-plan.p-scan{background:var(--bad-soft);border-color:var(--bad);color:var(--bad)}
.sq13-plan.p-srch{background:var(--good-soft);border-color:var(--good);color:var(--good)}
.sq13-plan.p-cov{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
.sq13-plan.p-oth{background:var(--amber-soft);border-color:var(--amber);color:var(--amber)}
/* S3 scan vs tree */
.sq13-two{display:grid;grid-template-columns:minmax(0,300px) minmax(0,1fr);gap:14px;align-items:start}
.sq13-side{border:1px solid var(--line);border-radius:12px;background:var(--surface);overflow:hidden;min-width:0}
.sq13-heap{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:3px;padding:10px}
.sq13-heap i{font:500 .62rem "JetBrains Mono",monospace;font-style:normal;text-align:center;padding:4px 0;border-radius:4px;background:var(--soft);color:var(--muted);border:1px solid transparent;transition:background .25s,color .25s}
.sq13-heap i.seen{background:var(--amber-soft);color:var(--amber)}
.sq13-heap i.hit{background:var(--good);color:#fff;border-color:var(--good);font-weight:700}
.sq13-cnt{padding:6px 12px 8px;font:600 .8rem Inter,sans-serif;color:var(--muted);border-top:1px solid var(--line)}
.sq13-cnt b{color:var(--text);font:700 .95rem "JetBrains Mono",monospace}
.sq13-tscroll{padding:12px 10px 8px;text-align:center}
.sq13-tscroll>.sq13-tn{display:inline-flex}
.sq13-tn{display:flex;flex-direction:column;align-items:center;position:relative;padding:14px 3px 0}
.sq13-tscroll>.sq13-tn{padding-top:0}
.sq13-tn:before,.sq13-tn:after{content:"";position:absolute;top:0;width:50%;height:14px;border-top:1.5px solid var(--line)}
.sq13-tn:before{left:0;border-right:1.5px solid var(--line)}
.sq13-tn:after{right:0}
.sq13-tn:first-child:before,.sq13-tn:last-child:after{border-top:0}
.sq13-tn:last-child:before{border-radius:0 6px 0 0}
.sq13-tn:first-child:after{border-left:1.5px solid var(--line);border-radius:6px 0 0 0}
.sq13-tn:only-child:before,.sq13-tn:only-child:after{display:none}
.sq13-tscroll>.sq13-tn:before,.sq13-tscroll>.sq13-tn:after{display:none}
.sq13-kids{display:flex;position:relative;padding-top:14px}
.sq13-kids:before{content:"";position:absolute;top:0;left:50%;height:14px;border-left:1.5px solid var(--line)}
.sq13-nb{display:flex;flex-direction:row;gap:2px;padding:4px 5px;border:1.5px solid var(--line);border-radius:7px;background:var(--surface);transition:background .3s,border-color .3s,box-shadow .3s}
.sq13-nb.lf{flex-direction:column;gap:1px;padding:3px 4px}
.sq13-nb i{font:500 .62rem "JetBrains Mono",monospace;font-style:normal;color:var(--muted);padding:1px 3px;border-radius:3px;text-align:center}
.sq13-nb.on{border-color:var(--accent);background:var(--accent-soft);box-shadow:0 0 0 2px var(--accent-fill)}
.sq13-nb.on i{color:var(--text)}
.sq13-nb i.hit{background:var(--good);color:#fff;font-weight:700}
.sq13-scale{margin-top:12px;padding:10px 12px;border:1px dashed var(--line);border-radius:12px;font:600 .8rem Inter,sans-serif;color:var(--muted);display:flex;flex-wrap:wrap;gap:8px 14px;align-items:center}
.sq13-scale b:first-child{color:var(--text)}
/* S5 composite */
.sq13-ck{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border:1px solid var(--line);border-radius:99px;background:var(--surface);cursor:pointer;font:600 .8rem Inter,sans-serif;color:var(--text)}
.sq13-idxrow{display:flex;flex-wrap:wrap;align-items:stretch;gap:6px;margin:6px 0 10px}
.sq13-ic{flex:1 1 120px;min-width:100px;border:1.5px solid var(--line);border-radius:10px;padding:8px 10px;background:var(--soft);color:var(--muted);transition:background .3s,border-color .3s}
.sq13-ic b{display:block;font:700 .9rem "JetBrains Mono",monospace;color:var(--muted)}
.sq13-ic em{display:block;font:600 .7rem Inter,sans-serif;font-style:normal;margin-top:2px}
.sq13-ic.on{background:var(--good-soft);border-color:var(--good);color:var(--good)}
.sq13-ic.on b{color:var(--good)}
.sq13-ic.dim{background:var(--amber-soft);border-color:var(--amber);color:var(--amber)}
.sq13-ic.dim b{color:var(--amber)}
.sq13-ar{align-self:center;color:var(--muted);font-weight:700}
.sq13-verdict{flex:1 1 100%;font:500 .84rem Inter,sans-serif;padding:8px 12px;border-radius:10px;background:var(--soft);color:var(--text)}
.sq13-verdict.good{background:var(--good-soft)}.sq13-verdict.part{background:var(--amber-soft)}.sq13-verdict.bad{background:var(--bad-soft)}
.sq13-lt{display:grid;gap:2px;margin-top:4px}
.sq13-lt div{display:grid;grid-template-columns:1fr 70px 1fr;gap:6px;font:500 .74rem "JetBrains Mono",monospace;padding:2px 10px;background:var(--soft);border-radius:6px;color:var(--muted)}
.sq13-lt span.on{color:var(--good);font-weight:700}
/* S6 clustered */
.sq13-ddl{margin:0 0 10px;font-size:.76rem;white-space:pre-wrap;overflow-wrap:anywhere}
.sq13-cl{display:grid;grid-template-columns:minmax(0,1fr) 70px minmax(0,1fr);gap:8px;align-items:center}
.sq13-bx{border:1.5px solid var(--line);border-radius:12px;padding:10px 12px;background:var(--surface);min-height:120px;transition:border-color .3s,background .3s;min-width:0}
.sq13-bx.on{border-color:var(--accent);background:var(--accent-soft)}
.sq13-bt{margin:6px 0;padding:6px 8px;border:1px dashed var(--line);border-radius:8px;font:600 .74rem Inter,sans-serif;color:var(--muted);text-align:center}
.sq13-en mark,.sq13-rw mark{display:block;background:var(--good-soft);color:var(--good);border:1px solid var(--good);border-radius:7px;padding:4px 8px;font:600 .74rem "JetBrains Mono",monospace;overflow-wrap:anywhere}
.sq13-en mark.cv{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}
.sq13-skip{font:600 .76rem Inter,sans-serif;color:var(--muted)}
.sq13-arrow{text-align:center;color:var(--muted);font:700 .66rem "JetBrains Mono",monospace;display:flex;flex-direction:column;align-items:center;gap:4px;opacity:.5;transition:opacity .3s,color .3s}
.sq13-arrow i{display:block;width:100%;height:2px;background:currentColor;position:relative}
.sq13-arrow i:after{content:"";position:absolute;right:-1px;top:-4px;border:5px solid transparent;border-left:8px solid currentColor;border-right:0}
.sq13-arrow.on{opacity:1;color:var(--accent)}
.sq13-arrow span{overflow-wrap:anywhere}
.sq13-note{margin-top:10px;font:400 .84rem Inter,sans-serif;color:var(--muted)}.sq13-note b{color:var(--text)}
.sq13-pl3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.sq13-pl3 em{display:block;font:600 .68rem Inter,sans-serif;font-style:normal;color:var(--muted);margin-bottom:3px}
.sq13-sim{color:var(--amber)}
/* S7 write cost */
.sq13-newrow{display:inline-block;padding:6px 12px;border-radius:10px;background:var(--accent-soft);border:1px solid var(--accent);margin-bottom:8px}
.sq13-newrow b{font:600 .8rem "JetBrains Mono",monospace;color:var(--text)}
.sq13-bts{display:flex;flex-wrap:wrap;gap:8px}
.sq13-wb{padding:8px 12px;border-radius:10px;border:1.5px solid var(--line);background:var(--surface);min-width:112px;animation:sq13in .45s both}
.sq13-wb.tb{border-color:var(--accent)}
.sq13-wb.ix{border-color:var(--amber);background:var(--amber-soft)}
.sq13-wb b{display:block;font:700 .78rem "JetBrains Mono",monospace;color:var(--text)}
.sq13-wb em{font:600 .7rem Inter,sans-serif;font-style:normal;color:var(--bad)}
@keyframes sq13in{from{opacity:0;transform:translateY(-10px) scale(.9)}to{opacity:1;transform:none}}
.sq13-bars{margin-top:10px}
.sq13-bar{display:grid;grid-template-columns:86px minmax(0,1fr) 70px;gap:8px;align-items:center;margin:4px 0;font:600 .76rem Inter,sans-serif;color:var(--muted)}
.sq13-bar i{display:block;height:14px;border-radius:7px;background:var(--accent);transition:width .5s}
.sq13-bar b{font:700 .76rem "JetBrains Mono",monospace;color:var(--text);text-align:right}
.sq13-wsum{margin:8px 0}
@media (max-width:640px){
  .sq13-vw,.sq13-two{grid-template-columns:minmax(0,1fr)}
  .sq13-cl{grid-template-columns:minmax(0,1fr)}
  .sq13-arrow{flex-direction:row;justify-content:center;min-height:24px}
  .sq13-arrow i{width:40px}
  .sq13-pl3{grid-template-columns:minmax(0,1fr)}
  .sq13-plans{margin-left:0}
  .sq13-bar{grid-template-columns:70px minmax(0,1fr) 56px}
}
@media (prefers-reduced-motion:reduce){
  .sq13-wb{animation:none}.sq13-heap i,.sq13-nb,.sq13-bar i,.sq13-ic,.sq13-bx,.sq13-arrow{transition:none}
}
html.no-motion .sq13-wb{animation:none}
html.no-motion .sq13-heap i,html.no-motion .sq13-nb,html.no-motion .sq13-bar i,html.no-motion .sq13-ic,html.no-motion .sq13-bx,html.no-motion .sq13-arrow{transition:none}

/* v2: view expansion */
.sq13-xsteps{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}
.sq13-xs{font:600 .72rem Inter,sans-serif;padding:4px 10px;border-radius:99px;border:1px solid var(--line);color:var(--muted);background:var(--surface)}
.sq13-xs.past{border-color:var(--accent);color:var(--accent)}
.sq13-xs.on{background:var(--accent);border-color:var(--accent);color:#fff}
.sq13-xcode{margin:0 0 8px;font-size:.8rem;white-space:pre-wrap;overflow-wrap:anywhere}
.sq13-xm{background:var(--amber-fill);color:inherit;border-radius:4px;padding:0 2px}
.sq13-xpl{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}
.sq13-xp{min-width:0;border:1px solid var(--line);border-radius:10px;background:var(--surface);padding:8px 10px;display:grid;gap:6px}
.sq13-xp em{font-style:normal;font:600 .7rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}
.sq13-xr.sub{padding-left:18px;position:relative}
.sq13-xr.sub::before{content:"└";position:absolute;left:4px;top:3px;color:var(--muted)}
/* v2: why isn't my index used */
.sq13-wy{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.sq13-wc{min-width:0;border:1px solid var(--line);border-radius:12px;background:var(--surface);overflow:hidden}
.sq13-wc.bad{border-top:3px solid var(--bad)}
.sq13-wc.fix{border-top:3px solid var(--good)}
.sq13-wc pre{margin:8px 10px;font-size:.74rem;white-space:pre-wrap;overflow-wrap:anywhere}
.sq13-wp{padding:0 10px 8px;display:grid;gap:6px;justify-items:start}
.sq13-vh span.sq13-wpill{text-transform:none;letter-spacing:0;font-size:.72rem;padding:2px 8px;border-radius:99px}
.sq13-vh span.sq13-wpill.no{background:var(--bad-soft);color:var(--bad)}
.sq13-vh span.sq13-wpill.ok{background:var(--good-soft);color:var(--good)}
.sq13-wst{font-size:.8rem;margin-top:8px}
.sq13-wst:empty{display:none}
/* v2: index design */
.sq13-dix{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.sq13-dix .sq13-ck{font-family:"JetBrains Mono",monospace;font-size:.74rem}
.sq13-dq{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}
.sq13-dqc{min-width:0;border:1px solid var(--line);border-radius:12px;background:var(--surface);overflow:hidden;padding-bottom:8px;transition:border-color .3s}
.sq13-dqc pre{margin:8px 10px;font-size:.72rem;white-space:pre-wrap;overflow-wrap:anywhere}
.sq13-dqc .sq13-plan{margin:0 10px 4px}
.sq13-dqc.ok{border-color:var(--good);border-top:3px solid var(--good)}
.sq13-dqc.part{border-color:var(--amber);border-top:3px solid var(--amber)}
.sq13-dqc.no{border-color:var(--bad);border-top:3px solid var(--bad)}
.sq13-dqc.ok .sq13-vh span{color:var(--good)}.sq13-dqc.part .sq13-vh span{color:var(--amber)}.sq13-dqc.no .sq13-vh span{color:var(--bad)}
@media (max-width:640px){.sq13-wy{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){.sq13-dqc{transition:none}}
html.no-motion .sq13-dqc{transition:none}

/* sql s12 v2 (2026-10-30): Lesson S12 labs, classes sq12- (labs-sql-s12.js). v2: #sq12Deps dependency diagram, #sq12Drill schema-design drill, two-report disagreement in #sq12Anom */
.sq12 .an-foot:empty{display:none}
.sq12 [hidden]{display:none!important}
.sq12-tabs,.sq12-acts,.sq12-pre,.sq12-steps,.sq12-meas,.sq12-rels,.sq12-mnctl{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 10px}
.sq12-tb.on,.sq12-ab.on,.sq12-rb.on,.sq12-tc.on,.sq12-mb2.on,.sq12-pb.on{background:var(--accent);color:#fff;border-color:var(--accent)}
.sq12-lab{font:600 .72rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);align-self:center;margin-right:4px}
.sq12-chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 0}
.sq12-chip{display:inline-flex;gap:6px;align-items:baseline;padding:4px 10px;border:1px solid var(--line);border-radius:999px;background:var(--soft);font-size:.78rem;max-width:100%}
.sq12-chip em{font-style:normal;color:var(--muted)}
.sq12-chip b{font-weight:700;overflow-wrap:anywhere}
.sq12-chip.sg{background:var(--good-soft);border-color:var(--good)}
.sq12-chip.sb{background:var(--bad-soft);border-color:var(--bad)}
.sq12-chip.sa{background:var(--amber-soft);border-color:var(--amber)}
/* ER diagram */
.sq12-legend{display:flex;flex-wrap:wrap;gap:6px 16px;margin:0 0 8px;font-size:.78rem;color:var(--muted)}
.sq12-lgi{display:inline-flex;align-items:center;gap:6px}
.sq12-lg{width:46px;height:18px;overflow:visible}
.sq12-erwrap{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:6px;margin-bottom:8px}
.sq12-er,.sq12-mn{display:block;width:100%;min-width:720px;height:auto}
.sq12-ent rect{fill:var(--surface);stroke:var(--line);stroke-width:1.4}
.sq12-ent.jn rect{fill:var(--accent-soft);stroke:var(--accent)}
.sq12-eh{stroke:var(--line);stroke-width:1.2;fill:none}
.sq12-en{font:700 13px "JetBrains Mono",monospace;fill:var(--accent);text-anchor:middle}
.sq12-at{font:400 11px "JetBrains Mono",monospace;fill:var(--text)}
.sq12-at.pk{font-weight:700}
.sq12-tag{font:700 9px Inter,sans-serif;fill:var(--amber);text-anchor:end}
.sq12-tag.fk{fill:var(--good)}
.sq12-ln{fill:none;stroke:var(--text);stroke-width:1.5;opacity:.75}
.sq12-ln.dash{stroke-dasharray:5 4}
.sq12-gl path{fill:none;stroke:var(--text);stroke-width:1.5;opacity:.85}
.sq12-o{fill:var(--surface);stroke:var(--text);stroke-width:1.5}
.sq12-hit{fill:none;stroke:transparent;stroke-width:16;cursor:pointer}
.sq12-rel{cursor:pointer}
.sq12-rel.on .sq12-ln,.sq12-rel.on .sq12-gl path{stroke:var(--accent);stroke-width:2.2;opacity:1}
.sq12-rel.on .sq12-o{stroke:var(--accent)}
.sq12-rel:hover .sq12-ln{stroke:var(--accent)}
.sq12-vb{font:600 11px Inter,sans-serif;fill:var(--muted)}
.sq12-rel.on .sq12-vb{fill:var(--accent)}
.sq12-det{border:1px solid var(--line);border-radius:12px;background:var(--soft);padding:10px 14px}
.sq12-dt p{margin:2px 0;font-size:.92rem}
.sq12-direct,.sq12-junc{transition:opacity .5s}
.sq12-direct.gone{opacity:.15}
.sq12-junc{opacity:0}
.sq12-junc.on{opacity:1}
.sq12-mnmsg{margin-top:8px}
/* tables in labs */
.sq12-gs{overflow-x:auto;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
.sq12-gs table{border-collapse:collapse;width:100%;font:400 .72rem "JetBrains Mono",monospace}
.sq12-gs th,.sq12-gs td{padding:3px 8px;text-align:left;white-space:nowrap;border-bottom:1px solid var(--line)}
.sq12-gs th{background:var(--soft);color:var(--muted);font-weight:600}
.sq12-gs th.pk{color:var(--amber)}
.sq12-gs th.fk{color:var(--good)}
.sq12-gs th i{font-style:normal;font-size:.6rem;margin-left:4px;padding:0 4px;border-radius:4px;border:1px solid currentColor}
.sq12-gs tr:last-child td{border-bottom:0}
.sq12-rc{font-size:.7rem;color:var(--muted);margin:3px 2px 0}
.sq12-sh td.kc{color:var(--amber);font-weight:600}
.sq12-sh tr.hot td{background:var(--amber-soft)}
.sq12-sh tr.r-new td{background:var(--good-soft)}
.sq12-sh tr.r-gone td{background:var(--bad-soft);color:var(--muted);text-decoration:line-through}
.sq12-sh td.chg{background:var(--bad-soft);font-weight:700}
.sq12-sh td s{color:var(--muted);font-weight:400}
.sq12-sql{margin-top:6px}
.sq12-sql pre{margin:0;font-size:.78rem;white-space:pre-wrap;overflow-wrap:anywhere}
/* FD tester */
.sq12-fdrow{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-bottom:8px}
.sq12-xs,.sq12-ys,.sq12-pre{display:flex;flex-wrap:wrap;gap:5px;margin:0}
.sq12-cb{font:600 .74rem "JetBrains Mono",monospace;padding:4px 9px;border-radius:8px;border:1px solid var(--line);background:var(--surface);color:var(--text);cursor:pointer}
.sq12-cb.x.on{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
.sq12-cb.y.on{background:var(--amber-soft);border-color:var(--amber);color:var(--text)}
.sq12-arrow{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:10px 12px;border:1px solid var(--line);border-radius:12px;background:var(--soft);margin:6px 0 10px}
.sq12-ax,.sq12-ay{display:inline-flex;gap:4px;flex-wrap:wrap}
.sq12-ax i,.sq12-ay i{font:600 .8rem "JetBrains Mono",monospace;font-style:normal;padding:3px 9px;border-radius:8px;border:1px solid var(--accent);background:var(--accent-soft)}
.sq12-ay i{border-color:var(--amber);background:var(--amber-soft)}
.sq12-arrow svg{width:80px;height:20px;flex:none}
.sq12-arrow svg path{fill:none;stroke:var(--muted);stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.sq12-arrow path[pathLength]{stroke-dasharray:1;animation:sq12draw .5s ease-out both}
.sq12-arrow.ok svg path{stroke:var(--good)}
.sq12-arrow.no svg path{stroke:var(--bad)}
.sq12-vd{font-size:.85rem;margin-left:auto}
.sq12-arrow.ok .sq12-vd{color:var(--good)}
.sq12-arrow.no .sq12-vd{color:var(--bad)}
.sq12-more{font-size:.74rem;color:var(--muted);margin-top:3px}
/* split lab */
.sq12-sb{font:600 .74rem Inter,sans-serif;padding:5px 12px;border-radius:999px;border:1px solid var(--line);background:var(--surface);color:var(--muted);cursor:pointer}
.sq12-sb.past{border-color:var(--accent);color:var(--accent)}
.sq12-sb.on{background:var(--accent);border-color:var(--accent);color:#fff}
.sq12-stage{position:relative;display:flex;flex-direction:column;gap:54px;padding:4px 0 6px}
.sq12-tier{display:flex;flex-wrap:wrap;gap:14px;align-items:flex-start}
.sq12-card{flex:1 1 220px;min-width:0;border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:8px 10px}
.sq12-card.new{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.sq12-card.kept{opacity:.62}
.sq12-ch{display:flex;align-items:center;gap:8px;margin-bottom:6px}
.sq12-ch b{font:700 .85rem "JetBrains Mono",monospace}
.sq12-ch em{font:600 .62rem Inter,sans-serif;font-style:normal;padding:1px 7px;border-radius:999px;background:var(--accent-soft);color:var(--accent)}
.sq12-card.kept .sq12-ch em{background:var(--soft);color:var(--muted)}
.sq12-arr{position:absolute;left:0;top:0;pointer-events:none;overflow:visible}
.sq12-al{fill:none;stroke-width:2.4;stroke-dasharray:1;stroke-dashoffset:0;animation:sq12draw .7s ease-out both}
.sq12-ah{stroke:none}
.sq12-ag circle{stroke-width:0}
.sq12-ag text{font:700 11px Inter,sans-serif;fill:#fff;text-anchor:middle}
.sq12-ag.a0 .sq12-al{stroke:var(--accent)}.sq12-ag.a0 .sq12-ah,.sq12-ag.a0 circle{fill:var(--accent)}
.sq12-ag.a1 .sq12-al{stroke:var(--amber)}.sq12-ag.a1 .sq12-ah,.sq12-ag.a1 circle{fill:var(--amber)}
.sq12-ag.a2 .sq12-al{stroke:var(--good)}.sq12-ag.a2 .sq12-ah,.sq12-ag.a2 circle{fill:var(--good)}
@keyframes sq12draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
.sq12-leg{list-style:none;margin:10px 0 0;padding:0;display:grid;gap:6px}
.sq12-leg li{display:flex;gap:10px;align-items:flex-start;font-size:.85rem}
.sq12-leg li span{flex:none;width:20px;height:20px;border-radius:50%;color:#fff;font:700 .7rem Inter,sans-serif;display:grid;place-items:center}
.sq12-leg li.a0 span{background:var(--accent)}.sq12-leg li.a1 span{background:var(--amber)}.sq12-leg li.a2 span{background:var(--good)}
/* trade-offs */
.sq12-two{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.sq12-side{min-width:0;border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:8px 10px}
.sq12-side.nrm{border-top:3px solid var(--good)}
.sq12-side.wde{border-top:3px solid var(--amber)}
.sq12-sh2{display:flex;gap:8px;align-items:baseline;margin-bottom:6px}
.sq12-sh2 span{font-size:.72rem;color:var(--muted)}
.sq12-side pre{margin:0 0 6px;font-size:.72rem;white-space:pre-wrap;overflow-wrap:anywhere}
.sq12-plan{margin:2px 0 0;padding-left:18px;font:400 .72rem "JetBrains Mono",monospace;color:var(--text)}
.sq12-pt{font-size:.68rem;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin:2px 0}
.sq12-big{font:800 2.4rem "Inter Tight",Inter,sans-serif;line-height:1.1;padding:6px 0}
.sq12-big small{font:600 .8rem Inter,sans-serif;margin-left:8px;color:var(--muted)}
.sq12-big.sg{color:var(--good)}.sq12-big.sb{color:var(--bad)}
.sq12-refuse{font:600 .78rem "JetBrains Mono",monospace;color:var(--bad);background:var(--bad-soft);border-radius:8px;padding:6px 10px;overflow-wrap:anywhere}
.sq12-sl{display:flex;gap:10px;align-items:center;font-size:.82rem;flex-wrap:wrap}
.sq12-sl input{flex:1 1 140px}
.sq12-bars{display:grid;gap:6px;margin-top:6px}
.sq12-bar{display:grid;grid-template-columns:78px 1fr auto;gap:8px;align-items:center;font-size:.76rem}
.sq12-bar i{display:block;height:14px;border-radius:7px;min-width:3px;transition:width .5s}
.sq12-bar i.nrm{background:var(--good-fill)}.sq12-bar i.wde{background:var(--amber-fill)}
.sq12-bar b{font-family:"JetBrains Mono",monospace;font-size:.72rem}
.sq12-bar em{font-style:normal;color:var(--muted)}
.sq12-note{font-size:.78rem;color:var(--muted)}
.sq12-score{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.sq12-sc{display:inline-flex;gap:6px;padding:4px 10px;border-radius:8px;border:1px dashed var(--line);font-size:.76rem}
.sq12-sc em{font-style:normal;color:var(--muted)}
.sq12-sc.nrm{border:1px solid var(--good);background:var(--good-soft)}
.sq12-sc.wde{border:1px solid var(--amber);background:var(--amber-soft)}
/* star */
.sq12-star{display:grid;grid-template-columns:minmax(0,1fr) 22px minmax(0,1.15fr) 22px minmax(0,1fr);grid-template-rows:auto 22px auto 22px auto;margin-bottom:10px;align-items:center}
.d-date{grid-area:1/3}.d-car{grid-area:3/1}.d-cust{grid-area:3/5}.d-emp{grid-area:5/3}.sq12-fact{grid-area:3/3}
.l1{grid-area:2/3}.l4{grid-area:4/3}.l2{grid-area:3/2}.l3{grid-area:3/4}
.sq12-vl,.sq12-hl{display:block;background:var(--line);transition:background .4s;justify-self:center}
.sq12-vl{width:3px;height:100%}.sq12-hl{height:3px;width:100%}
.sq12-vl.lit,.sq12-hl.lit{background:var(--accent)}
.sq12-dim,.sq12-fact{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:8px;min-width:0;transition:border-color .4s,box-shadow .4s}
.sq12-dim.lit{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.sq12-fact{border-color:var(--amber);background:var(--amber-soft);text-align:center}
.sq12-dh b{font:700 .78rem "JetBrains Mono",monospace;overflow-wrap:anywhere}
.sq12-da{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}
.sq12-fa{font:400 .68rem "JetBrains Mono",monospace;margin-top:4px;overflow-wrap:anywhere}
.sq12-fa em{font-style:normal;font-weight:700}
.sq12-ab2{font:600 .7rem "JetBrains Mono",monospace;padding:3px 8px;border-radius:7px;border:1px solid var(--line);background:var(--soft);color:var(--text);cursor:pointer}
.sq12-ab2.on{background:var(--accent);border-color:var(--accent);color:#fff}
.sq12-gen{margin:0 0 8px;font-size:.78rem;white-space:pre-wrap;overflow-wrap:anywhere}
@media (max-width:640px){
  .sq12-two{grid-template-columns:1fr}
  .sq12-star{grid-template-columns:minmax(0,1fr) 12px minmax(0,1.2fr) 12px minmax(0,1fr)}
  .sq12-ab2{font-size:.64rem;padding:3px 6px}
  .sq12-stage{gap:46px}
  .sq12-card{flex-basis:100%}
  .sq12-card.kept{display:none}
  .sq12-arr{display:none}
  .sq12-vd{margin-left:0;flex-basis:100%}
}
@media (prefers-reduced-motion:reduce){.sq12-al,.sq12-arrow path[pathLength]{animation:none}.sq12-bar i,.sq12-direct,.sq12-junc,.sq12-vl,.sq12-hl,.sq12-dim{transition:none}}
html.no-motion .sq12-al,html.no-motion .sq12-arrow path[pathLength]{animation:none}
html.no-motion .sq12-bar i,html.no-motion .sq12-direct,html.no-motion .sq12-junc,html.no-motion .sq12-vl,html.no-motion .sq12-hl,html.no-motion .sq12-dim{transition:none}
.sq12-ft{font:600 .68rem "JetBrains Mono",monospace;color:var(--muted);display:block}

/* v2: two reports disagree (anomaly lab) */
.sq12-rep{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:10px;align-items:center;margin:10px 0 0}
.sq12-rcard{min-width:0;border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:8px 10px;display:grid;gap:6px}
.sq12-rcard em{font-style:normal;font-size:.76rem;color:var(--muted)}
.sq12-rcard pre{margin:0;font-size:.7rem;white-space:pre-wrap;overflow-wrap:anywhere}
.sq12-rcard b{font:800 1.3rem "Inter Tight",Inter,sans-serif;justify-self:start;padding:2px 12px;border-radius:8px}
.sq12-rcard b.no{background:var(--bad-soft);color:var(--bad)}
.sq12-rcard b.ok{background:var(--good-soft);color:var(--good)}
.sq12-neq{font:800 2rem "Inter Tight",Inter,sans-serif;text-align:center}
.sq12-neq.no{color:var(--bad)}.sq12-neq.ok{color:var(--good)}
/* v2: dependency diagram */
.sq12-dwrap{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:6px;margin-bottom:8px}
.sq12-dsv{display:block;width:100%;min-width:740px;height:auto}
.sq12-dc rect{fill:var(--soft);stroke:var(--line);stroke-width:1.3}
.sq12-dc text{font:600 11.5px "JetBrains Mono",monospace;fill:var(--text);text-anchor:middle}
.sq12-dc.key rect{fill:var(--amber-soft);stroke:var(--amber);stroke-width:2}
.sq12-dc.key text{text-decoration:underline}
.sq12-dc.bad rect{fill:var(--bad-soft);stroke:var(--bad);stroke-width:2}
.sq12-dc text.sq12-dli{font:700 10px Inter,sans-serif;fill:var(--bad);text-decoration:none}
.sq12-df path{fill:none;stroke-width:2;stroke-linejoin:round}
.sq12-df path[pathLength]{stroke-dasharray:1;animation:sq12draw .6s ease-out both}
.sq12-df .sq12-dah{stroke:none}
.sq12-df.neu path{stroke:var(--muted)}.sq12-df.neu circle,.sq12-df.neu .sq12-dah{fill:var(--muted)}
.sq12-df.ok path{stroke:var(--good)}.sq12-df.ok circle,.sq12-df.ok .sq12-dah{fill:var(--good)}
.sq12-df.bad path{stroke:var(--bad);stroke-width:2.8}.sq12-df.bad circle,.sq12-df.bad .sq12-dah{fill:var(--bad)}
.sq12-df.done{opacity:.22}.sq12-df.done path{stroke:var(--muted)}.sq12-df.done circle,.sq12-df.done .sq12-dah{fill:var(--muted)}
.sq12-dfl{font:700 10.5px Inter,sans-serif;fill:var(--bad);text-anchor:middle}
.sq12-dleg{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 8px}
.sq12-dlg{font:600 .72rem "JetBrains Mono",monospace;padding:3px 9px;border-radius:999px;border:1px solid var(--line);color:var(--muted)}
.sq12-dlg.bad{border-color:var(--bad);background:var(--bad-soft);color:var(--text)}
.sq12-dlg.ok{border-color:var(--good);background:var(--good-soft);color:var(--text)}
.sq12-dlg.done{opacity:.6;text-decoration:line-through}
.sq12-gs td.dup{background:var(--bad-soft);font-weight:700}
.sq12-fixl{margin-top:8px;padding:8px 12px;border-left:3px solid var(--good);background:var(--good-soft);border-radius:0 8px 8px 0;font-size:.86rem}
/* v2: schema-design drill */
.sq12-dp.on,.sq12-dk.on{background:var(--accent);color:#fff;border-color:var(--accent)}
.sq12-dbrief{margin:0 0 10px;font-size:.9rem}
.sq12-dks{display:flex;flex-wrap:wrap;gap:6px;margin:4px 0 12px}
.sq12-dk{font:600 .76rem "JetBrains Mono",monospace;padding:5px 11px;border-radius:8px;border:1px solid var(--line);background:var(--surface);color:var(--text);cursor:pointer}
.sq12-fq{display:grid;gap:8px;margin:4px 0 12px}
.sq12-fql{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:10px;align-items:center;font-size:.85rem}
.sq12-fql select{min-width:0;width:100%;font:500 .8rem Inter,sans-serif;padding:6px 8px;border-radius:8px;border:1px solid var(--line);background:var(--surface);color:var(--text)}
.sq12-dres{margin-top:10px}
.sq12-dscore{margin-bottom:8px}
.sq12-dnote{margin:6px 0 0;font-size:.84rem}
.sq12-dsvg{display:block;width:100%;min-width:720px;height:auto}
.sq12-ent.sq12-miss{opacity:.4}
.sq12-ent.sq12-miss rect{stroke-dasharray:5 4}
.sq12-dwhy{margin:8px 0;padding-left:20px;font-size:.86rem;display:grid;gap:4px}
.sq12-ddl summary{cursor:pointer;font-size:.82rem;color:var(--muted)}
.sq12-ddl pre{font-size:.72rem;white-space:pre-wrap;overflow-wrap:anywhere}
@media (max-width:640px){
  .sq12-rep{grid-template-columns:1fr}
  .sq12-neq{font-size:1.4rem}
  .sq12-fql{grid-template-columns:1fr;gap:4px}
}
@media (prefers-reduced-motion:reduce){.sq12-df path[pathLength]{animation:none}}
html.no-motion .sq12-df path[pathLength]{animation:none}

/* sql s15 v3 (2026-10-30): Lesson S15 labs, classes sq15- (labs-sql-s15.js). Replaces BOTH old s15 blocks (v1 and the merge-time v2). v3: pool cores + pool-size comparison, cache stampede dots, replication timeline SVG; v2 ring/expand/outbox rules kept. */
.sq15-ctls{display:flex;flex-wrap:wrap;gap:10px 22px;margin:4px 0 10px}
.sq15-ctls label{display:flex;align-items:center;gap:8px;font:600 .78rem Inter,sans-serif;color:var(--muted)}
.sq15-ctls output{font:700 .8rem "JetBrains Mono",monospace;color:var(--text);min-width:2.2em}
.sq15-rg{width:150px;max-width:100%;accent-color:var(--accent)}
.sq15-btns{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:6px 0 10px}
.sq15-btns>span{font:600 .76rem Inter,sans-serif;color:var(--muted);margin-right:2px}
.sq15-btns .btn.on{background:var(--accent);color:#fff;border-color:var(--accent)}
.sq15-sel,.sq15-in{font:500 .8rem "JetBrains Mono",monospace;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text);max-width:100%}
.sq15-in{min-width:160px;flex:1 1 160px}
.sq15-stats,.sq15-sum{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}
.sq15-stats span,.sq15-sum span{font:600 .76rem Inter,sans-serif;padding:3px 10px;border-radius:99px;background:var(--soft);color:var(--muted)}
.sq15-stats b,.sq15-sum b{color:var(--text)}
.sq15-stats .warn,.sq15-sum .warn{background:var(--amber-soft)}
.sq15-stats .bad,.sq15-sum .bad{background:var(--bad-soft)}
.sq15-stats .good,.sq15-sum .good{background:var(--good-soft)}
.sq15-h5{margin:12px 0 6px;font:700 .78rem Inter,sans-serif;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}
.sq15-code{margin:4px 0 8px;font-size:.74rem;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere}
.sq15-lbl{font:700 .66rem Inter,sans-serif;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-top:4px}
.sq15-chip{display:inline-block;font:600 .72rem "JetBrains Mono",monospace;padding:2px 8px;margin:2px;border-radius:99px;background:var(--accent-soft);color:var(--text);border:1px solid var(--line)}
.sq15-chip.old,.sq15-chip.dup{background:var(--bad-soft);border-color:var(--bad);color:var(--text)}
.sq15-chip.fresh{background:var(--good-soft);border-color:var(--good)}
.sq15-chip.mis{background:var(--amber-soft);border-color:var(--amber)}
.sq15-more{font:600 .72rem Inter,sans-serif;color:var(--muted);margin-left:4px}
.sq15-none{font:500 .76rem Inter,sans-serif;color:var(--muted)}
.sq15-pt{border-collapse:collapse;width:100%;font:500 .76rem Inter,sans-serif}
.sq15-pt th,.sq15-pt td{border:1px solid var(--line);padding:5px 8px;text-align:left}
.sq15-pt th{background:var(--soft);color:var(--muted);font-weight:700}
.sq15-badtxt{color:var(--bad)}
/* pool */
.sq15-pool{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1.3fr) auto auto;gap:8px;align-items:stretch}
.sq15-qbox,.sq15-pbox{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:8px 10px;min-width:0}
.sq15-qbox h5,.sq15-pbox h5,.sq15-card h5,.sq15-box h5,.sq15-node h5,.sq15-pc2 h5,.sq15-dcol h5{margin:0 0 6px;font:700 .74rem Inter,sans-serif;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
.sq15-queue{display:flex;flex-wrap:wrap;gap:2px;min-height:38px;align-content:flex-start}
.sq15-slots{display:grid;grid-template-columns:repeat(auto-fill,minmax(54px,1fr));gap:6px}
.sq15-slot{height:42px;border:1px dashed var(--line);border-radius:8px;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden;font:600 .66rem Inter,sans-serif;color:var(--muted)}
.sq15-slot.busy{border:1px solid var(--accent);background:var(--accent-soft);color:var(--text)}
.sq15-slot.busy b{font:700 .72rem "JetBrains Mono",monospace;position:relative;z-index:1}
.sq15-slot i{position:absolute;left:0;bottom:0;height:4px;background:var(--accent);transition:width .05s linear}
.sq15-arrow{align-self:center;font:700 1.2rem Inter,sans-serif;color:var(--muted)}
.sq15-db{align-self:center;text-align:center;font-size:1.8rem}
.sq15-db small{display:block;font:600 .64rem Inter,sans-serif;color:var(--muted)}
/* two-column cards */
.sq15-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.sq15-card{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:10px 12px;min-width:0}
.sq15-tag{font:700 .64rem Inter,sans-serif;padding:2px 8px;border-radius:99px;margin-left:6px;text-transform:uppercase}
.sq15-tag.bad{background:var(--bad-soft);color:var(--bad)}
.sq15-tag.good{background:var(--good-soft);color:var(--good)}
.sq15-hit{margin-top:6px;padding:6px 10px;border-radius:8px;background:var(--bad-soft);border:1px solid var(--bad);font:600 .76rem Inter,sans-serif;color:var(--text)}
/* n+1 */
.sq15-n1{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:12px;align-items:start}
.sq15-axis{display:flex;justify-content:space-between;font:600 .66rem Inter,sans-serif;color:var(--muted);margin:0 0 4px 26px}
.sq15-lane,.sq15-st{display:flex;align-items:center;gap:6px;margin:3px 0}
.sq15-ln{flex:0 0 20px;text-align:center;font:700 .66rem "JetBrains Mono",monospace;color:var(--muted)}
.sq15-track{position:relative;flex:1 1 auto;height:14px;background:var(--soft);border-radius:4px}
.sq15-bar{position:absolute;top:2px;height:10px;border-radius:3px;background:var(--accent);animation:sq15grow .35s ease-out both;transform-origin:left}
.sq15-lane b{flex:0 0 66px;font:600 .68rem Inter,sans-serif;color:var(--muted);text-align:right}
.sq15-st code{font:500 .7rem "JetBrains Mono",monospace;overflow-wrap:anywhere;color:var(--text)}
.sq15-stmts{max-height:260px;overflow:auto;border:1px solid var(--line);border-radius:10px;padding:6px 8px;background:var(--code-bg)}
@keyframes sq15grow{from{transform:scaleX(0);opacity:0}to{transform:none;opacity:1}}
.sq15-scale{margin-top:6px;overflow-x:auto}
/* pagination */
.sq15-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.sq15-pc2{border:1px solid var(--line);border-top-width:3px;border-radius:12px;background:var(--surface);padding:8px 10px;min-width:0}
.sq15-pc2.good{border-top-color:var(--good)}.sq15-pc2.warn{border-top-color:var(--amber)}.sq15-pc2.bad{border-top-color:var(--bad)}
.sq15-track2{display:flex;height:12px;background:var(--soft);border-radius:4px;overflow:hidden;margin:6px 0 4px}
.sq15-track2 .skip{background:var(--muted);opacity:.45;display:block}
.sq15-track2 .read{background:var(--accent);display:block;min-width:3px}
.sq15-lg{display:flex;flex-wrap:wrap;gap:4px 12px;font:600 .68rem Inter,sans-serif;color:var(--muted)}
.sq15-lg b{color:var(--text)}
.sq15-plan{margin:6px 0}
.sq15-plan small{display:block;font:700 .6rem Inter,sans-serif;color:var(--muted);text-transform:uppercase}
.sq15-plan code{font:500 .7rem "JetBrains Mono",monospace;overflow-wrap:anywhere;color:var(--text)}
.sq15-ids{min-height:26px}
.sq15-big{font:600 .78rem Inter,sans-serif;color:var(--muted)}
.sq15-big b{font:700 1rem "JetBrains Mono",monospace;color:var(--text)}
.sq15-cmsg{margin-top:10px;font:500 .84rem/1.5 Inter,sans-serif;color:var(--muted)}
.sq15-dgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;margin:8px 0}
.sq15-dcol{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:8px 10px;min-width:0}
.sq15-dcol small{display:block;font:500 .76rem Inter,sans-serif;color:var(--muted);margin-top:4px}
.sq15-dcol.mut{border-color:var(--amber);background:var(--amber-soft)}
.sq15-event{font:600 .8rem Inter,sans-serif;color:var(--text)}
/* cache, replication, cap */
.sq15-cb,.sq15-nodes{display:flex;flex-wrap:wrap;gap:12px;align-items:stretch}
.sq15-box,.sq15-node{flex:1 1 150px;border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:10px 12px;text-align:center;min-width:0}
.sq15-box .sq15-val,.sq15-node b{display:block;font:700 1.3rem "JetBrains Mono",monospace;color:var(--text);margin:4px 0}
.sq15-box .sq15-val b.stale{color:var(--bad)}
.sq15-box small,.sq15-node small{display:block;font:500 .68rem Inter,sans-serif;color:var(--muted)}
.sq15-box.cache{border-top:3px solid var(--accent-2)}.sq15-box.dbx{border-top:3px solid var(--good)}
.sq15-clock{align-self:center;font:700 .8rem "JetBrains Mono",monospace;color:var(--muted)}
.sq15-log{margin:8px 0;font:500 .78rem/1.5 Inter,sans-serif;color:var(--muted)}
.sq15-log div{padding:3px 0;border-bottom:1px dashed var(--line)}
.sq15-node{transition:background .3s,border-color .3s}
.sq15-node.old{border-color:var(--amber)}
.sq15-node.hot{background:var(--accent-soft);border-color:var(--accent)}
.sq15-link{align-self:center;font:700 .74rem Inter,sans-serif;color:var(--muted);text-align:center}
.sq15-link.cut{color:var(--bad)}
/* shards */
.sq15-shards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.sq15-shard{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:8px 10px;min-width:0}
.sq15-shard.touched{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}
.sq15-shard.hotspot{background:var(--bad-soft);border-color:var(--bad)}
.sq15-shard h5{display:flex;justify-content:space-between;gap:6px;margin:0 0 6px;font:700 .78rem Inter,sans-serif;color:var(--text)}
.sq15-shard h5 small{font:600 .64rem Inter,sans-serif;color:var(--muted)}
.sq15-shard h5 span{font:600 .72rem Inter,sans-serif;color:var(--muted)}
.sq15-bar2{height:6px;background:var(--soft);border-radius:4px;overflow:hidden;margin-bottom:6px}
.sq15-bar2 i{display:block;height:100%;background:var(--accent);transition:width .35s}
.sq15-rowsx{display:flex;flex-wrap:wrap;gap:3px}
.sq15-row{font:500 .62rem "JetBrains Mono",monospace;padding:2px 5px;border-radius:6px;background:var(--soft);color:var(--muted)}
.sq15-row b{color:var(--text);margin-right:3px}
.sq15-row.new{background:var(--amber-soft)}
.sq15-qline pre{margin:0 0 6px}
.sq15-hits{display:flex;gap:6px;align-items:center;flex-wrap:wrap;font:600 .76rem Inter,sans-serif;color:var(--text)}
.sq15-pill{width:24px;height:24px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:var(--soft);color:var(--muted);font:700 .72rem Inter,sans-serif}
.sq15-pill.on{background:var(--accent);color:#fff}
.sq15-ans{font:500 .78rem Inter,sans-serif;color:var(--muted);margin-top:4px}
/* pick */
.sq15-pick{display:grid;gap:10px}
.sq15-sc{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:10px 12px}
.sq15-sc.okc{border-color:var(--good)}.sq15-sc.noc{border-color:var(--bad)}
.sq15-sc h5{margin:0 0 6px;font:700 .86rem Inter,sans-serif;color:var(--text);text-transform:none;letter-spacing:0;display:flex;gap:8px}
.sq15-sc h5 span{flex:0 0 22px;height:22px;border-radius:50%;background:var(--accent);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:.72rem}
.sq15-req span{display:inline-block;font:600 .68rem Inter,sans-serif;padding:2px 8px;margin:2px 4px 2px 0;border-radius:99px;background:var(--soft);color:var(--muted)}
.sq15-opts{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0 4px}
.sq15-opts .btn.sel{background:var(--accent);color:#fff;border-color:var(--accent)}
.sq15-why{margin-top:8px;font:500 .82rem/1.5 Inter,sans-serif;color:var(--text)}
@media (max-width:640px){
  .sq15-pool{grid-template-columns:1fr}.sq15-arrow{transform:rotate(90deg);justify-self:center}.sq15-db{justify-self:center}
  .sq15-two,.sq15-n1,.sq15-cards{grid-template-columns:1fr}
  .sq15-shards{grid-template-columns:1fr}
  .sq15-rg{width:120px}
}
@media (prefers-reduced-motion:reduce){.sq15-bar{animation:none}.sq15-bar2 i,.sq15-slot i,.sq15-node{transition:none}}
html.no-motion .sq15-bar{animation:none}
html.no-motion .sq15-bar2 i,html.no-motion .sq15-slot i,html.no-motion .sq15-node{transition:none}
.sq15-after{margin-top:6px;font:600 .76rem Inter,sans-serif;color:var(--muted)}
.sq15-after b{color:var(--text)}
.sq15-rep .sq15-clock{margin:8px 0 4px}

/* v2 rules (ring, expand-contract, outbox), from the merge of 2026-10-30 */
.sq15-ring{display:grid;grid-template-columns:minmax(0,300px) minmax(0,1fr);gap:16px;align-items:start}
.sq15-rsvg{min-width:0}.sq15-rg-svg{width:100%;max-width:300px;height:auto;display:block;margin:0 auto}
.sq15-rg-ring{fill:none;stroke:var(--line);stroke-width:14}
.sq15-rg-arc{fill:none;stroke-width:14;opacity:.55}
.sq15-rg-arc.sa,.sq15-rg-key.sa,.sq15-rg-node.sa,.sq15-rg-sw.sa,.sq15-cbar i.sa{--k:var(--accent)}
.sq15-rg-arc.sb,.sq15-rg-key.sb,.sq15-rg-node.sb,.sq15-rg-sw.sb,.sq15-cbar i.sb{--k:var(--good)}
.sq15-rg-arc.sc,.sq15-rg-key.sc,.sq15-rg-node.sc,.sq15-rg-sw.sc,.sq15-cbar i.sc{--k:var(--amber)}
.sq15-rg-arc.sd,.sq15-rg-key.sd,.sq15-rg-node.sd,.sq15-rg-sw.sd,.sq15-cbar i.sd{--k:var(--accent-2)}
.sq15-rg-arc{stroke:var(--k)}
.sq15-rg-key{fill:var(--k);stroke:var(--surface);stroke-width:1.5}
.sq15-rg-key.mv{stroke:var(--text);stroke-width:2}
.sq15-rg-node{fill:var(--surface);stroke:var(--k);stroke-width:3}
.sq15-rg-lb{font:700 13px Inter,sans-serif;fill:var(--text)}
.sq15-rg-c{font:700 15px Inter,sans-serif;fill:var(--text)}
.sq15-rg-cs{font:500 10px Inter,sans-serif;fill:var(--muted)}
.sq15-rside{min-width:0}
.sq15-rrow{display:grid;grid-template-columns:52px minmax(0,1fr) auto;gap:8px;align-items:center;margin:5px 0;font:600 .8rem Inter,sans-serif}
.sq15-rrow>b{font:700 .78rem "JetBrains Mono",monospace}
.sq15-rg-sw{display:inline-block;text-align:center;padding:1px 0;border-radius:6px;color:#fff;background:var(--k)}
.sq15-cbar{height:12px;border-radius:99px;background:var(--soft);border:1px solid var(--line);overflow:hidden}
.sq15-cbar i{display:block;height:100%;border-radius:99px;background:var(--k,var(--accent));transition:width .4s}
.sq15-cbar i.sbad{background:var(--bad)}
.sq15-rrow>span{font:600 .76rem "JetBrains Mono",monospace;color:var(--muted);white-space:nowrap}
.sq15-rmv{margin-top:8px}
.sq15-chip.mis{background:color-mix(in srgb,var(--accent-2) 15%,var(--surface));border:1px solid var(--accent-2)}
.sq15-bang .sq-err{margin-top:8px}
.sq15-xstep h5,.sq15-bang h5{display:flex;align-items:center;flex-wrap:wrap}
.sq15-xtab{margin-top:10px;overflow-x:auto}
.sq15-xt th.nw,.sq15-xt td.nw{background:color-mix(in srgb,var(--good) 10%,transparent)}
.sq15-xt td.miss{background:var(--bad-soft);color:var(--bad)}
.sq15-sum span.good{background:var(--good-soft);color:var(--good)}.sq15-sum span.bad{background:var(--bad-soft);color:var(--bad)}
.sq15-vers{display:flex;flex-direction:column;gap:6px;margin-top:4px}
.sq15-ver{display:block;padding:7px 12px;border-radius:10px;font:500 .84rem Inter,sans-serif;border:1px solid var(--line);background:var(--surface)}
.sq15-ver b{margin-right:6px}
.sq15-ver.ok{border-color:var(--good);background:var(--good-soft)}
.sq15-ver.no{border-color:var(--bad);background:var(--bad-soft)}
.sq15-ver.gone{opacity:.55}
.sq15-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr) auto) minmax(0,1fr);gap:6px;align-items:stretch}
.sq15-fb{min-width:0;padding:8px 10px;border-radius:12px;border:1px solid var(--line);background:var(--surface);display:flex;flex-direction:column;gap:3px;transition:border-color .3s,box-shadow .3s}
.sq15-fb h5{margin:0 0 2px;font:700 .74rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}
.sq15-fb small{font:500 .74rem Inter,sans-serif;color:var(--text);overflow-wrap:anywhere}
.sq15-fb.on{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.sq15-fb.down{border-color:var(--bad);background:var(--bad-soft)}
.sq15-far{align-self:center;color:var(--muted);font-weight:700}
.sq15-otab{margin-top:10px}
@media (max-width:760px){.sq15-flow{grid-template-columns:1fr}.sq15-far{transform:rotate(90deg);justify-self:center}}
@media (max-width:640px){.sq15-ring{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){.sq15-cbar i,.sq15-fb{transition:none}}
html.no-motion .sq15-cbar i,html.no-motion .sq15-fb{transition:none}
/* v3 additions (2026-10-30): pool cores + comparison bars, cache stampede dots, replication timeline SVG */
.sq15-db{display:flex;flex-direction:column;align-items:center;gap:4px;min-width:96px}
.sq15-cores{display:grid;grid-template-columns:repeat(4,14px);gap:3px;justify-content:center}
.sq15-cores i{width:14px;height:14px;border-radius:3px;border:1px solid var(--line);background:var(--soft)}
.sq15-cores i.on{background:var(--accent);border-color:var(--accent)}
.sq15-over{grid-column:1/-1;font:600 .64rem Inter,sans-serif;color:var(--bad);font-style:normal;text-align:center;max-width:110px}
.sq15-cmpg{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}
.sq15-cmpr{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:8px 10px;display:flex;flex-direction:column;gap:4px;min-width:0}
.sq15-cmpr>b{font:700 .82rem "JetBrains Mono",monospace;color:var(--text)}
.sq15-cmpr>span{font:600 .72rem Inter,sans-serif;color:var(--muted)}
.sq15-cmpr>small{font:600 .7rem Inter,sans-serif;color:var(--bad)}
.sq15-cbar i.sok{background:var(--good)}.sq15-cbar i.sslow{background:var(--amber)}
.sq15-dots{display:grid;grid-template-columns:repeat(20,minmax(0,1fr));gap:4px;max-width:420px;margin:6px 0}
.sq15-d{display:inline-block;width:12px;height:12px;border-radius:50%;background:var(--soft);transition:background .3s}
.sq15-dots>.sq15-d{width:auto;aspect-ratio:1}
.sq15-d.sdb{background:var(--bad)}.sq15-d.swt{background:var(--amber)}.sq15-d.shit{background:var(--good)}
.sq15-dlg{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:4px 14px;margin-top:6px;font:600 .72rem Inter,sans-serif;color:var(--muted)}
.sq15-dlg span{display:inline-flex;align-items:center;gap:5px}.sq15-dlg b{color:var(--text)}
.sq15-sw{display:inline-block;width:14px;height:10px;border-radius:3px}
.sq15-sw.slag{background:var(--bad-soft);border:1px solid var(--bad)}.sq15-sw.sold{background:var(--bad)}.sq15-sw.sfresh{background:var(--good)}
.sq15-tline{margin:10px 0 4px}
.sq15-tl-svg{width:100%;height:auto;display:block;max-width:760px}
.sq15-tl-lb{font:700 11px Inter,sans-serif;fill:var(--muted)}
.sq15-tl-tx{font:600 9.5px Inter,sans-serif;fill:var(--text)}
.sq15-tl-ln{stroke:var(--line);stroke-width:1.5}
.sq15-tl-lag{fill:var(--bad-soft);stroke:var(--bad);stroke-width:.8;stroke-dasharray:3 2}
.sq15-tl-w{stroke:var(--accent);stroke-width:2.2;fill:none}
.sq15-tl-wd{fill:var(--accent)}
.sq15-tl-ship{stroke:var(--muted);stroke-width:1.4;stroke-dasharray:4 3;fill:none}
.sq15-tl-ap{fill:var(--good);stroke:var(--surface);stroke-width:1.5}
.sq15-tl-rd{stroke-width:2;fill:none}.sq15-tl-rd.sold{stroke:var(--bad)}.sq15-tl-rd.sfresh{stroke:var(--good)}
.sq15-tl-dot.sold{fill:var(--bad)}.sq15-tl-dot.sfresh{fill:var(--good)}
.sq15-tl-now{stroke:var(--accent-2);stroke-width:1.4;stroke-dasharray:2 3}
.sq15-tl-w,.sq15-tl-rd{stroke-dasharray:1;animation:sq15draw .5s ease-out both}
@keyframes sq15draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@media (max-width:640px){.sq15-dots{gap:3px}.sq15-cmpg{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){.sq15-d{transition:none}.sq15-tl-w,.sq15-tl-rd{animation:none;stroke-dasharray:none}}
html.no-motion .sq15-d{transition:none}
html.no-motion .sq15-tl-w,html.no-motion .sq15-tl-rd{animation:none;stroke-dasharray:none}

/* sql s17 v2 (2026-10-30): Lesson S17 labs, classes sq17- (labs-sql-s17.js). v2: pattern-hint disclosure on every problem (.sq17-pat), attack lab problem picker (.sq17-apick .sq17-ahead .sq17-atask .sq17-ahint) */
.sq17-sticky{position:sticky;top:54px;z-index:20;margin:8px 0 14px;padding:9px 14px;border:1px solid var(--line);border-radius:12px;background:color-mix(in srgb,var(--surface) 92%,transparent);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);box-shadow:var(--shadow);font-size:.88rem;color:var(--muted)}
.sq17-sticky b{color:var(--accent)}
.sq17-cnt{font:600 .7rem Inter,sans-serif;color:var(--muted);margin-left:8px;text-transform:uppercase;letter-spacing:.05em}
.sq17-tb{font-size:.84rem;color:var(--muted);margin:-4px 0 8px}
.sq17 .an-foot:empty{display:none}
.sq17-ctl{display:flex;flex-wrap:wrap;gap:8px 14px;align-items:center;margin-bottom:10px}
.sq17-seg{display:flex;flex-wrap:wrap;gap:6px}
.sq17-mb.on,.sq17-br.on,.sq17-tg.on{background:var(--accent);color:#fff;border-color:var(--accent)}
.sq17-n{display:inline-flex;align-items:center;gap:8px;font:600 .85rem Inter,sans-serif;color:var(--muted)}
.sq17-n .btn{padding:3px 11px}
.sq17-nv{min-width:1.2em;text-align:center;color:var(--text);font-family:"JetBrains Mono",monospace}
.sq17-sel{display:inline-flex;flex-wrap:wrap;gap:8px;align-items:center}
.sq17-sel label{font:600 .82rem Inter,sans-serif;color:var(--muted)}
.sq17-sel select{font:500 .85rem "JetBrains Mono",monospace;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:4px 6px}
.sq17-sum{margin-top:10px;padding:9px 12px;border-radius:10px;background:var(--accent-soft);font-size:.9rem;line-height:1.5;min-height:1.5em}
.sq17-sum.err{background:var(--bad-soft);color:var(--bad)}
.sq17-sum:empty{display:none}
.sq17-code{margin:8px 0;font-size:.78rem;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere}
.sq17-empty{padding:10px;color:var(--muted);font-size:.85rem}
.sq17-cap{margin:8px 0 4px;font-size:.84rem;color:var(--muted)}
/* mini table */
.sq17-tw{overflow-x:auto;border:1px solid var(--line);border-radius:10px;background:var(--surface);margin:8px 0}
.sq17-tw table{border-collapse:collapse;width:100%;font:500 .78rem "JetBrains Mono",monospace}
.sq17-tw th{background:var(--soft);color:var(--muted);text-align:left;padding:5px 10px;font-size:.68rem;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}
.sq17-tw td{padding:5px 10px;border-top:1px solid var(--line);white-space:nowrap}
.sq17-tw tr.hot td{background:var(--good-soft);color:var(--text)}
.sq17-tw tr.nul td{background:var(--amber-soft)}
.sq17-tw tr.dim td{opacity:.4;text-decoration:line-through}
/* attack stepper */
.sq17-stg{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.sq17-pill{font:600 .78rem Inter,sans-serif;padding:5px 12px;border-radius:999px;border:1px solid var(--line);color:var(--muted);background:var(--surface);transition:background .3s,color .3s,border-color .3s}
.sq17-pill.on{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}
.sq17-pill.cur{background:var(--accent);color:#fff}
.sq17-pan{min-height:80px}
.sq17-qa,.sq17-pats,.sq17-tests{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px}
.sq17-qa div,.sq17-pats div,.sq17-tests div{border:1px solid var(--line);border-radius:10px;padding:9px 12px;background:var(--surface);display:flex;flex-direction:column;gap:3px;font-size:.84rem}
.sq17-qa b,.sq17-pats b,.sq17-tests b{font-size:.85rem}
.sq17-qa span,.sq17-pats span,.sq17-tests span{color:var(--muted)}
.sq17-pats div{opacity:.55}
.sq17-pats div.hit{opacity:1;border-color:var(--good);background:var(--good-soft)}
.sq17-tests i{font-style:normal;color:var(--good);font-weight:700}
/* rank */
.sq17-rk{display:grid;gap:3px}
.sq17-rr{display:grid;grid-template-columns:minmax(60px,.9fr) 70px minmax(40px,2fr) 92px 60px 92px;gap:8px;align-items:center;padding:3px 8px;border-radius:8px;border:1px solid transparent;font:500 .78rem "JetBrains Mono",monospace;transition:background .25s,border-color .25s}
.sq17-rr.sq17-h{font:700 .62rem Inter,sans-serif;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
.sq17-rr.on{background:var(--good-soft);border-color:var(--good)}
.sq17-rr .bar{height:8px;border-radius:4px;background:var(--soft);overflow:hidden}
.sq17-rr .bar i{display:block;height:100%;background:var(--accent-fill);border-radius:4px}
.sq17-rr .rk{text-align:center;color:var(--muted)}
.sq17-rr .rk.sel{color:var(--text);font-weight:700}
/* dupes */
.sq17-dp{display:grid;gap:3px}
.sq17-dr{display:grid;grid-template-columns:36px minmax(90px,1.4fr) minmax(70px,1fr) 56px;gap:8px;padding:4px 10px;border-radius:8px;border:1px solid var(--line);background:var(--surface);font:500 .8rem "JetBrains Mono",monospace;transition:opacity .4s,background .3s}
.sq17-dr.sq17-h{border-color:transparent;background:none;font:700 .62rem Inter,sans-serif;color:var(--muted);text-transform:uppercase}
.sq17-dr.amber{background:var(--amber-soft);border-color:var(--amber)}
.sq17-dr.red{background:var(--bad-soft);border-color:var(--bad)}
.sq17-dr.gone{background:var(--bad-soft);border-color:var(--bad);opacity:.35;text-decoration:line-through}
/* charts */
.sq17-lbl{font:700 .68rem Inter,sans-serif;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin:6px 0 2px}
.sq17-ch{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:6px}
.sq17-ch .col{display:flex;flex-direction:column;align-items:center;gap:2px;min-width:0}
.sq17-ch .v{font:600 .62rem "JetBrains Mono",monospace;color:var(--muted);white-space:nowrap}
.sq17-ch .m{font:600 .66rem Inter,sans-serif;color:var(--muted)}
.sq17-ch .plot{position:relative;width:100%;height:84px;border-bottom:1px solid var(--line)}
.sq17-ch .plot i{position:absolute;left:14%;right:14%;border-radius:4px 4px 0 0;background:var(--accent-fill);transition:height .5s}
.sq17-ch.dv .plot{border-bottom:0}
.sq17-ch.dv .plot::after{content:"";position:absolute;left:0;right:0;top:50%;border-top:1px solid var(--line)}
.sq17-ch .plot i.neg{background:var(--bad-fill);border-radius:0 0 4px 4px}
.sq17-ch.dv .plot i:not(.neg){background:var(--good-fill)}
/* islands */
.sq17-cal{min-width:0}
.sq17-cr{display:grid;grid-template-columns:46px repeat(10,minmax(0,1fr));gap:3px;margin-bottom:5px}
.sq17-cr.sq17-h span{font:600 .6rem Inter,sans-serif;color:var(--muted);text-align:center}
.sq17-cr .u{font:700 .68rem Inter,sans-serif;align-self:center}
.sq17-cr .c0{height:30px;border-radius:6px;background:var(--soft)}
.sq17-cr .c1{height:30px;border-radius:6px;position:relative;display:grid;place-items:center;font:600 .58rem "JetBrains Mono",monospace;background:var(--accent-fill);color:#fff;transition:background .4s;overflow:visible}
.sq17-cr .c1 em{position:absolute;top:100%;left:0;margin-top:1px;font:700 .56rem Inter,sans-serif;font-style:normal;color:var(--text);white-space:nowrap}
.sq17-cr:has(em){margin-bottom:16px}
.sq17-cr .c1.plain{background:var(--accent-fill)}
.sq17-cr .i0{background:var(--accent-fill)}.sq17-cr .i1{background:var(--good-fill)}.sq17-cr .i2{background:var(--amber-fill)}.sq17-cr .i3{background:var(--bad-fill)}.sq17-cr .i4{background:var(--accent-2-fill)}.sq17-cr .i5{background:var(--muted)}
/* pairs */
.sq17-pr{display:grid;grid-template-columns:minmax(200px,260px) minmax(0,1fr);gap:14px;align-items:start}
.sq17-pg svg{width:100%;height:auto;display:block}
.sq17-ar{fill:none;stroke-width:1.8;stroke-linecap:round;transition:opacity .3s}
.sq17-ar.g{stroke:var(--muted)}.sq17-ar.n{stroke:var(--good)}
.sq17-ar.dim{opacity:.25;stroke-dasharray:3 3}.sq17-ar.thick{stroke-width:3.2}.sq17-ar.strike{opacity:.2}
.sq17-hn{fill:var(--good)}.sq17-hg{fill:var(--muted)}
.sq17-nd{fill:var(--surface);stroke:var(--accent);stroke-width:1.8}
.sq17-nt{font:700 11px "JetBrains Mono",monospace;fill:var(--text);text-anchor:middle}
/* anti / division */
.sq17-vr{display:grid;grid-template-columns:minmax(60px,1.2fr) repeat(var(--n),minmax(48px,1fr)) 70px;gap:6px;align-items:center;padding:5px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);margin-bottom:3px;font:500 .8rem "JetBrains Mono",monospace}
.sq17-vr.sq17-h{border-color:transparent;background:none;font:700 .62rem Inter,sans-serif;color:var(--muted);text-transform:uppercase}
