.sq14-badge.amber{background:var(--amber-soft);color:var(--amber)}.sq14-badge.good{background:var(--good-soft);color:var(--good)}.sq14-badge.bad{background:var(--bad-soft);color:var(--bad)}
.sq14-bars{display:grid;gap:10px;margin-bottom:8px}
.sq14-bar{display:grid;grid-template-columns:minmax(0,200px) minmax(0,1fr) 80px;gap:12px;align-items:center}
.sq14-bl b{display:block;font-size:.82rem}.sq14-bl small{font-size:.7rem;color:var(--muted);line-height:1.3;display:block}
