.sq14-bv{font:700 .82rem "JetBrains Mono",monospace;text-align:right}
.sq14-note{font-size:.8rem;color:var(--muted)}
.sq14-beam{position:relative;height:110px;margin:4px 0 16px}
.sq14-pivot{position:absolute;left:50%;bottom:0;width:0;height:0;margin-left:-14px;border-left:14px solid transparent;border-right:14px solid transparent;border-bottom:30px solid var(--accent)}
