@media(prefers-reduced-motion:reduce){.sq14-node,.sq14-arrow,.sq14-calls div,.sq14-card,.sq14-mt tr.new td{animation:none;opacity:1}.sq14-plank,.sq14-bt i,.sq14-tile,.sq14-ln,.sq14-ps,.sq14-op{transition:none}}
