/* v2: trigger timeline */
.sq14-tl{border:1px solid var(--line);border-radius:12px;background:var(--surface);overflow:hidden;margin-top:8px}
.sq14-tlh,.sq14-tr{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.3fr) minmax(0,.8fr) minmax(0,1.3fr);gap:6px;padding:4px 8px}
.sq14-tlh{background:var(--soft);border-bottom:1px solid var(--line)}
.sq14-tlh span{font:700 .64rem Inter,sans-serif;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}
.sq14-tlb{padding:4px 0}
.sq14-tr{border-left:3px solid transparent}
.sq14-tr.cur{border-left-color:var(--accent);background:var(--accent-soft)}
.sq14-tc{min-width:0;border:1px solid var(--line);border-radius:8px;padding:5px 8px;font-size:.74rem;background:var(--surface);display:flex;flex-wrap:wrap;gap:4px 8px;align-items:baseline}
.sq14-tc b{font:700 .72rem "JetBrains Mono",monospace;flex-basis:100%}
.sq14-tc.st{grid-column:1/-1;background:var(--soft);font:600 .74rem Inter,sans-serif;color:var(--muted)}
.sq14-tc.rw{border:0;background:none;color:var(--muted);font:600 .7rem Inter,sans-serif;padding-left:0}
.sq14-tc.bf{border-color:var(--amber);background:var(--amber-soft)}
.sq14-tc.af{border-color:var(--good);background:var(--good-soft)}
.sq14-tc.wr{border-color:var(--accent);background:var(--accent-soft);justify-content:center}
.sq14-tc.wr b{flex-basis:auto}
.sq14-tc.sk{border-color:var(--bad);background:var(--bad-soft)}
.sq14-tc span{font:500 .7rem "JetBrains Mono",monospace;white-space:nowrap}
.sq14-tc small{display:block;font:600 .58rem Inter,sans-serif;color:var(--muted);white-space:normal}
.sq14-stl{margin-top:10px;border:1px dashed var(--line);border-radius:12px;padding:8px 10px}
.sq14-stb{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.sq14-sp{font:600 .72rem Inter,sans-serif;padding:4px 10px;border-radius:99px;border:1px solid var(--line);color:var(--muted)}
.sq14-sp.on{border-color:var(--accent);background:var(--accent-soft);color:var(--text)}
.sq14-sp.mid{border:0;padding:4px 2px;flex:1 1 200px}
.sq14-tsql{margin-top:8px}.sq14-tsql summary{cursor:pointer;font-size:.8rem;color:var(--muted)}
.sq14-tsql pre{font-size:.72rem;white-space:pre-wrap;overflow-wrap:anywhere}
/* v2: cursor vs set-based */
.sq14-cu{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;margin-top:8px}
.sq14-cs{min-width:0;border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:10px}
.sq14-cs[data-s="cur"]{border-top:3px solid var(--amber)}
.sq14-cs[data-s="set"]{border-top:3px solid var(--good)}
.sq14-cs pre.sq-q{margin:0 0 8px;font-size:.7rem;white-space:pre-wrap;overflow-wrap:anywhere}
.sq14-ct{overflow-x:auto}
.sq14-mt tr.cur td{background:var(--amber-soft);font-weight:700}
.sq14-mt tr.dn td{background:var(--good-soft)}
.sq14-cc2{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.sq14-k{display:inline-flex;gap:6px;align-items:baseline;padding:3px 10px;border-radius:99px;border:1px solid var(--line);background:var(--soft);font-size:.74rem}
.sq14-k em{font-style:normal;color:var(--muted)}
.sq14-k b{font:700 .8rem "JetBrains Mono",monospace}
.sq14-k.ok{border-color:var(--good);background:var(--good-soft)}
.sq14-cn2{margin-top:8px}
/* v2: procedure control-flow chart */
.sq14-pside{display:grid;gap:10px;min-width:0}
.sq14-pfc{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:10px;min-width:0}
.sq14-fsv{display:block;width:100%;height:auto}
.sq14-fn rect{fill:var(--soft);stroke:var(--line);stroke-width:1.3}
.sq14-fn text{font:600 13px Inter,sans-serif;fill:var(--muted);text-anchor:middle}
.sq14-fn.dia rect{stroke-dasharray:4 3}
.sq14-fn.ok rect{fill:var(--good-soft);stroke:var(--good)}.sq14-fn.ok text{fill:var(--text)}
.sq14-fn.bad rect{fill:var(--bad-soft);stroke:var(--bad)}.sq14-fn.bad text{fill:var(--text)}
.sq14-fn.cur rect{stroke-width:2.6}
