.sq14-fe.err.on{stroke:var(--bad);stroke-dasharray:none}
.sq14-fl{font:600 11px Inter,sans-serif;fill:var(--muted)}
@media(max-width:640px){
  .sq14-cu{grid-template-columns:minmax(0,1fr)}
  .sq14-tlh,.sq14-tr{grid-template-columns:minmax(0,.5fr) minmax(0,1.3fr) minmax(0,.7fr) minmax(0,1.3fr);gap:4px;padding:3px 4px}
