  .sq14-tc span{white-space:normal}
}
.sq14 .sq14-pg{grid-template-columns:minmax(0,1.45fr) minmax(0,1fr)}
@media(max-width:640px){.sq14 .sq14-pg{grid-template-columns:minmax(0,1fr)}}

/* sql challenge v2 (2026-10-30): graded challenges .sq-ch (labs-sql.js), used by every SQL lesson. v2: stars, 80% bar in .sq-chsum, timed interview mode (body.sq-iv), Visualize button area, DML "effect" grid on Run, inline reset of the lesson DB, home card challenge meter (.sq-chc) */
.sq-ch{margin:18px 0;padding:14px 16px;border:1px solid var(--line);border-radius:16px;background:var(--surface);box-shadow:var(--shadow)}
.sq-ch.solved{border-color:var(--good)}
.sq-ch-h{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:6px}
.sq-ch-h b{font:700 .95rem "Inter Tight",Inter,sans-serif}
.sq-ch-lv{font:700 .64rem Inter,sans-serif;letter-spacing:.07em;text-transform:uppercase;padding:3px 9px;border-radius:99px;color:#fff;background:var(--good-fill)}
.sq-ch-lv.lv-I{background:var(--accent-fill)}.sq-ch-lv.lv-A{background:var(--amber-fill)}.sq-ch-lv.lv-E{background:var(--bad-fill)}
.sq-ch-ok{margin-left:auto;font:700 .78rem Inter,sans-serif;color:var(--good);white-space:nowrap}
.sq-ch-st{color:var(--amber);letter-spacing:.06em;margin-left:4px}
.sq-st0{font-style:normal;opacity:.28;filter:grayscale(1)}
.sq-vh-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.sq-ch-tm{font:700 .78rem "JetBrains Mono",monospace;font-variant-numeric:tabular-nums;color:var(--muted)}
.sq-ch-tm:empty{display:none}
.sq-ch-tm.warn{color:var(--amber)}.sq-ch-tm.late{color:var(--bad)}.sq-ch-tm.ok{color:var(--good)}
.sq-ch-task{font-size:.92rem}
.sq-ch-task p{margin:4px 0}
.sq-ch .sq-ed{margin:10px 0 0}
.sq-ch-ctl{margin-top:10px;flex-wrap:wrap}
.sq-ch-ctl [data-k="viz"][aria-pressed="true"]{border-color:var(--accent);color:var(--accent)}
.sq-ch-hints p{margin:8px 0 0;padding:8px 12px;border-radius:10px;background:var(--amber-soft);border-left:3px solid var(--amber);font-size:.88rem}
.sq-ch-res h5,.sq-out h5.sq-vh{margin:12px 0 0;font:700 .72rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.sq-out h5.sq-vh code{text-transform:none;letter-spacing:0;font-weight:500}
.sq-ch-pass,.sq-ch-fail{margin-top:10px;padding:9px 12px;border-radius:10px;font-weight:600;font-size:.9rem}
.sq-ch-pass{background:var(--good-soft);border-left:3px solid var(--good);color:var(--good)}
.sq-ch-fail{background:var(--bad-soft);border-left:3px solid var(--bad);color:var(--bad)}
.sq-ch-sol{margin-top:10px}.sq-ch-sol>b{display:block;font:700 .72rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin-bottom:6px}
.sq-ch-viz:empty{display:none}
.sq-ch-viz.sqv{margin:12px 0 0}
.sq-chsum{margin:14px 0;padding:12px 14px;border-radius:12px;background:var(--accent-soft);color:var(--text);font-size:.9rem}
.sq-chs-top{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px}
.sq-chs-st{font-weight:700;color:var(--amber)}
.sq-chs-top .btn{margin-left:auto;padding:5px 12px;font-size:.8rem}
.sq-chbar{position:relative;display:block;height:8px;border-radius:99px;background:color-mix(in srgb,var(--line) 70%,transparent);margin:10px 0 6px;overflow:visible}
.sq-chbar i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--good),color-mix(in srgb,var(--good) 55%,var(--accent)));transition:width .5s}
.sq-chbar u{position:absolute;top:-3px;bottom:-3px;width:2px;border-radius:2px;background:var(--text);opacity:.55}
.sq-chs-note{font-size:.8rem;color:var(--muted)}
.sq-ivbar{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px;margin-top:10px;padding:8px 10px;border-radius:10px;background:var(--surface);border:1px solid var(--line);font-size:.84rem}
.sq-ivbar span{color:var(--muted);font-variant-numeric:tabular-nums}
.sq-ivbar .btn{margin-left:auto;padding:5px 12px;font-size:.8rem}
.sq-ivres{margin-top:8px;padding:10px 12px;border-radius:10px;background:var(--surface);border:1px solid var(--good)}
.sq-ivres ol{margin:6px 0 0;padding-left:20px;font-size:.84rem}.sq-ivres em{font-style:normal;color:var(--muted);font-size:.76rem}
body.sq-iv .sq-ch [data-k="hint"],body.sq-iv .sq-ch [data-k="sol"],body.sq-iv .sq-ch [data-k="viz"],body.sq-iv .sq-ch-hints,body.sq-iv .sq-ch-sol,body.sq-iv .sq-ch-viz,body.sq-iv .sq-ch .count{display:none!important}
.sq-out .sq-vnote{padding:6px 2px;font:500 .8rem Inter,sans-serif;color:var(--muted)}
.sq-resetin{margin-top:8px;display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:8px 12px;border-radius:10px;background:var(--amber-soft);border-left:3px solid var(--amber);font-size:.85rem}
.sq-resetin .btn{padding:5px 12px;font-size:.8rem}
