.nx-tabs button{font:600 .72rem Inter,sans-serif;color:var(--code-dim);background:none;border:1px solid transparent;border-radius:8px;padding:4px 10px;cursor:pointer}
.nx-tabs button.on{color:var(--code-text);border-color:var(--code-line);background:var(--code-hl)}
.nx-pre{margin:0;padding:12px 14px;max-height:240px;overflow:auto;font:.78rem/1.55 "JetBrains Mono",monospace;color:var(--code-text);white-space:pre-wrap;word-break:break-word}
.nx-jk{color:#7dd3fc}.nx-js{color:#86efac}.nx-jv{color:#fbbf24}.nx-jn{color:#f472b6}.nx-dim{color:var(--code-dim);font-family:Inter,sans-serif}
.nx-cv.hl-workflow{box-shadow:inset 0 0 0 3px var(--accent)}
.nx-cv.hl-trigger .k-trig .nx-box,.nx-cv.hl-node .nx-box{box-shadow:0 0 0 5px color-mix(in srgb,var(--accent) 40%,transparent)}
.nx-cv.hl-conn path{stroke:var(--accent);stroke-width:4}
.nx0-words{display:flex;flex-wrap:wrap;gap:8px;padding:14px 16px 0}
.nx0-words button,.nx0-pick button{font:600 .8rem Inter,sans-serif;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:6px 12px;cursor:pointer}
.nx0-words button.on{background:var(--accent);border-color:var(--accent);color:#fff}
.nx0-cap{margin:10px 16px 12px;font-size:.92rem;min-height:2.8em}
.nx0-sort{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px;padding:16px}
.nx0-card{border:1px solid var(--line);border-radius:12px;padding:12px;background:var(--surface)}
.nx0-card>b{display:block;font-size:.9rem;margin-bottom:8px}
.nx0-pick{display:flex;flex-wrap:wrap;gap:6px}
.nx0-pick button{font-size:.72rem;padding:4px 9px}
.nx0-card p{margin:8px 0 0;min-height:0}
.nx0-card.ok{border-color:var(--good);background:var(--good-soft)}
.nx0-card.ok .nx0-pick{display:none}
.nx0-card.miss:not(.ok){border-color:var(--bad)}
.nx0-score{padding:0 16px 14px;margin:0}
.nx0-ctl{padding:14px 16px 10px;font-size:.9rem}
.nx0-ctl input{vertical-align:middle;width:min(220px,60vw)}
.nx0-roi{display:grid;gap:16px;padding:16px;grid-template-columns:minmax(0,1fr)}
@media (min-width:761px){.nx0-roi{grid-template-columns:minmax(0,280px) minmax(0,1fr)}}
.nx0-in{display:grid;gap:10px}
.nx0-in label{display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:.86rem}
.nx0-in input{width:96px;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text);font:inherit}
.nx0-bars div{display:grid;grid-template-columns:76px minmax(0,1fr);align-items:center;gap:4px 10px;margin-bottom:10px;font-size:.84rem}
.nx0-bars i{display:block;height:14px;border-radius:7px;background:linear-gradient(90deg,var(--bad),var(--amber));transition:width .4s}
.nx0-bars i.g{background:var(--good)}
.nx0-bars b{grid-column:2;font-size:.8rem;font-weight:600}
.nx0-kpi{display:flex;flex-wrap:wrap;gap:10px}
.nx0-kpi div{flex:1 1 140px;border:1px solid var(--line);border-radius:12px;padding:10px 14px;background:var(--good-soft)}
.nx0-kpi small{display:block;color:var(--muted);font-size:.74rem}
.nx0-kpi b{font:700 1.25rem "Inter Tight",Inter,sans-serif;color:var(--good)}
.nx0-where{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));margin:18px 0}
.nx0-where>div{border:1px solid var(--line);border-radius:14px;padding:14px 16px;background:var(--surface);box-shadow:var(--shadow)}
.nx0-where b{display:block;font:700 1rem "Inter Tight",Inter,sans-serif;margin-bottom:4px}
.nx0-where p{margin:6px 0 0;font-size:.88rem}
@media (max-width:560px){.nx-node{width:92px}.nx-box{width:46px;height:46px}.nx-node{transform:translate(-50%,-23px)}.nx-lb small{display:none}.nx-ic{font-size:1.2rem}}
@media (prefers-reduced-motion:reduce){.nx-node.run .nx-box{animation:none}.nx-wires path,.nx0-bars i,.nx-wl{transition:none}}
.nx-snip{background:var(--code-bg);border:1px solid var(--line);border-radius:12px;margin:14px 0}
.nx-bar .nx-go{background:linear-gradient(135deg,#ea4b71,#8b5cf6);color:#fff;border-color:transparent;font-weight:600}
/* n8n N01 labs v1 (#nxJson #nxPath #nxShape #nxViews #nxPin) */
.nx1-pre{display:flex;flex-wrap:wrap;gap:8px;padding:14px 16px 0}
.nx1-pre button{font:600 .78rem Inter,sans-serif;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:6px 12px;cursor:pointer}
.nx1-pre button.on{background:var(--accent);border-color:var(--accent);color:#fff}
.nx1-ed{display:grid;gap:12px;padding:14px 16px 16px;grid-template-columns:minmax(0,1fr)}
@media (min-width:761px){.nx1-ed{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}}
.nx1-ed textarea{min-height:190px;resize:vertical;font:.8rem/1.55 "JetBrains Mono",monospace;color:var(--code-text);background:var(--code-bg);border:1px solid var(--code-line);border-radius:12px;padding:12px 14px}
.nx1-res{border:1px solid var(--line);border-radius:12px;padding:12px 14px;font-size:.88rem;overflow:auto}
.nx1-res.good{border-color:var(--good);background:var(--good-soft)}
.nx1-res.bad{border-color:var(--bad);background:var(--bad-soft)}
.nx1-res small{display:block;margin-top:8px;font:.72rem "JetBrains Mono",monospace;color:var(--muted)}
.nx1-tree{font:.8rem/1.7 "JetBrains Mono",monospace;margin-top:8px}
.nx1-card{margin:0 16px;padding:12px 14px;border-radius:12px;background:var(--code-bg);color:var(--code-text);overflow-x:auto}
.nx1-o{padding-left:18px}
.nx1-v{font:inherit;background:none;border:1px dashed transparent;border-radius:6px;padding:0 3px;cursor:pointer}
.nx1-card .nx1-v{border-color:color-mix(in srgb,var(--code-dim) 45%,transparent)}
.nx1-v.on{background:color-mix(in srgb,var(--good) 30%,transparent);border-color:var(--good)}
.nx1-v.no{background:color-mix(in srgb,var(--bad) 25%,transparent);border-color:var(--bad)}
.nx1-b{font:600 .62rem Inter,sans-serif;font-style:normal;border-radius:999px;padding:1px 7px;color:#fff;background:#64748b;vertical-align:1px}
.nx1-b.t-string{background:#16a34a}.nx1-b.t-number{background:#d97706}.nx1-b.t-boolean{background:#7c3aed}.nx1-b.t-null{background:#db2777}.nx1-b.t-array{background:#0284c7}.nx1-b.t-object{background:#475569}
.nx1-goal{margin:14px 16px 10px;font-size:.92rem;font-weight:600}
.nx1-said{margin:10px 16px 14px;min-height:1.5em}
.nx1-views{margin-top:14px}
.nx1-vw{background:var(--surface);color:var(--text)}
.nx1-vw .tw{margin:0}
.nx1-tb{font-size:.82rem}
.nx1-vw .nx-pre{background:var(--code-bg)}
.nx1-sc{list-style:none;margin:0;padding:12px 14px;display:grid;gap:8px;font-size:.86rem}
.nx1-pinbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between}
.nx1-pinned .nx-box::after{content:"📌";position:absolute;right:-10px;top:-10px;font-size:.9rem}
.nx-snip.nx1-nw{white-space:pre;overflow-x:auto;word-break:normal}
/* n8n N02 labs v1 (#nxExpr #nxMap #nxLink #nxDate) */
.nx2-param{margin:12px 16px 16px;border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:var(--surface)}
.nx2-lbl{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px;font-size:.86rem}
.nx2-mode{display:inline-flex;border:1px solid var(--line);border-radius:999px;overflow:hidden}
.nx2-mode button{font:600 .72rem Inter,sans-serif;background:none;border:0;padding:4px 12px;color:var(--muted);cursor:pointer}
.nx2-mode button.on{background:var(--accent);color:#fff}
.nx2-param input,.nx2-node input{width:100%;box-sizing:border-box;font:.82rem "JetBrains Mono",monospace;color:var(--code-text);background:var(--code-bg);border:1px solid var(--code-line);border-radius:8px;padding:8px 10px}
.nx2-hl{font:.74rem "JetBrains Mono",monospace;color:var(--muted);margin:6px 0 0;word-break:break-word;min-height:1em}
.nx2-br{color:var(--good);background:var(--good-soft);border-radius:4px;padding:0 2px}
.nx2-fixed .nx2-param input{border-color:var(--amber)}
.nx2-res{list-style:none;margin:10px 0 0;padding:0;display:grid;gap:6px}
.nx2-res li{display:flex;flex-wrap:wrap;gap:4px 10px;align-items:baseline;border-left:3px solid var(--good);padding:4px 10px;background:var(--soft);border-radius:0 8px 8px 0;font-size:.88rem}
.nx2-res small{color:var(--muted);font-size:.72rem;min-width:88px}
.nx2-fixed .nx2-res li{border-left-color:var(--amber)}
.nx2-err{color:var(--bad);font:600 .78rem "JetBrains Mono",monospace}
.nx2-warn{color:var(--amber);font-size:.74rem}
.nx2-map{display:grid;gap:14px;padding:14px 16px 16px;grid-template-columns:minmax(0,1fr)}
@media (min-width:761px){.nx2-map{grid-template-columns:minmax(0,260px) minmax(0,1fr)}}
.nx2-schema,.nx2-node{display:grid;gap:8px;align-content:start;border:1px solid var(--line);border-radius:12px;padding:12px;background:var(--surface)}
.nx2-schema small,.nx2-node small{font:600 .68rem Inter,sans-serif;letter-spacing:.06em;color:var(--muted)}
.nx2-schema button{text-align:left;font:.78rem "JetBrains Mono",monospace;color:var(--text);background:var(--soft);border:1px dashed var(--line);border-radius:8px;padding:6px 8px;cursor:grab;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.nx2-schema button:hover{border-color:var(--accent)}
.nx2-node label{display:grid;gap:4px;font-size:.8rem;font-weight:600}
.nx2-node input.ex{border-color:var(--good)}
.nx2-prev{display:grid;gap:6px;font-size:.86rem}
.nx2-prev div{display:grid;gap:2px;padding:6px 10px;border-radius:8px;background:var(--soft)}
.nx2-prev small{letter-spacing:0;font-weight:500}
.nx2-ok{margin:4px 0 0;color:var(--good);font-weight:600}
.nx2-pick button,.nx2-dates button{border-radius:10px}
.nx2-pick code,.nx2-dates code{background:none;font-size:.74rem}
.nx2-why{margin:8px 16px 4px;min-height:1.4em}
.nx2-dates{display:flex;flex-wrap:wrap;gap:8px;padding:14px 16px 0}
.nx2-dates button{font:600 .76rem Inter,sans-serif;color:var(--text);background:var(--surface);border:1px solid var(--line);padding:6px 10px;cursor:pointer;text-align:left}
.nx2-dates button.on{border-color:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 25%,transparent)}
.nx2-dres{margin:12px 16px 0;padding:12px 14px;border-radius:12px;background:var(--code-bg);color:var(--code-text)}
.nx2-dres small{color:var(--code-dim);font-size:.7rem;letter-spacing:.06em;text-transform:uppercase}
.nx2-dres b{display:block;font:600 1.05rem "JetBrains Mono",monospace;color:#86efac;margin:2px 0 6px;word-break:break-all}
.nx2-dres p{margin:0;font-size:.86rem;color:var(--code-text)}
.nx2-line{position:relative;height:44px;margin:14px 16px 16px;border-bottom:2px solid var(--line)}
.nx2-line i{position:absolute;bottom:6px;transform:translateX(-50%);font:600 .7rem Inter,sans-serif;font-style:normal;color:var(--muted);white-space:nowrap}
.nx2-line i::after{content:"";position:absolute;left:50%;top:100%;width:2px;height:10px;background:currentColor}
.nx2-line .nx2-slot{color:#3b82f6}.nx2-line .nx2-now{color:var(--accent)}
.nx2-line b{position:absolute;left:20%;bottom:-3px;height:4px;width:0;border-radius:2px;background:var(--good)}
/* n8n N03 labs v1 (#nxCron #nxHook #nxRespond #nxPoll, form mock) */
.nx3-pre code,.nx3-send code{background:none;font-size:.74rem}
.nx3-cron{display:grid;gap:12px;padding:14px 16px 16px}
.nx3-cron input{font:600 1rem "JetBrains Mono",monospace;color:var(--code-text);background:var(--code-bg);border:1px solid var(--code-line);border-radius:10px;padding:10px 12px;width:100%;box-sizing:border-box}
.nx3-fields{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}
.nx3-fields div{display:grid;justify-items:center;gap:2px;padding:6px 4px;border:1px solid var(--line);border-radius:8px;background:var(--surface);text-align:center}
.nx3-fields b{font:600 .86rem "JetBrains Mono",monospace;word-break:break-all}
.nx3-fields small{font-size:.64rem;color:var(--muted);line-height:1.2}
.nx3-out{font-size:.86rem;line-height:1.6;padding:10px 12px;border-radius:10px;background:var(--soft)}
.nx3-out.bad{background:var(--bad-soft);border:1px solid var(--bad)}
.nx3-n{font:700 1rem "Inter Tight",Inter,sans-serif;color:var(--accent)}
.nx3-week{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}
.nx3-week>div{display:grid;justify-items:center;gap:4px}
.nx3-week small{font-size:.68rem;color:var(--muted)}
.nx3-week p{grid-column:1/-1;margin:2px 0 0}
.nx3-col{position:relative;width:100%;height:120px;border-radius:8px;background:var(--soft);border:1px solid var(--line);overflow:hidden}
.nx3-col i{position:absolute;left:20%;right:20%;height:2px;border-radius:1px;background:var(--accent)}
.nx3-col em{position:absolute;left:0;right:0;height:0;border-top:2px dashed var(--amber)}
.nx3-hk{display:grid;gap:12px;padding:14px 16px 16px}
.nx3-sw,.nx3-send{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.nx3-listen.on{background:var(--amber);color:#111;border-color:var(--amber)}
.nx3-tg{display:inline-flex;gap:6px;align-items:center;font-size:.86rem;font-weight:600}
.nx3-path{position:relative;display:flex;justify-content:space-between;align-items:center;padding:8px 12px;border-radius:10px;background:var(--soft);font-size:.84rem;font-weight:600}
.nx3-path::before{content:"";position:absolute;left:96px;right:52px;top:50%;border-top:2px dashed var(--line)}
.nx3-dot{position:absolute;left:100%;top:50%;width:12px;height:12px;margin:-6px 0 0 -6px;border-radius:50%;background:var(--muted);opacity:0}
.nx3-dot.ok{background:var(--good);opacity:1}.nx3-dot.no{background:var(--bad);opacity:1}
.nx3-pan{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.nx3-pan div{border:1px solid var(--line);border-radius:10px;padding:8px 12px;background:var(--surface)}
.nx3-pan small{display:block;color:var(--muted);font-size:.72rem}
.nx3-pan b{font:700 1.3rem "Inter Tight",Inter,sans-serif}
.nx3-log{list-style:none;margin:0;padding:0;display:grid;gap:6px;max-height:220px;overflow:auto}
.nx3-log li{font-size:.84rem;padding:6px 10px;border-radius:8px;border-left:3px solid var(--good);background:var(--good-soft)}
.nx3-log li.no{border-left-color:var(--bad);background:var(--bad-soft)}
.nx3-tl{position:relative;margin:14px 16px 0;padding-bottom:4px}
.nx3-lane,.nx3-row{display:grid;grid-template-columns:62px minmax(0,1fr);align-items:center;gap:8px;margin-bottom:8px;font-size:.78rem;font-weight:600}
.nx3-track{position:relative;height:30px;border-radius:8px;background:var(--soft);border:1px solid var(--line)}
.nx3-seg{position:absolute;top:3px;bottom:3px;border-radius:6px;font:600 .62rem Inter,sans-serif;font-style:normal;color:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden;white-space:nowrap}
.nx3-seg.s0{background:#f97316}.nx3-seg.s1{background:#22c55e}.nx3-seg.s2{background:#8b5cf6}.nx3-seg.s3{background:#3b82f6}
.nx3-caller>*{opacity:0;transition:opacity .3s}.nx3-caller.show>*{opacity:1}
.nx3-wait{position:absolute;left:0;top:10px;height:8px;border-radius:4px;background:repeating-linear-gradient(90deg,var(--amber) 0 6px,transparent 6px 10px)}
.nx3-wait.late{background:repeating-linear-gradient(90deg,var(--bad) 0 6px,transparent 6px 10px)}
.nx3-ans{position:absolute;top:50%;transform:translate(-50%,-50%);font:700 .64rem "JetBrains Mono",monospace;font-style:normal;color:#fff;background:var(--good);border-radius:999px;padding:2px 7px;white-space:nowrap}
.nx3-ans.x{background:var(--bad)}
.nx3-axis{position:relative;height:16px;margin-left:70px}
.nx3-row .nx3-axis{margin-left:0}
.nx3-axis span{position:absolute;transform:translateX(-50%);font-size:.62rem;color:var(--muted)}
.nx3-ov{position:absolute;left:70px;right:0;top:0;bottom:16px;pointer-events:none}
.nx3-cur{position:absolute;top:0;bottom:0;left:0;width:2px;background:var(--accent)}
.nx3-lim{position:absolute;top:0;bottom:0;width:0;border-left:2px dashed var(--bad)}
.nx3-pl{padding:4px 16px 0}
.nx3-m,.nx3-x,.nx3-c{position:absolute;top:50%;transform:translate(-50%,-50%);font-style:normal;font-size:.72rem;line-height:1}
.nx3-x{width:18px;height:18px;border-radius:50%;background:var(--good);color:#fff;display:grid;place-items:center;font:700 .62rem Inter,sans-serif}
.nx3-c{width:3px;height:22px;border-radius:2px;background:var(--line);color:transparent}
.nx3-c.on{width:20px;height:20px;border-radius:6px;background:var(--accent);color:#fff;display:grid;place-items:center;font:700 .66rem Inter,sans-serif}
.nx3-st{margin:8px 16px 14px}
.nx3-form{max-width:420px;margin:16px auto;border:1px solid var(--line);border-radius:16px;padding:16px;background:var(--surface);box-shadow:var(--shadow);display:grid;gap:10px}
.nx3-fh b{display:block;font:700 1.05rem "Inter Tight",Inter,sans-serif}.nx3-fh small{color:var(--muted)}
.nx3-form label{display:grid;gap:4px;font-size:.78rem;font-weight:600}
.nx3-form label span{font-weight:400;font-size:.86rem;border:1px solid var(--line);border-radius:8px;padding:7px 10px;background:var(--soft)}
.nx3-form>i{justify-self:start;font-style:normal;font-weight:600;color:#fff;background:linear-gradient(135deg,#ea4b71,#8b5cf6);border-radius:8px;padding:7px 18px}
.nx3-form pre{border-radius:10px;font-size:.7rem}
/* n8n N04 labs v1 (#nxReq #nxAuth #nxPage #nxRate, cURL map) */
.nx4-m{color:#f472b6}.nx4-u{color:#7dd3fc}.nx4-h{color:#fbbf24}.nx4-b{color:#86efac}
.nx4-map{display:grid;gap:8px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin:12px 0}
.nx4-map div{border:1px solid var(--line);border-radius:10px;padding:8px 12px;background:var(--surface);font-size:.86rem}
.nx4-map span{font:600 .8rem "JetBrains Mono",monospace;background:var(--code-bg);border-radius:6px;padding:1px 6px}
.nx4-form{display:grid;gap:10px;padding:14px 16px 0}
.nx4-line{display:flex;flex-wrap:wrap;align-items:center;gap:6px;border:1px solid var(--code-line);border-radius:10px;background:var(--code-bg);padding:6px}
.nx4-line select{font:700 .8rem "JetBrains Mono",monospace;color:#f472b6;background:var(--code-hl);border:0;border-radius:6px;padding:6px}
