.nx4-form textarea{min-height:60px;font:.8rem "JetBrains Mono",monospace;color:var(--code-text);background:var(--code-bg);border:1px solid var(--code-line);border-radius:10px;padding:8px 10px;resize:vertical}
.nx4-form .nx-bar{padding:0}
.nx4-res{margin:12px 16px 16px;border:1px solid var(--line);border-radius:12px;overflow:hidden}
.nx4-st{display:flex;gap:12px;align-items:center;padding:10px 14px;font-size:.88rem}
.nx4-st b{font:800 1.3rem "Inter Tight",Inter,sans-serif;color:#fff;border-radius:8px;padding:2px 10px}
.nx4-st.ok{background:var(--good-soft)}.nx4-st.ok b{background:var(--good)}
.nx4-st.c4{background:var(--bad-soft)}.nx4-st.c4 b{background:var(--bad)}
.nx4-st.c5{background:color-mix(in srgb,var(--amber) 18%,transparent)}.nx4-st.c5 b{background:var(--amber);color:#111}
.nx4-res .nx-pre{border-radius:0}
.nx4-res>p{margin:0;padding:10px 14px}
.nx4-tabs{margin:14px 16px 0;border-radius:10px;border:1px solid var(--code-line)}
.nx4-auth{padding:12px 16px 16px}
.nx4-auth>pre{border-radius:10px;background:var(--code-bg)}
.nx4-actors{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
