@media (prefers-reduced-motion: reduce){.ds21-lv span,.ds21-fwr i,.ds21-str i,.ds21-n circle,.ds21-hist i{transition:none}}

/* DSA Lab R3 (kb/java/playground.md → "DSA redesign R3"): "just ran" bar, Why here, History tab, array-backed stack, [ data | next ] nodes,
   compared cells, tree comparison label, hash → bucket ribbon, scaled/centred picture; colours from the dsa-ds tokens */
.pg-jr{font:700 .6rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.06em;color:var(--ds-mod);background:var(--ds-mod-soft);border-radius:99px;padding:1px 8px;margin-right:8px;vertical-align:1px;white-space:nowrap}
.pg-whyh{margin:7px 0 0;font-size:.8rem;line-height:1.7;color:var(--text)}
.pg-whyh>span:first-child{margin-right:6px;font:700 .6rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.07em;color:var(--ds-cmp);background:var(--ds-cmp-soft);border-radius:99px;padding:2px 8px}
.pg-whyh code{font:.76rem var(--ds-mono);background:var(--soft);border:1px solid var(--line);border-radius:6px;padding:1px 6px;color:var(--text)}
.pg-htabs{display:inline-flex;gap:2px;margin:-3px 0 -3px -6px}
.pg-htab{font:600 .72rem var(--ds-mono);color:var(--code-dim);background:none;border:1px solid transparent;border-radius:7px;padding:2px 8px;cursor:pointer;position:relative}
.pg-htab:hover{color:var(--code-text)}
.pg-htab.on{color:var(--code-text);background:color-mix(in srgb,var(--code-text) 10%,transparent);border-color:var(--code-line)}
.pg-htab:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
.pg-hdot{position:absolute;top:2px;right:1px;width:6px;height:6px;border-radius:50%;background:var(--ds-mod)}
.pg-hist{list-style:none;margin:0;padding:4px 0;overflow:auto;flex:1;min-height:0;font:.72rem/1.4 var(--ds-mono);color:var(--code-text)}
.pg-hist li{margin:0}
.pg-hist li.pg-dim{padding:6px 12px;color:var(--code-dim);font-family:Inter,sans-serif}
.pg-hist button{display:flex;gap:8px;align-items:baseline;width:100%;text-align:left;background:none;border:0;border-left:2px solid transparent;color:inherit;font:inherit;padding:3px 10px;cursor:pointer;opacity:.72}
.pg-hist button:hover{opacity:1;background:color-mix(in srgb,var(--code-text) 6%,transparent)}
.pg-hist li.on button{opacity:1;border-left-color:var(--ds-mod);background:color-mix(in srgb,var(--amber) 12%,transparent)}
.pg-hln{flex:none;min-width:2.6em;color:var(--code-dim)}
.pg-hev{flex:none;font:700 .56rem Inter,sans-serif;text-transform:uppercase;letter-spacing:.05em;border-radius:99px;padding:1px 6px;background:color-mix(in srgb,var(--accent) 22%,transparent);color:var(--code-text)}
.pg-hev.ex{background:color-mix(in srgb,var(--bad) 30%,transparent)}
.pg-hev.end{background:color-mix(in srgb,var(--good) 30%,transparent)}
/* array-backed stack: slot [len-1] on top, used slots solid, free slots faded and dashed, a gliding "← top" marker */
.pg-ast{position:relative;display:flex;flex-direction:column;align-items:flex-start;padding:8px 74px 12px 12px;border:0}
.pg-asi{display:flex;align-items:center;gap:8px;width:auto}
.pg-asi i{font:.6rem var(--ds-mono);color:var(--muted);font-style:normal;min-width:2.4em;text-align:right}
.pg-asi b{display:block;min-width:56px;text-align:center;font:700 .86rem var(--ds-mono);padding:6px 10px;border:var(--ds-bw) solid var(--ds-edge);border-top-width:0;background:var(--ds-act-soft);color:var(--text);transition:opacity var(--ds-move) var(--ds-ease),background var(--ds-fast)}
.pg-asi:first-of-type b{border-top-width:var(--ds-bw);border-radius:0}
.pg-asi:last-of-type b{border-radius:0 0 var(--ds-r) var(--ds-r)}
.pg-asi.free b{background:transparent;border-style:dashed;opacity:.38;font-weight:500}
.pg-asi.pg-chg b{background:var(--ds-mod-soft)}
.pg-astm{position:absolute;left:0;transform:translateY(-50%);font:700 .66rem var(--ds-mono);color:var(--ds-act);white-space:nowrap;transition:top var(--ds-move) var(--ds-ease)}
.pg-astm.none{color:var(--muted);transform:none}
/* a linked-list node: [ prev | data | next ] */
.pg-ln{display:flex;padding:6px 8px 8px}
.pg-lnc{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:44px;padding:3px 8px 5px;border:var(--ds-bw) solid var(--ds-edge);margin-left:calc(-1 * var(--ds-bw));background:var(--bg)}
.pg-lnc:first-child{margin-left:0;border-radius:var(--ds-r) 0 0 var(--ds-r)}
.pg-lnc:last-child{border-radius:0 var(--ds-r) var(--ds-r) 0}
.pg-lnc i{font:.56rem var(--ds-mono);color:var(--muted);font-style:normal}
.pg-lnc b{font:700 .86rem var(--ds-mono);color:var(--text);min-height:1.2em;display:flex;align-items:center}
.pg-lnc.ptr{background:var(--soft);min-width:38px}
.pg-lnc.pg-chg{background:var(--ds-mod-soft)}
.pg-lnull{color:var(--muted);font-weight:500}
.pg-nomem .pg-k-obj:has(.pg-ln) .pg-bh{padding-top:2px;padding-bottom:2px;font-size:.66rem}
/* compared cells, the tree comparison, the hash ribbon */
.pg-cell.pg-cmp{background:var(--ds-cmp-soft);box-shadow:inset 0 0 0 2px var(--ds-cmp);position:relative;z-index:1}
.pg-gtag.cmp{background:var(--ds-cmp-soft);color:var(--ds-cmp);border-color:color-mix(in srgb,var(--ds-cmp) 40%,transparent);text-transform:none;letter-spacing:0}
.pg-tree{overflow:visible}
.pg-tree text.pg-tcmp{font:700 10.5px var(--ds-mono);fill:var(--ds-cmp);text-anchor:start}
.pg-tree text.pg-tcmp.f{fill:var(--muted)}
.pg-hrib{margin:6px 10px 2px;font:.72rem var(--ds-mono);color:var(--text);background:var(--ds-cmp-soft);border:1px solid color-mix(in srgb,var(--ds-cmp) 30%,transparent);border-radius:8px;padding:4px 8px;line-height:1.5}
.pg-hrib code{font:inherit;background:none;padding:0;color:var(--ds-cmp)}
.pg-bkr.on>i{color:var(--ds-cmp);font-weight:700}
.pg-bkc.cur{box-shadow:0 0 0 2px var(--ds-cmp)}
/* scaled picture (Memory off): scale from the top-left, glide when the scale changes */
.pg-nomem .pg-heap{transform-origin:0 0} /* no transition: arrows are measured right after layout */
.pg-col h5 small{opacity:1;color:color-mix(in srgb,var(--muted) 70%,var(--text))}
.pg-watchp .pg-ph>span:last-child{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
@media (max-width:600px){#pgv.pg3 .CodeMirror-scroll{max-height:34vh}}
@media (prefers-reduced-motion:reduce){.pg-astm,.pg-asi b{transition:none}}
/* dsa vary v1: the "Advanced variations" table of D01–D19 (R5). On a phone each row is a card, the column names become labels. */
section[id$="-vary"]>.tw td:first-child{font-weight:600}
section[id$="-vary"]>.tw td:last-child{white-space:nowrap;color:var(--text)}
@media (max-width:600px){
  section[id$="-vary"]>.tw{overflow:visible}
  section[id$="-vary"]>.tw table{min-width:0}
  section[id$="-vary"]>.tw thead{display:none}
  section[id$="-vary"]>.tw :is(tbody,tr,td){display:block}
  section[id$="-vary"]>.tw tr{padding:12px 14px;border-bottom:1px solid var(--line)}
  section[id$="-vary"]>.tw tr:last-child{border-bottom:0}
  section[id$="-vary"]>.tw td{padding:3px 0;border:0;min-width:0}
  section[id$="-vary"]>.tw td:last-child{white-space:normal}
  section[id$="-vary"]>.tw td:not(:first-child)::before{display:block;font-size:.68rem;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin-top:6px}
  section[id$="-vary"]>.tw td:nth-child(2)::before{content:"The twist"}
  section[id$="-vary"]>.tw td:nth-child(3)::before{content:"What changes"}
  section[id$="-vary"]>.tw td:nth-child(4)::before{content:"Cost"}
}
/* dsa-ds v1:the DSA design system (kb/site/site-internals.md → "DSA design system"). One meaning per colour, everywhere (DSA Lab and the
   D00–D21 labs): act = the element being worked on, cmp = being compared, mod = just changed, del = being removed, ok = finished/sorted,
   dim = out of play, new = just created. Tokens derive from the theme, so every theme gets them. Markup comes from DSX (pg-viz.js). */
:root{
  --ds-act:var(--accent);--ds-act-soft:var(--accent-soft);
  --ds-cmp:color-mix(in srgb,#3b82f6 78%,var(--text));--ds-cmp-soft:color-mix(in srgb,#3b82f6 14%,var(--surface));
  --ds-mod:var(--amber);--ds-mod-soft:var(--amber-soft);
  --ds-del:var(--bad);--ds-del-soft:var(--bad-soft);
  --ds-ok:var(--good);--ds-ok-soft:var(--good-soft);
  --ds-ref:color-mix(in srgb,var(--muted) 80%,var(--text));--ds-edge:color-mix(in srgb,var(--line) 70%,var(--muted));
  --ds-cell:46px;--ds-bw:1.5px;--ds-r:10px;--ds-gap:10px;
  --ds-fast:160ms;--ds-move:320ms;--ds-emph:480ms;--ds-ease:cubic-bezier(.2,.7,.2,1);
  --ds-mono:"JetBrains Mono",ui-monospace,Consolas,monospace;
}
.dsx{display:flex;flex-wrap:wrap;align-items:flex-end;gap:18px 28px;padding:14px 4px 6px;position:relative}
.dsx-ghost{z-index:3}
.dsx-cap{font:500 .78rem/1.4 Inter,system-ui,sans-serif;color:var(--muted)}
.dsx-lbl{font:600 .66rem/1.2 var(--ds-mono);letter-spacing:.04em;text-transform:uppercase;color:var(--muted)}
/* shared states (only on dsx parts) */
.dsx-c,.dsx-n,.dsx-pi{transition:background var(--ds-fast),border-color var(--ds-fast),opacity var(--ds-fast),box-shadow var(--ds-fast)}
:is(.dsx-c,.dsx-n,.dsx-pi).is-act{border-color:var(--ds-act);background:var(--ds-act-soft);z-index:1}
:is(.dsx-c,.dsx-n,.dsx-pi).is-cmp{border-color:var(--ds-cmp);background:var(--ds-cmp-soft);z-index:1}
:is(.dsx-c,.dsx-n,.dsx-pi).is-mod{border-color:var(--ds-mod);background:var(--ds-mod-soft);z-index:1}
:is(.dsx-c,.dsx-n,.dsx-pi).is-del{border-color:var(--ds-del);border-style:dashed;background:var(--ds-del-soft);opacity:.75}
:is(.dsx-c,.dsx-n,.dsx-pi).is-del b{text-decoration:line-through}
:is(.dsx-c,.dsx-n,.dsx-pi).is-ok{border-color:var(--ds-ok);background:var(--ds-ok-soft)}
:is(.dsx-c,.dsx-n,.dsx-pi).is-dim{opacity:.38}
:is(.dsx-c,.dsx-n,.dsx-pi).is-new{border-color:var(--ds-act);background:var(--ds-act-soft);box-shadow:0 0 0 4px color-mix(in srgb,var(--ds-act) 18%,transparent)}
/* array: contiguous cells, index under, optional address over */
.dsx-arr{display:inline-flex;flex-direction:column;gap:4px}
.dsx-row{display:inline-flex;align-items:stretch}
.dsx-c{position:relative;min-width:var(--ds-cell);height:var(--ds-cell);padding:0 6px;display:grid;place-items:center;border:var(--ds-bw) solid var(--ds-edge);background:var(--surface);margin-left:calc(-1 * var(--ds-bw))}
.dsx-c:first-child{margin-left:0;border-radius:var(--ds-r) 0 0 var(--ds-r)}.dsx-c:last-child{border-radius:0 var(--ds-r) var(--ds-r) 0}.dsx-c:only-child{border-radius:var(--ds-r)}
.dsx-c b{font:700 .9rem var(--ds-mono);color:var(--text)}
.dsx-c.nil b{color:var(--muted);font-weight:500}
.dsx-c>i{position:absolute;top:calc(100% + 4px);left:0;right:0;text-align:center;font:500 .64rem var(--ds-mono);font-style:normal;color:var(--muted)}
.dsx-c>u{position:absolute;bottom:calc(100% + 4px);left:0;right:0;text-align:center;font:500 .58rem var(--ds-mono);text-decoration:none;color:var(--muted);opacity:.8}
.dsx-arr.addr{padding-top:14px}.dsx-arr .dsx-row{margin-bottom:18px}
.dsx-pts{position:relative;height:30px;margin-top:-2px}
.dsx-pt{position:absolute;top:0;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;font:700 .66rem var(--ds-mono);color:var(--ds-act);transition:left var(--ds-move) var(--ds-ease)}
.dsx-pt::before{content:"";border:5px solid transparent;border-bottom-color:currentColor;border-top:0;margin-bottom:2px}
.dsx-pt.cmp{color:var(--ds-cmp)}.dsx-pt.mod{color:var(--ds-mod)}
/* linked list: [prev | data | next] nodes, drawn arrows, explicit null */
.dsx-chain{display:inline-flex;align-items:flex-end;position:relative}
.dsx-chain.circ{padding-bottom:26px}
.dsx-ni{display:flex;flex-direction:column;align-items:center;gap:5px}
.dsx-tgs{display:flex;gap:3px;min-height:18px;align-items:flex-end}
.dsx-tg{font:700 .62rem/1 var(--ds-mono);padding:3px 6px;border-radius:999px;background:var(--ds-act);color:var(--surface)}
.dsx-tg.alt{background:transparent;color:var(--ds-act);box-shadow:inset 0 0 0 1.5px var(--ds-act)}
.dsx-n{display:inline-flex;align-items:stretch;height:44px;border:var(--ds-bw) solid var(--ds-edge);border-radius:var(--ds-r);background:var(--surface);position:relative}
.dsx-n b{min-width:46px;padding:0 12px;display:grid;place-items:center;font:700 .9rem var(--ds-mono);color:var(--text)}
.dsx-np{width:22px;display:grid;place-items:center;border-left:var(--ds-bw) solid var(--ds-edge)}
.dsx-np.p{border-left:0;border-right:var(--ds-bw) solid var(--ds-edge)}
.dsx-np::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--ds-ref)}
.dsx-np.nil::before{content:"⌀";width:auto;height:auto;background:none;font:600 .7rem var(--ds-mono);color:var(--muted)}
.dsx-ar{position:relative;width:34px;height:44px;flex:none;align-self:flex-end;color:var(--ds-ref)}
.dsx-ar::before{content:"";position:absolute;left:0;right:5px;top:21px;border-top:2px solid currentColor}
.dsx-ar::after{content:"";position:absolute;right:0;top:17px;border:5px solid transparent;border-left:7px solid currentColor;border-right:0}
.dsx-ar.dbl::before{top:15px}.dsx-ar.dbl::after{top:11px}
.dsx-ar.dbl>i{position:absolute;left:5px;right:0;top:27px;border-top:2px solid var(--ds-ref)}
.dsx-ar.dbl>i::before{content:"";position:absolute;left:-5px;top:-6px;border:5px solid transparent;border-right:7px solid var(--ds-ref);border-left:0}
.dsx-ar.is-mod{color:var(--ds-mod)}.dsx-ar.is-old{opacity:.45}.dsx-ar.is-old::before{border-top-style:dashed}
.dsx-ar.gap::before,.dsx-ar.gap::after{opacity:0}
.dsx-nil{height:44px;align-self:flex-end;display:grid;place-items:center;padding:0 10px;border:var(--ds-bw) dashed var(--ds-edge);border-radius:var(--ds-r);font:600 .74rem var(--ds-mono);color:var(--muted)}
.dsx-back{position:absolute;bottom:4px;height:22px;border:2px solid var(--ds-ref);border-top:0;border-radius:0 0 12px 12px}
.dsx-back::before{content:"";position:absolute;left:-7px;top:-8px;border:6px solid transparent;border-bottom:8px solid var(--ds-ref);border-top:0}
/* stack: an open-topped container, top item highlighted, bottom first in the markup */
.dsx-stk{display:inline-flex;align-items:flex-end;gap:10px}
.dsx-pile{display:flex;flex-direction:column-reverse;gap:5px;min-width:132px;min-height:60px;padding:6px;border:2px solid var(--ds-edge);border-top:0;border-radius:0 0 14px 14px}
.dsx-pi{position:relative;height:36px;padding:0 12px;display:flex;align-items:center;justify-content:center;border:var(--ds-bw) solid var(--ds-edge);border-radius:8px;background:var(--surface)}
.dsx-pi b{font:700 .84rem var(--ds-mono)}.dsx-pi small{margin-left:8px;font:500 .66rem var(--ds-mono);color:var(--muted)}
.dsx-pi[data-top]::after{content:attr(data-top);position:absolute;left:calc(100% + 12px);top:50%;transform:translateY(-50%);font:700 .66rem var(--ds-mono);color:var(--ds-act);white-space:nowrap}
.dsx-pile:empty::after,.dsx-lane:empty::after{content:"empty";margin:auto;font:500 .72rem var(--ds-mono);color:var(--muted)}
.dsx-stk .dsx-lbl{writing-mode:vertical-rl;transform:rotate(180deg);align-self:center}
/* queue: a pipe open at both ends, front on the left, rear on the right */
.dsx-q{display:inline-flex;flex-direction:column;gap:6px}
.dsx-lane{display:flex;align-items:center;gap:6px;min-width:160px;min-height:52px;padding:7px 10px;border-top:2px solid var(--ds-edge);border-bottom:2px solid var(--ds-edge)}
.dsx-lane .dsx-pi{min-width:44px}
.dsx-qe{display:flex;justify-content:space-between;font:700 .66rem var(--ds-mono);color:var(--ds-act)}
.dsx-qe span:first-child::before{content:"◀ "}.dsx-qe span:last-child::after{content:" ◀"}
/* legend of state colours */
.dsx-key{display:flex;flex-wrap:wrap;gap:6px 14px;font:500 .72rem Inter,system-ui,sans-serif;color:var(--muted)}
.dsx-key span{display:inline-flex;align-items:center;gap:6px}
.dsx-key span::before{content:"";width:11px;height:11px;border-radius:3px;border:1.5px solid var(--c);background:color-mix(in srgb,var(--c) 18%,var(--surface))}
.dsx-key .act{--c:var(--ds-act)}.dsx-key .cmp{--c:var(--ds-cmp)}.dsx-key .mod{--c:var(--ds-mod)}.dsx-key .del{--c:var(--ds-del)}.dsx-key .ok{--c:var(--ds-ok)}
/* the step controller: first · back · play/pause · next · last · speed · counter */
.dsx-ctl{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:10px}
.dsx-ctl .btn{min-width:38px;height:34px;padding:0 10px;display:inline-flex;align-items:center;justify-content:center;gap:6px}
.dsx-ctl .btn[data-a="play"]{min-width:92px}
.dsx-ctl .btn:disabled{opacity:.4;cursor:default}
.dsx-spd{display:inline-flex;align-items:center;gap:6px;margin-left:6px;font:500 .74rem Inter,system-ui,sans-serif;color:var(--muted)}
.dsx-spd select{height:30px;border-radius:8px;border:1px solid var(--line);background:var(--surface);color:var(--text);font:600 .74rem var(--ds-mono);padding:0 6px}
.dsx-cnt{margin-left:auto;font:500 .74rem var(--ds-mono);color:var(--muted);font-variant-numeric:tabular-nums}
.dsx-ctl .count{font:500 .74rem var(--ds-mono);color:var(--text);padding-left:6px} /* R4: a lab's own counter (stepBar) */
.dsx-prog{flex-basis:100%;height:3px;border-radius:3px;background:var(--line);overflow:hidden}
.dsx-prog i{display:block;height:100%;width:0;background:var(--ds-act);transition:width var(--ds-move) var(--ds-ease)}
.viz.ol[tabindex]:focus-visible{outline:2px solid var(--ds-act);outline-offset:3px}
@media (max-width:560px){:root{--ds-cell:38px}.dsx-spd span{display:none}.dsx-cnt{flex-basis:100%;margin-left:0}}
@media (prefers-reduced-motion:reduce){.dsx-c,.dsx-n,.dsx-pi,.dsx-pt,.dsx-prog i{transition:none}}

/* jvm labs v1 (labs-jvm.js: L25 #ojLoad .ojl- #ojJit .ojj-; L26 #ojAreas .oja- #ojLayout .ojo-; L27 #ojMark .ojm- #ojGen .ojg-; L28 #ojLeak .ojk- #ojTools .ojt-) */
/* l25 jvm execution labs v1: #ojLoad (.ojl-*), #ojJit (.ojj-*) — TEMPORARY file, merged into course.css as part of "jvm labs v1" */
.ojl-flow{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;margin:4px 0 10px}
.ojl-st{display:flex;flex-direction:column;align-items:center;gap:4px;padding:8px 4px;border-radius:10px;border:2px solid var(--line);background:var(--surface);font:600 .74rem Inter,sans-serif;color:var(--muted);text-align:center;min-width:0;transition:border-color .25s,background .25s,color .25s,opacity .25s}
.ojl-st i{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--soft);font:700 .7rem "JetBrains Mono",monospace;font-style:normal}
.ojl-st span{overflow-wrap:anywhere}
.ojl-st.ojl-on{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}
.ojl-st.ojl-on i{background:var(--accent);color:#fff}
.ojl-st.ojl-done{border-color:color-mix(in srgb,var(--good) 55%,var(--line));color:var(--good)}
.ojl-st.ojl-done i{background:var(--good-soft)}
.ojl-st.ojl-skip{opacity:.45;border-style:dashed;text-decoration:line-through}
.ojl-bc{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;min-height:2em;margin:0 0 10px;font:500 .78rem "JetBrains Mono",monospace}
.ojl-bc code{padding:4px 10px;border-radius:8px;background:#0b1020;color:#c7d2fe;overflow-x:auto;white-space:pre;max-width:100%}
.ojl-cap,.ojj-cap{font:700 .72rem "JetBrains Mono",monospace;letter-spacing:.04em;color:#8b93a7}
.ojl-cap i,.ojj-cap i{font-style:normal;font-weight:500;color:#6b7280}
