.rx19-grid{display:grid;gap:4px;margin:8px 0}.rx19-row{display:grid;grid-template-columns:3.4em repeat(10,minmax(0,1fr));gap:3px;align-items:center}.rx19-row small{font:600 .64rem "JetBrains Mono",monospace;color:var(--muted)}
