.rx20-svg .ed{stroke:var(--line);stroke-width:1.2}.rx20-svg .pa{stroke:#f59e0b;stroke-width:3}.rx20-svg .cur circle{fill:#f59e0b;stroke:#b45309}.rx20-svg .cand circle{stroke:#16a34a;stroke-width:3}.rx20-svg .star{fill:#dc2626;font-size:20px}
