.rx20-row i{display:block;height:10px;border-radius:5px;background:linear-gradient(90deg,#4f46e5,#16a34a);transition:width .4s}.rx20-row em{font:600 .72rem "JetBrains Mono",monospace;font-style:normal;text-align:right}.rx20-row small{grid-column:1/4;color:var(--muted);font-size:.72rem}
