/* nginx G11 kit v1 (labs-nginx.js, 2026-11-05): the console board's "Last load test" panel after wrk (bottleneck, worker CPU bars, slots) */
.ngx-pf{border:1px solid var(--line);border-left:3px solid var(--nk,#64748b);border-radius:10px;padding:10px 12px;background:var(--surface)}
.ngx-pfn{margin:0 0 8px;font-size:.8rem;line-height:1.4}.ngx-pfn b{display:block;font:700 .66rem "Inter Tight",sans-serif;text-transform:uppercase;letter-spacing:.06em;color:var(--nk,#64748b);margin-bottom:2px}
.ngx-pfw{display:grid;gap:4px;margin-bottom:8px}
.ngx-pfc{display:grid;grid-template-columns:6.2em minmax(0,1fr) 2.8em;align-items:center;gap:8px;font:600 .7rem "JetBrains Mono",monospace}
.ngx-pfc i{height:8px;border-radius:4px;background:linear-gradient(90deg,var(--nk,#64748b) var(--u),color-mix(in srgb,var(--muted) 18%,transparent) var(--u))}
