.ng11-pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.7rem}
.ng11-res{margin:6px 0;padding:6px 10px;border-radius:10px;font-size:.84rem}.ng11-bad{background:var(--bad-soft);color:var(--bad)}.ng11-ok{background:var(--good-soft);color:var(--good)}
.ng11-lw{display:grid;grid-template-columns:150px minmax(0,1fr);gap:14px;align-items:center;margin:10px 0}
