.ng11-q{background:var(--accent)}.ng11-a{background:#16a34a}
@keyframes ng11-spin{to{transform:rotate(360deg)}}
.ng11-chart{display:flex;flex-direction:column;gap:3px;margin:8px 0}
.ng11-crow{display:grid;grid-template-columns:4.2em minmax(0,1fr) auto;gap:8px;align-items:center;font:600 .7rem "JetBrains Mono",monospace;padding:1px 4px;border-radius:6px}
.ng11-crow.ng11-cur{background:color-mix(in srgb,var(--accent) 12%,transparent)}.ng11-crow em{font-style:normal;color:var(--muted);white-space:nowrap}
