.kx10-knobs{display:flex;flex-wrap:wrap;gap:10px;margin:4px 0 10px}.kx10-knob{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:10px;padding:4px 8px}
.kx10-knob b{font-size:.78rem}.kx10-knob output{font:700 .9rem "JetBrains Mono",monospace;min-width:1.4em;text-align:center}.kx10-knob .btn{padding:2px 10px}
