@media (max-width:640px){.kx10-wire{grid-template-columns:repeat(2,minmax(0,1fr))}.kx10-w-kt{grid-column:auto}.kx10-w-ad{grid-column:span 2}.kx10-row{grid-template-columns:minmax(0,1fr)}.kx10-axis{margin-left:0}}
