.sd-k-app{--kc:#6366f1}.sd-k-cache{--kc:#e11d48}.sd-k-queue{--kc:#d97706}.sd-k-db{--kc:#059669}.sd-k-worker{--kc:#ea580c}.sd-k-replica{--kc:#0d9488}
