.bh-gp{border:1px solid var(--line);border-radius:12px;padding:12px;background:var(--soft);align-self:start;display:grid;gap:8px;min-width:0}
.bh-gp>small{color:var(--muted);font-weight:700;font-size:.75rem;text-transform:uppercase;letter-spacing:.04em}
.bh-gx p{margin:0 0 6px;font-size:.88rem;line-height:1.5}
@media (max-width:720px){.bh-gd{grid-template-columns:minmax(0,1fr)}}
@media (max-width:560px){.bh-an,.bh-gd{padding-left:12px;padding-right:12px}}
@media (prefers-reduced-motion:reduce){.bh-al li{transition:none}}

/* behavioural B03 v1 (assets/labs/behavioural/labs-beh-03.js, 2026-11-05): impact estimator .bh3-calc */
.bh3-calc{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,240px),1fr));gap:12px;padding:14px 16px 0}
.bh3-fs{border:1px solid var(--line);border-radius:12px;padding:10px 12px;display:grid;gap:8px;margin:0;min-width:0}
.bh3-fs legend{font-weight:700;font-size:.85rem;padding:0 4px}
.bh3-fs input{width:100%;box-sizing:border-box;font:inherit;font-size:.9rem;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:6px 8px}
.bh3-out{margin:12px 16px 16px;padding:0;list-style:none;display:grid;gap:6px;font-size:.9rem}
