.dx2-act b{display:inline-grid;place-items:center;width:1.4em;height:1.4em;border-radius:50%;background:var(--soft);font-size:.68rem;margin-right:2px}.dx2-act.done{opacity:.6}
.dx2-pmap{border:1px solid var(--line);border-radius:12px;padding:8px 10px;background:var(--soft)}
