/* 5. inspect */
.dx2-tin{display:flex;align-items:center;gap:8px;margin:4px 0 8px}.dx2-tin span{font:600 .8rem "JetBrains Mono",monospace;color:var(--muted)}
.dx2-tin input{flex:1;min-width:0;font:.8rem "JetBrains Mono",monospace;padding:8px 10px;border-radius:10px;border:1px solid #1f2a44;background:#0b1020;color:#e2e8f0}
.dx2-two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;align-items:start}
.dx2-two .dx2-lbl code{text-transform:none;letter-spacing:0;font-size:.66rem}
