.dx2-score{margin-left:auto;font-size:.82rem;color:var(--muted)}
h4.dx2-ct{margin:4px 0 2px;font:700 1rem "Inter Tight",sans-serif}.dx2-cbody>p{margin:0 0 6px;font-size:.9rem}
.dx2-vs{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:5px}
