.dx2-ll{min-width:0;padding-right:8px}.dx2-ll code{display:block;font-size:.68rem;background:none;padding:0;border:0;box-shadow:none;overflow-wrap:anywhere}.dx2-ll small{display:block;font-size:.62rem;color:var(--muted);line-height:1.3}
