.sd24-kp small{display:block;font:700 .58rem Inter,sans-serif;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
.sd24-kp b{display:block;font:700 .86rem/1.3 "JetBrains Mono",monospace;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.sd24-kp>span.sd24-good{border-color:color-mix(in srgb,var(--good) 45%,var(--line));background:var(--good-soft)}
