.sd24-out{margin:0 0 12px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);line-height:1.5;font-size:.9rem}
.sd24-out.sd24-ok{border-color:color-mix(in srgb,var(--good) 45%,var(--line));background:var(--good-soft)}
.sd24-out.sd24-bad{border-color:color-mix(in srgb,var(--bad) 45%,var(--line));background:var(--bad-soft)}
.sd24-mx td,.sd24-mx th{font-size:.78rem}.sd24-mx tr.on td{background:color-mix(in srgb,#7c3aed 10%,transparent)}
