.ax1-col{display:flex;flex-direction:column;gap:6px;min-width:0}
.ax1-box{display:flex;flex-direction:column;align-items:center;text-align:center;gap:2px;padding:9px 8px;border-radius:12px;border:1px solid var(--line);background:var(--surface);font-weight:600;font-size:.85rem;min-width:0;transition:opacity .3s,border-color .3s,box-shadow .3s,background .3s}
.ax1-box small{font-weight:400;font-size:.7rem;color:var(--muted)}
.ax1-lbl{display:block;font-size:.74rem;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);margin-bottom:4px}.ax1-lbl code{text-transform:none}
.ax1-pre{margin:0;font:12px/1.5 "JetBrains Mono",monospace;background:#0b1020;color:#d6deeb;border-radius:10px;padding:10px 12px;white-space:pre-wrap;overflow-wrap:anywhere;min-height:3em;max-height:340px;overflow:auto}
.ax1-chk{display:inline-flex;align-items:center;gap:6px;font-size:.85rem;padding:4px 8px;border:1px solid var(--line);border-radius:10px;background:var(--surface);cursor:pointer}
.ax1-sel{display:flex;flex-direction:column;gap:4px;font-size:.84rem;min-width:0}
.ax1-sel select,.ax1-sel input{font:.84rem "JetBrains Mono",monospace;border:1px solid var(--line);border-radius:10px;padding:7px 9px;background:var(--surface);color:var(--text);max-width:100%;box-sizing:border-box}
