.ax1-tl li{font-size:.84rem;padding:6px 10px;border-radius:8px;border-left:4px solid var(--line);background:var(--surface)}
.ax1-tl li.ax1-y{border-left-color:var(--good);background:var(--good-soft)}.ax1-tl li.ax1-n{border-left-color:var(--bad);background:var(--bad-soft)}
.ax1-tl li.ax1-verd{font-weight:600;border-left-color:var(--accent)}
