.ax1-tg2{align-items:center;margin-bottom:8px}.ax1-tg2 .ax1-tabs{margin:0}
.ax1-sm{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:10px 0;font:600 .76rem "JetBrains Mono",monospace}
