/* api A02 v1 (assets/labs/api/labs-api-02.js, 2026-11-06): resource tree builder .ax2-words/.ax2-place/.ax2-tree, RPC → REST flip cards
   .ax2-card (.ax2-flip), id schemes .ax2-ids + .ax2-pt, nesting depth meter .ax2-depth, path/query bins .ax2-bins + deck .ax2-qc, URL linter
   .ax2-lout (.ax2-iss), query builder .ax2-fc + coloured URL .ax2-url + order table .ax2-ot, order state machine .ax2-sm + side panel,
   bulk rows .ax2-bt + round-trip dots .ax2-trips, singleton user switch .ax2-who, marketplace map .ax2-map */
.ax2-pad{padding:12px 14px 14px;min-width:0}
.ax2-pad>.ax-chips{padding:0 0 10px}
.ax2-msg{margin:10px 0 0;font-size:.9rem;min-height:1.4em}
.ax2-two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-items:start;margin-top:10px}
.ax2-btns{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 4px}
.ax2-tabs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.ax2-tabs .btn.on,.ax2-who.on{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}
.ax2-cl{min-width:0}
.ax2-mGET{color:#059669}.ax2-mPOST{color:#d97706}.ax2-mPUT,.ax2-mPATCH{color:#2563eb}.ax2-mDELETE{color:#dc2626}
.ax2-mGET,.ax2-mPOST,.ax2-mPUT,.ax2-mPATCH,.ax2-mDELETE{font-family:"JetBrains Mono",monospace}
/* 1 tree builder */
.ax2-story{margin:0 0 10px;font-size:.92rem;line-height:1.6;background:var(--soft);border:1px solid var(--line);border-radius:12px;padding:10px 12px}
.ax2-story i{color:var(--muted)}
.ax2-words{display:flex;flex-wrap:wrap;gap:6px}
.ax2-w{font-size:.8rem;padding:5px 11px}
.ax2-w.on{border-color:var(--good);background:var(--good-soft);color:var(--good)}
.ax2-place{display:flex;flex-direction:column;gap:6px;margin-top:4px}
.ax2-pl{border:1px solid var(--line);border-left:4px solid var(--line);border-radius:0 10px 10px 0;padding:6px 9px;background:var(--surface);font-size:.85rem}
.ax2-pl label{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.ax2-pl select{font:600 .78rem Inter,sans-serif;border:1px solid var(--line);border-radius:8px;padding:3px 6px;background:var(--surface);color:var(--text)}
.ax2-pl small{display:block;margin-top:4px;font-size:.76rem;color:var(--muted)}
.ax2-pl.ax2-ok{border-left-color:var(--good)}.ax2-pl.ax2-soft{border-left-color:var(--amber)}.ax2-pl.ax2-no{border-left-color:var(--bad)}
.ax2-tree,.ax2-tree ul{list-style:none;margin:4px 0 0;padding-left:16px}
.ax2-tree{padding-left:0;font-size:.8rem}
.ax2-tree li{margin:4px 0;position:relative}
.ax2-tree ul li::before{content:"";position:absolute;left:-11px;top:-4px;width:8px;height:14px;border-left:2px solid var(--line);border-bottom:2px solid var(--line);border-radius:0 0 0 5px}
.ax2-pp{display:inline-block;font:600 .74rem "JetBrains Mono",monospace;background:#0b1020;color:#a5e8c2;border-radius:7px;padding:2px 7px;margin:1px 2px 1px 0;overflow-wrap:anywhere}
.ax2-pp.ax2-it{color:#93c5fd}
.ax2-sg{font-size:.68rem;color:var(--accent);border:1px solid var(--accent);border-radius:6px;padding:0 5px}
/* 2 flip cards */
.ax2-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px}
.ax2-card{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:10px;min-width:0}
.ax2-card small{display:block;font:700 .64rem "Inter Tight",sans-serif;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin-bottom:4px}
.ax2-rpc,.ax2-rest{display:block;font-size:.78rem;overflow-wrap:anywhere;margin-bottom:8px}
.ax2-rpc{color:var(--bad);text-decoration:line-through;text-decoration-color:color-mix(in srgb,var(--bad) 45%,transparent)}
.ax2-opts{display:flex;flex-direction:column;gap:5px}
.ax2-o{font:.74rem "JetBrains Mono",monospace;text-align:left;padding:5px 8px;overflow-wrap:anywhere}
.ax2-o.ax2-wrong{background:var(--bad-soft);border-color:var(--bad);color:var(--bad)}
.ax2-back{display:none}.ax2-back p{margin:6px 0 0;font-size:.8rem}.ax2-back:focus{outline:none}
.ax2-flip{border-color:var(--good);background:var(--good-soft)}
