.ax2-ids{margin:4px 0 0;padding-left:1.4em;display:flex;flex-direction:column;gap:4px;font-size:.78rem}
.ax2-ids code{overflow-wrap:anywhere}.ax2-ids small{display:block;color:var(--muted);font-size:.68rem}
.ax2-pt{width:100%;border-collapse:collapse;font-size:.8rem;margin-top:4px}
.ax2-pt th,.ax2-pt td{text-align:left;padding:4px 7px;border-bottom:1px solid var(--line);vertical-align:top}
.ax2-pt th{font-weight:600;color:var(--muted);width:48%}
.ax2-pt tr.ax2-bad td{color:var(--bad);font-weight:600}
.ax2-badt{color:var(--bad);font-weight:700}.ax2-okt{color:var(--good);font-weight:700}
/* 4 depth meter */
.ax2-depth{padding:10px 14px 0}
.ax2-segs{display:flex;flex-wrap:wrap;align-items:center;gap:3px;font:600 .8rem "JetBrains Mono",monospace}
.ax2-segs i{color:var(--muted);font-style:normal}
.ax2-seg{border-radius:7px;padding:2px 8px;background:var(--accent-soft);color:var(--accent);border:1px solid transparent}
.ax2-seg.ax2-sid{background:var(--soft);color:var(--text);border-color:var(--line)}
.ax2-seg.ax2-deep{background:var(--bad-soft);color:var(--bad)}
.ax2-lv{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;margin-top:8px}
.ax2-lv span{text-align:center;font:700 .68rem "Inter Tight",sans-serif;text-transform:uppercase;padding:4px;border-radius:8px;border:1px solid var(--line);color:var(--muted);transition:background .3s}
.ax2-lv span.on{background:var(--good-soft);border-color:var(--good);color:var(--good)}
.ax2-lv span.ax2-over{background:var(--bad-soft);border-color:var(--bad);color:var(--bad)}
.ax2-dn{margin:6px 0 0;font-size:.84rem}
/* 5 path / query */
.ax2-bins{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;margin-bottom:12px}
.ax2-bin{border:2px dashed var(--line);border-radius:12px;padding:8px 10px;min-height:70px;min-width:0}
.ax2-bin>b{font:800 .8rem "Inter Tight",sans-serif;letter-spacing:.06em}.ax2-bin>small{display:block;color:var(--muted);font-size:.72rem}
.ax2-bin[data-b="path"]{border-color:color-mix(in srgb,var(--accent) 50%,var(--line))}.ax2-bin[data-b="query"]{border-color:color-mix(in srgb,var(--amber) 55%,var(--line))}
.ax2-bin ul{list-style:none;margin:6px 0 0;padding:0;display:flex;flex-direction:column;gap:4px}
.ax2-bin li{font-size:.78rem;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:3px 7px}
.ax2-bin li code{display:block;font-size:.72rem;overflow-wrap:anywhere}
