.ax11-msg.ax11-good{border-color:var(--good);background:var(--good-soft)}.ax11-msg.ax11-badm{border-color:var(--bad);background:var(--bad-soft)}.ax11-msg.ax11-warnm{border-color:var(--amber);background:var(--amber-soft)}
