.ax11-s2{background:var(--good-soft);border-color:var(--good);color:var(--good)}.ax11-s3{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
.ax11-s4{background:var(--amber-soft);border-color:var(--amber);color:var(--amber)}.ax11-s5{background:var(--bad-soft);border-color:var(--bad);color:var(--bad)}
.ax11-pre{margin:8px 0 0;font:12px/1.5 "JetBrains Mono",monospace;background:#0b1020;color:#d6deeb;border-radius:10px;padding:8px 10px;white-space:pre-wrap;overflow-wrap:anywhere;min-height:2em;max-height:340px;overflow:auto}
.ax11-2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;align-items:start}
.ax11-3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:10px}
.ax11-card{border:1px solid var(--line);border-radius:12px;padding:8px 10px;background:var(--surface);font-size:.84rem;min-width:0}
.ax11-card>small{display:block;font:700 .7rem "Inter Tight",sans-serif;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin-bottom:4px}
.ax11-in{display:flex;flex-direction:column;gap:4px;font-size:.8rem;font-weight:600;color:var(--muted);min-width:0}
.ax11-in input,.ax11-in select,.ax11-in textarea{font:13px "JetBrains Mono",monospace;border:1px solid var(--line);border-radius:8px;padding:6px 8px;background:var(--surface);color:var(--text);width:100%;box-sizing:border-box}
.ax11-emp{color:var(--muted);font-size:.8rem;list-style:none}
.ax11-notes,.ax11-rl{list-style:none;margin:10px 0 0;padding:0;display:flex;flex-direction:column;gap:5px;font-size:.84rem}
