.ax11-n-bad{border-left-color:var(--bad)!important;background:var(--bad-soft)!important}.ax11-n-warn{border-left-color:var(--amber)!important;background:var(--amber-soft)!important}
.ax11-n-good{border-left-color:var(--good)!important;background:var(--good-soft)!important}.ax11-n-info{border-left-color:var(--accent)!important}
