.ax11-tb th{color:var(--muted);font-weight:600;width:38%}
/* 1 flow */
.ax11-flow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:14px;align-items:start}
.ax11-tree{list-style:none;margin:0;padding:8px 10px;border:1px solid var(--line);border-radius:12px;background:var(--soft);font:12px/1.7 "JetBrains Mono",monospace;overflow-wrap:anywhere}
.ax11-tree li{border-radius:6px;padding:0 6px;transition:background .25s,color .25s}.ax11-tree li.ax11-l1{margin-left:16px}
.ax11-tree li.on{background:var(--accent-soft);color:var(--accent);font-weight:600}
.ax11-pipe{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:4px;counter-reset:ax11p}
.ax11-pipe li{border:1px solid var(--line);border-radius:10px;padding:5px 10px;background:var(--surface);opacity:.55;transition:opacity .25s,border-color .25s,box-shadow .25s,background .25s;display:flex;flex-wrap:wrap;gap:2px 8px;align-items:baseline}
