/* 2 builder */
.ax11-mapc{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:14px;align-items:start}
.ax11-ctl fieldset{border:1px solid var(--line);border-radius:10px;margin:0 0 8px;padding:6px 8px 0;min-width:0}
