.ax11-ctl .btn{font-family:"JetBrains Mono",monospace;font-size:.74rem}
/* 4–5 validation and errors */
.ax11-out .ax11-pre{max-height:260px}
.ax11-rq{max-height:120px}
/* 6 predictor */
.ax11-guess .btn{min-width:52px;justify-content:center;text-align:center}
.ax11-score{margin-left:auto;font:600 .8rem "JetBrains Mono",monospace;color:var(--muted)}
.ax11-sel{margin-bottom:10px}
/* 7 page */
.ax11-pg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-bottom:8px}
.ax11-grid{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:5px;margin:10px 0 0}
.ax11-grid span{border:1px solid var(--line);border-radius:8px;padding:4px 2px;text-align:center;font:600 .68rem "JetBrains Mono",monospace;color:var(--muted);background:var(--soft);transition:background .25s,border-color .25s,color .25s}
.ax11-grid b{display:block;font-size:.8rem;color:var(--text)}
.ax11-grid span.on{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
/* 8 etag */
.ax11-ctr{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:.8rem;margin-bottom:6px}.ax11-ctr b{font-family:"JetBrains Mono",monospace;color:var(--accent)}
.ax11-ctr code{overflow-wrap:anywhere}
.ax11-elog{margin:0;padding-left:18px;font-size:.78rem;display:flex;flex-direction:column;gap:4px}.ax11-elog li{overflow-wrap:anywhere}.ax11-elog small{color:var(--muted)}
/* 9 guard */
.ax11-gp{list-style:none;margin:6px 0 0;padding:0;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}
.ax11-gp li{border:1px solid var(--line);border-radius:10px;padding:6px 8px;background:var(--surface);font-size:.8rem;transition:opacity .25s,border-color .25s,background .25s;min-width:0;overflow-wrap:anywhere}
.ax11-gp li b{display:block;font-size:.78rem}.ax11-gp li small{color:var(--muted);font-size:.7rem}
.ax11-gp li.ax11-pass{border-color:var(--good);background:var(--good-soft)}
.ax11-gp li.ax11-here{border-color:var(--good);box-shadow:0 0 0 3px var(--good-soft)}
.ax11-gp li.ax11-stop{border-color:var(--bad);background:var(--bad-soft);box-shadow:0 0 0 3px var(--bad-soft)}
.ax11-gp li.ax11-skip{opacity:.4}
/* 10 tests */
.ax11-res{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:4px;font-size:.8rem}
.ax11-res li{border-left:3px solid var(--line);padding:3px 8px;border-radius:0 8px 8px 0;overflow-wrap:anywhere}
.ax11-res .ax11-sum{font-weight:700}
/* 11 case */
.ax11-lanes{display:flex;flex-wrap:wrap;gap:6px}
.ax11-lanes span{border:1px solid var(--line);border-radius:999px;padding:3px 12px;font-size:.8rem;font-weight:600;color:var(--muted);background:var(--soft);transition:background .25s,border-color .25s,color .25s}
.ax11-lanes span.on{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}
@media (prefers-reduced-motion:reduce){.ax11-pipe li,.ax11-tree li,.ax11-grid span,.ax11-gp li,.ax11-lanes span{transition:none}}
html.no-motion .ax11-pipe li,html.no-motion .ax11-tree li,html.no-motion .ax11-grid span,html.no-motion .ax11-gp li,html.no-motion .ax11-lanes span{transition:none}
@media (max-width:760px){
  .ax11-2,.ax11-3,.ax11-flow,.ax11-mapc{grid-template-columns:minmax(0,1fr)}
  .ax11-gp{grid-template-columns:minmax(0,1fr)}
  .ax11-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
  .ax11-pg{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
  .ax11-score{margin-left:0;width:100%}
}

