.apg-knob::after{content:"";position:absolute;top:3px;left:3px;width:14px;height:14px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.3);transition:transform .2s}
.apg-sw.on{border-color:#f97316;background:color-mix(in srgb,#f97316 9%,var(--surface));box-shadow:0 0 0 2px color-mix(in srgb,#f97316 18%,transparent)}
