.apg-swt{flex:1;min-width:0;display:flex;flex-direction:column}.apg-swt b{font-size:.88rem}.apg-swt small{color:var(--muted);font-size:.75rem}
.apg-les{flex:none;font:700 .66rem "JetBrains Mono",monospace;color:var(--muted);border:1px solid var(--line);border-radius:6px;padding:1px 5px}
.apg-fbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:6px 14px 12px}.apg-fmsg,.apg-lmsg{font-size:.82rem;color:var(--muted)}
.apg-scn{display:flex;flex-wrap:wrap;gap:6px;margin:4px 0 12px}.apg-sc{font-size:.8rem}
.apg-need{font:700 .62rem "JetBrains Mono",monospace;color:#f97316;margin-left:4px}
.apg-pipe{list-style:none;margin:0;padding:12px 14px 6px;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:6px}
