.apg-g::after{content:"→";position:absolute;right:-9px;top:50%;transform:translateY(-50%);font-size:.7rem;color:var(--muted)}.apg-g:last-child::after{content:none}
.apg-g b{font:700 .72rem "Inter Tight",sans-serif}.apg-g small{font:.66rem "JetBrains Mono",monospace;color:var(--muted);overflow-wrap:anywhere}
.apg-off{opacity:.45;border-style:dashed}.apg-skip{opacity:.7}
