.sb5-ctl label{display:inline-flex;gap:6px;align-items:center;flex-wrap:wrap}
.sb5-pad select{font:600 .76rem "JetBrains Mono",monospace;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text);padding:4px 6px;max-width:100%}
