.sb5-node b{font:600 .78rem "JetBrains Mono",monospace;overflow-wrap:anywhere}.sb5-node small{font-size:.68rem;color:var(--muted)}
.sb5-n-px{border-color:var(--accent);border-style:dashed}.sb5-n-adv{border-color:var(--amber);background:var(--amber-soft)}.sb5-n-tgt{border-color:var(--good)}
.sb5-node.sb5-cur{box-shadow:0 0 0 3px var(--accent-soft);border-color:var(--accent);border-style:solid}
.sb5-st .sb-step{padding-top:10px}
.sb5-rings{margin:4px 0 10px}
.sb5-proxy,.sb5-ring{position:relative;border-radius:14px;padding:22px 10px 10px;min-width:0}
.sb5-proxy{border:2px dashed var(--accent);background:var(--soft)}
.sb5-ring{border:1px solid var(--amber);background:color-mix(in srgb,var(--amber-soft) 55%,var(--surface));margin-top:2px}
.sb5-proxy>span,.sb5-ring>span{position:absolute;top:4px;left:10px;font:600 .7rem "JetBrains Mono",monospace;color:var(--muted)}.sb5-ring>span{color:var(--amber)}
.sb5-proxy.sb5-tie .sb5-ring{border-style:dashed;border-color:var(--bad)}
.sb5-core{padding:8px;border-radius:10px;border:1px solid var(--good);background:var(--good-soft);text-align:center;font:600 .8rem "JetBrains Mono",monospace}
.sb5-tl{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.sb5-ev{padding:4px 9px;border-radius:9px;border:1px solid var(--line);background:var(--surface);font:600 .72rem "JetBrains Mono",monospace}
.sb5-e-method{border-color:var(--good);background:var(--good-soft)}.sb5-e-at,.sb5-e-catch{border-color:var(--bad);background:var(--bad-soft)}
.sb5-e-in,.sb5-e-out,.sb5-e-skip,.sb5-e-fallback{border-color:var(--accent);background:var(--accent-soft)}
.sb5-pcs{display:flex;flex-direction:column;gap:5px;margin-bottom:10px}
.sb5-pc{text-align:left;font:inherit;font-size:.8rem;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:9px;padding:6px 9px;cursor:pointer;overflow-wrap:anywhere}
.sb5-pc b{color:var(--accent)}.sb5-pc.on{border-color:var(--accent);background:var(--accent-soft)}
.sb5-ms{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px}
.sb5-cls{display:flex;flex-direction:column;gap:5px;padding:9px;border:1px solid var(--line);border-radius:12px;background:var(--soft);min-width:0}
.sb5-cls>b{font:600 .78rem "JetBrains Mono",monospace}
.sb5-m{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:5px 8px;border:1px solid var(--line);border-radius:9px;background:var(--surface);font-size:.76rem;min-width:0;transition:border-color .2s,background .2s}
.sb5-m code{overflow-wrap:anywhere}.sb5-m small{font:600 .64rem "JetBrains Mono",monospace;color:var(--muted);white-space:nowrap}
