.sb5-uml{display:flex;justify-content:center;padding:12px;border-radius:14px;background:var(--soft);margin-bottom:10px}
.sb5-col{display:flex;flex-direction:column;align-items:center;gap:6px;min-width:0;max-width:100%}
.sb5-two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;width:100%}
.sb5-box{display:flex;flex-direction:column;gap:2px;padding:7px 11px;border:1px solid var(--line);border-radius:10px;background:var(--surface);text-align:center;min-width:0}
.sb5-box b{font:600 .78rem "JetBrains Mono",monospace;overflow-wrap:anywhere}.sb5-box small{font-size:.66rem;color:var(--muted)}
.sb5-b-if{border-style:dashed}.sb5-b-tgt{border-color:var(--good)}.sb5-b-px{border-color:var(--accent);background:var(--accent-soft)}
.sb5-b-err{border-style:dashed;border-color:var(--bad);opacity:.6;text-decoration:line-through}
.sb5-up{font:700 .7rem "JetBrains Mono",monospace;color:var(--accent)}.sb5-up.sb5-bad{color:var(--bad)}.sb5-cap{font-size:.7rem;color:var(--muted)}
.sb5-res{display:flex;flex-wrap:wrap;gap:8px;margin:6px 0}
.sb5-rc{display:flex;flex-direction:column;gap:2px;padding:7px 11px;border:1px solid var(--good);border-radius:10px;background:var(--good-soft);font-size:.74rem;min-width:0}
.sb5-rc b{font:600 .78rem "JetBrains Mono",monospace;overflow-wrap:anywhere}.sb5-rc.sb5-bad{border-color:var(--bad);background:var(--bad-soft)}.sb5-rc.sb5-mute{border-color:var(--line);background:var(--surface);opacity:.7}
.sb5-objs{margin:4px 0}
.sb5-obj{display:flex;flex-direction:column;gap:4px;padding:10px;border:1px solid var(--line);border-radius:12px;background:var(--surface);min-width:0;transition:opacity .25s}
.sb5-obj b{font:600 .78rem "JetBrains Mono",monospace;overflow-wrap:anywhere}.sb5-obj small{font-size:.68rem;color:var(--muted)}.sb5-obj code{font-size:.74rem}
.sb5-o-px{border:2px dashed var(--accent)}.sb5-o-tg{border-color:var(--good)}.sb5-obj.sb5-dim{opacity:.5}
.sb5-tag{display:inline-block;margin-top:4px;padding:3px 8px;border-radius:8px;font:600 .72rem "JetBrains Mono",monospace}
.sb5-t-adv{background:var(--amber-soft);color:var(--amber)}.sb5-t-ok{background:var(--good-soft);color:var(--good)}.sb5-t-bad{background:var(--bad-soft);color:var(--bad)}.sb5-t-mute{background:var(--soft);color:var(--muted)}
.sb5-bld{display:flex;flex-wrap:wrap;gap:8px;align-items:stretch;padding:12px;border-radius:14px;background:var(--soft)}
.sb5-gate{display:flex;flex-direction:column;justify-content:center;padding:8px 10px;border:2px dashed var(--accent);border-radius:11px;background:var(--accent-soft);font:600 .76rem "JetBrains Mono",monospace;color:var(--accent)}
.sb5-gate small{font-size:.66rem;color:var(--amber)}
.sb5-room{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px;padding:9px;border:1px solid var(--line);border-radius:11px;background:var(--surface)}
.sb5-room>b{font:600 .76rem "JetBrains Mono",monospace}
.sb5-mrow{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.sb5-mm{padding:3px 8px;border-radius:8px;border:1px solid var(--line);font:600 .74rem "JetBrains Mono",monospace}
.sb5-mm.sb5-hot{border-color:var(--bad);background:var(--bad-soft)}.sb5-mm.sb5-good{border-color:var(--good);background:var(--good-soft)}
.sb5-arr{font:600 .72rem "JetBrains Mono",monospace}.sb5-loop{color:var(--bad)}.sb5-out2{color:var(--good)}
.sb5-wall{padding:12px;border-radius:12px;border:1px solid var(--bad);background:var(--bad-soft);color:var(--bad);font:600 .8rem "JetBrains Mono",monospace}
.sb5-pxb{display:flex;flex-direction:column;gap:5px;padding:9px;border:2px dashed var(--accent);border-radius:12px;background:var(--surface);min-width:0;transition:opacity .25s}
.sb5-pxb>b{font:600 .74rem "JetBrains Mono",monospace;overflow-wrap:anywhere}.sb5-pxb.sb5-skipd{opacity:.45}
.sb5-adv{display:flex;flex-direction:column;padding:4px 8px;border:1px solid var(--line);border-radius:8px;min-width:0}
.sb5-adv code{font-size:.74rem}.sb5-adv small{font-size:.62rem;color:var(--muted);overflow-wrap:anywhere}
.sb5-adv.sb5-on{border-color:var(--amber);background:var(--amber-soft)}
@media (max-width:760px){.sb5-ms,.sb5-two{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){.sb5-node,.sb5-m,.sb5-obj,.sb5-pxb{transition:none}}
html.no-motion .sb5-node,html.no-motion .sb5-m,html.no-motion .sb5-obj,html.no-motion .sb5-pxb{transition:none}

/* dsa bank v2 "the lab" (assets/labs/dsa/labs-dsa-bank.js, 2026-11-06): courses/dsa/bank-<topic>.html (body.pg-page.dbk-page), generated by
   scripts/dsa-bank/build.mjs. Sticky timeline (.dbk-tl: ticks .dbk-tk with status .dbk-s0|1|2, .dbk-cur, .dbk-off; drawer .dbk-drawer), the bench
   (one article.dbk-p, stage tabs .dbk-sb, panels .dbk-sp[data-s]), sticky footer .dbk-foot. The lab breaks out of .wrap to 1240 px on wide screens.
   Notes: kb/dsa/dsa-bank-arrays.md. */
@media (min-width:1200px){body.dbk-page{padding-right:0}body.dbk-page nav{margin-right:0}}
.dbk-lab{--dbk-w:min(1240px,calc(100vw - 64px));width:var(--dbk-w);margin:18px 0 8px calc((100% - var(--dbk-w)) / 2);position:relative;font-size:15px}
@media (max-width:920px){.dbk-lab{width:auto;margin-left:0}}
/* timeline */
.dbk-tl{position:sticky;top:60px;z-index:20;background:color-mix(in srgb,var(--surface) 94%,transparent);backdrop-filter:saturate(1.3) blur(10px);-webkit-backdrop-filter:saturate(1.3) blur(10px);
  border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);padding:10px 14px 10px}
.dbk-tlhead{display:flex;flex-wrap:wrap;align-items:center;gap:6px 18px}
.dbk-now{display:flex;align-items:baseline;gap:10px;flex:1 1 260px;min-width:0}
.dbk-nowk{font:600 .82rem Inter,sans-serif;color:var(--muted);white-space:nowrap}.dbk-nowk b{font:800 1.15rem "Inter Tight",Inter,sans-serif;color:var(--text)}
.dbk-nowt{font:650 .95rem "Inter Tight",Inter,sans-serif;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.dbk-pct{display:flex;align-items:center;gap:8px;font-size:.8rem;color:var(--muted);white-space:nowrap}.dbk-pct b{color:var(--good)}
.dbk-pct i{width:110px;height:6px;border-radius:9px;background:var(--soft);overflow:hidden}.dbk-pct em{display:block;height:100%;width:0;border-radius:inherit;background:linear-gradient(90deg,var(--good),color-mix(in srgb,var(--good) 55%,var(--accent)));transition:width .6s}
.dbk-tlacts{display:flex;gap:6px}
.dbk-tlb{font:600 .8rem Inter,sans-serif;color:var(--text);background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:5px 10px;cursor:pointer;white-space:nowrap}
.dbk-tlb:hover{border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}.dbk-tlb[aria-expanded="true"]{color:var(--accent);background:var(--accent-soft)}
.dbk-track{display:flex;gap:12px;margin-top:8px;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:thin;padding:0 2px 4px}
.dbk-seg{flex:var(--n) 1 0;min-width:calc(var(--n) * 11px);display:flex;flex-direction:column;gap:4px}
.dbk-segl{font:500 .7rem Inter,sans-serif;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dbk-segl b{font:700 .7rem "JetBrains Mono",monospace;color:var(--text)}.dbk-segl em{font:600 .66rem "JetBrains Mono",monospace;font-style:normal;margin-left:2px}
.dbk-segon .dbk-segl,.dbk-segon .dbk-segl b{color:var(--accent)}
.dbk-ticks{display:flex;gap:2px;height:28px;align-items:center}
.dbk-tk{flex:1 1 0;min-width:7px;height:16px;padding:0;border:0;border-radius:4px;cursor:pointer;background:color-mix(in srgb,var(--muted) 24%,var(--surface));transition:height .15s,background .3s,opacity .2s}
.dbk-tk:hover{height:24px}
.dbk-tk.dbk-s1{background:var(--amber)}.dbk-tk.dbk-s2{background:var(--good)}
.dbk-tk.dbk-cur{height:26px;box-shadow:0 0 0 2px var(--surface),0 0 0 4px var(--accent)}
.dbk-tk.dbk-off{opacity:.22}
.dbk-tk:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.dbk-tk.dbk-pop{animation:dbkPop .8s cubic-bezier(.2,.7,.2,1)}
@keyframes dbkPop{0%{transform:scaleY(1)}35%{transform:scaleY(1.5)}100%{transform:none}}
.dbk-tip{position:absolute;z-index:3;max-width:300px;padding:6px 10px;border-radius:9px;background:var(--text);color:var(--bg);font:500 .78rem/1.35 Inter,sans-serif;pointer-events:none;box-shadow:0 8px 24px rgba(0,0,0,.2)}
.dbk-tips{display:inline-block;margin-left:8px;font:600 .68rem "JetBrains Mono",monospace;opacity:.75}
.dbk-drawer{position:absolute;z-index:4;top:calc(100% + 8px);right:0;width:min(440px,100%);max-height:min(70vh,640px);display:flex;flex-direction:column;background:var(--surface);
  border:1px solid var(--line);border-radius:16px;box-shadow:0 24px 60px rgba(0,0,0,.25);overflow:hidden}
.dbk-drawer[hidden]{display:none}
.dbk-dwh{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line)}.dbk-dwh b{font-family:"Inter Tight",Inter,sans-serif}
.dbk-dwf{flex:1;font-size:.76rem;color:var(--muted)}
.dbk-lnk{font:inherit;color:var(--accent);background:none;border:0;padding:0;cursor:pointer;text-decoration:underline}
.dbk-dwl{overflow:auto;padding:4px 8px 12px;overscroll-behavior:contain}
.dbk-dwg h4{display:flex;align-items:center;gap:8px;margin:12px 6px 4px;font:700 .82rem "Inter Tight",Inter,sans-serif}.dbk-dwg h4 em{margin-left:auto;font:600 .7rem "JetBrains Mono",monospace;font-style:normal;color:var(--muted)}
.dbk-dwg ol{list-style:none;margin:0;padding:0}
.dbk-dwi{width:100%;display:grid;grid-template-columns:12px 26px 1fr;align-items:center;gap:8px;text-align:left;font:500 .86rem Inter,sans-serif;color:var(--text);background:none;border:0;border-radius:9px;padding:6px 8px;cursor:pointer}
.dbk-dwi:hover,.dbk-dwi:focus-visible{background:var(--soft);outline:none}
.dbk-dwi.dbk-cur{background:var(--accent-soft);color:var(--accent)}
