.dbk-dwi[data-st="1"] i{background:var(--amber);border-color:var(--amber)}.dbk-dwi[data-st="2"] i{background:var(--good);border-color:var(--good)}
.dbk-dwn{font:600 .72rem "JetBrains Mono",monospace;color:var(--muted)}
/* the bench */
.dbk-bench{margin-top:14px}
article.dbk-p [hidden],.dbk-tl [hidden]{display:none!important}
article.dbk-p{background:var(--surface);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);overflow:clip;scroll-margin-top:150px}
.dbk-enter{animation:dbkEnter .35s cubic-bezier(.2,.7,.2,1)}
@keyframes dbkEnter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.dbk-ph{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;padding:18px 22px 14px;background:linear-gradient(180deg,color-mix(in srgb,var(--accent-soft) 55%,var(--surface)),var(--surface))}
.dbk-ph .dbk-n{font:700 .8rem "JetBrains Mono",monospace;color:var(--muted)}
.dbk-ph h3.dbk-t{margin:0;flex:1 1 260px;font:750 1.35rem/1.25 "Inter Tight",Inter,sans-serif;letter-spacing:-.01em;color:var(--text)}
.dbk-lv{font:700 .68rem "JetBrains Mono",monospace;border-radius:6px;padding:2px 7px;color:#fff;white-space:nowrap}
.dbk-l0{background:#64748b}.dbk-l1{background:#16a34a}.dbk-l2{background:#2563eb}.dbk-l3{background:#d97706}.dbk-l4{background:#dc2626}.dbk-l5{background:#7c3aed}
.dbk-ph .dbk-mark{display:flex;gap:6px}
.dbk-win{animation:dbkWin 1.2s ease-out}
@keyframes dbkWin{0%{box-shadow:inset 0 0 0 0 transparent}25%{box-shadow:inset 0 -60px 60px -30px color-mix(in srgb,var(--good) 35%,transparent)}100%{box-shadow:inset 0 0 0 0 transparent}}
.dbk-mb{font:600 .8rem Inter,sans-serif;border:1px solid var(--line);background:var(--surface);color:var(--text);border-radius:10px;padding:5px 12px;cursor:pointer}
.dbk-mb[data-dbk="tried"][aria-pressed="true"]{background:var(--amber-soft);border-color:var(--amber);color:var(--amber)}
.dbk-mb[data-dbk="solved"][aria-pressed="true"]{background:var(--good-soft);border-color:var(--good);color:var(--good)}
.dbk-stg{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--soft)}
.dbk-sb{display:flex;align-items:center;gap:8px;min-width:0;padding:12px 14px;border:0;border-bottom:2px solid transparent;background:none;color:var(--muted);font:600 .84rem Inter,sans-serif;cursor:pointer;text-align:left}
.dbk-sb span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dbk-sb i{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:50%;border:1.5px solid currentColor;font:700 .72rem "JetBrains Mono",monospace;font-style:normal}
.dbk-sb:hover{color:var(--text)}
.dbk-sb.dbk-ahead{opacity:.6}
.dbk-sb.dbk-done i{background:var(--good);border-color:var(--good);color:#fff}
.dbk-sb[aria-selected="true"]{color:var(--accent);border-bottom-color:var(--accent);background:var(--surface);opacity:1}
.dbk-sb[aria-selected="true"] i{background:var(--accent);border-color:var(--accent);color:#fff}
.dbk-sb:focus-visible{outline:2px solid var(--accent);outline-offset:-3px}
.dbk-sp{padding:22px 24px 24px}
.dbk-sp h4{margin:18px 0 6px;font:700 1rem "Inter Tight",Inter,sans-serif}.dbk-sp h4:first-child{margin-top:0}
.dbk-sp h5{margin:18px 0 6px;font:700 .88rem "Inter Tight",Inter,sans-serif;color:var(--accent)}
.dbk-nx{grid-column:1/-1;display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;margin-top:22px;padding-top:16px;border-top:1px dashed var(--line)}
.dbk-io{font:500 .84rem/1.55 "JetBrains Mono",monospace;background:var(--code-bg);color:var(--code-text);border-radius:12px;padding:10px 14px;white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}
