.dbk-lbtns{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}
/* stage 4 */
.dbk-s4:not([hidden]){display:grid;grid-template-columns:minmax(0,1fr);gap:18px 26px}
@media (min-width:1000px){.dbk-s4:not([hidden]){grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr)}.dbk-task{position:sticky;top:180px;align-self:start}}
