.dbk-tabs{display:inline-flex;flex-wrap:wrap;gap:4px;padding:4px;border-radius:12px;background:var(--soft);border:1px solid var(--line);margin-bottom:10px}
.dbk-tab{font:600 .82rem Inter,sans-serif;color:var(--muted);background:none;border:0;border-radius:9px;padding:6px 14px;cursor:pointer}
.dbk-tab:hover{color:var(--text)}.dbk-tab[aria-selected="true"]{background:var(--surface);color:var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.08)}
