.dbk-sh{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px}.dbk-sh b{font-family:"Inter Tight",Inter,sans-serif}
.dbk-cost{font:600 .74rem "JetBrains Mono",monospace;color:var(--good);background:var(--good-soft);border-radius:8px;padding:2px 8px}
