.dbk-tb{width:auto;font-size:.82rem}.dbk-tb th{text-transform:none}.dbk-tb td,.dbk-tb th{padding:5px 10px;font-family:"JetBrains Mono",monospace;font-size:.78rem}
.dbk-fu li,.dbk-faces li,.dbk-mis li{margin:4px 0;font-size:.92rem}
.dbk-endl{margin-top:16px}
/* footer */
.dbk-foot{position:sticky;bottom:12px;z-index:15;display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:12px;padding:10px 12px;
  background:color-mix(in srgb,var(--surface) 94%,transparent);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}
.dbk-dots{display:flex;align-items:center;gap:8px;min-width:0}
.dbk-dot{width:12px;height:12px;padding:0;border-radius:99px;border:2px solid color-mix(in srgb,var(--muted) 55%,var(--line));background:none;cursor:pointer;transition:width .25s,background .25s}
.dbk-dot i{display:none}
.dbk-dot.dbk-seen{background:color-mix(in srgb,var(--muted) 45%,var(--surface))}
