.dbk-dot:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.dbk-dotl{font-size:.8rem;color:var(--muted);margin-left:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dbk-foot .btn:disabled{opacity:.45;cursor:default}
/* sections below the lab */
.dbk-method{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:14px 0}
.dbk-method div{border:1px solid var(--line);border-radius:14px;padding:12px 14px;background:var(--surface)}
.dbk-method b{display:block;font-family:"Inter Tight",Inter,sans-serif;color:var(--accent);margin-bottom:4px}.dbk-method span{font-size:.85rem;color:var(--muted)}
.dbk-legend{list-style:none;padding:0;margin:10px 0;display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:6px 18px}
.dbk-legend li{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 8px;font-size:.86rem;padding:6px 0;border-bottom:1px dashed var(--line)}
.dbk-legend li>span:nth-child(2){flex:1;min-width:160px;color:var(--muted)}.dbk-legend a{font-size:.78rem;white-space:nowrap}
.dbk-pc{--pc:#64748b;display:inline-flex;align-items:center;gap:5px;font:600 .72rem Inter,sans-serif;color:color-mix(in srgb,var(--pc) 75%,var(--text));background:color-mix(in srgb,var(--pc) 13%,var(--surface));border:1px solid color-mix(in srgb,var(--pc) 35%,var(--line));border-radius:99px;padding:2px 9px;white-space:nowrap}
.dbk-pc::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--pc)}
.dbk-filters{border:1px solid var(--line);border-radius:16px;padding:12px 14px;background:var(--surface);box-shadow:var(--shadow);display:flex;flex-direction:column;gap:10px}
