.dbk-frow>span,.dbk-frow label>span{font-size:.76rem;color:var(--muted);margin-right:4px}
.dbk-frow .chip[aria-pressed="true"]{color:var(--accent);border-color:color-mix(in srgb,var(--accent) 55%,var(--line));background:var(--accent-soft)}
.dbk-frow select,.dbk-frow input[type=search]{font:inherit;font-size:.86rem;color:var(--text);background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:6px 9px;max-width:100%}
.dbk-q{flex:1;display:flex;align-items:center;min-width:200px}.dbk-q input{flex:1;min-width:0}
.dbk-un{font-size:.86rem;display:flex;align-items:center;gap:6px}
.dbk-fsum{justify-content:space-between}.dbk-shown{font-size:.86rem;color:var(--muted)}.dbk-shown b{color:var(--text)}
.dbk-facts{display:flex;flex-wrap:wrap;gap:6px}
.dbk-lvbars{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:6px 18px;padding-top:8px;border-top:1px dashed var(--line)}
.dbk-lb{display:grid;grid-template-columns:1fr 60px 38px;gap:8px;align-items:center;font-size:.76rem;color:var(--muted)}
.dbk-lb span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dbk-lb i{height:6px;border-radius:9px;background:var(--soft);overflow:hidden}.dbk-lb em{display:block;height:100%;background:var(--good);border-radius:9px;transition:width .6s}
