.dbk-dq{font:600 1.02rem/1.5 "Inter Tight",Inter,sans-serif;min-height:1.5em;margin:4px 0 12px}
.dbk-dopts{display:flex;flex-wrap:wrap;gap:8px;min-height:10px}
.dbk-dopts .dbk-pc{cursor:pointer;font-size:.82rem;padding:6px 12px}
.dbk-dopts .dbk-ok{outline:2px solid var(--good)}.dbk-dopts .dbk-no{outline:2px solid var(--bad);opacity:.8}
.dspa-rain span.dbk-rp i.b{background:var(--accent)}
/* phones: the stage bar keeps numbers and names only the open stage; the track scrolls inside itself */
@media (max-width:700px){
  .dbk-stg{display:flex}.dbk-sb{flex:none;justify-content:center;padding:10px 8px}.dbk-sb span{display:none}
  .dbk-sb[aria-selected="true"]{flex:1;justify-content:flex-start}.dbk-sb[aria-selected="true"] span{display:inline}
}
@media (max-width:560px){
  .dbk-tl{top:56px;padding:8px 10px;border-radius:14px}
  .dbk-nowt{display:none}.dbk-pct i{width:56px}.dbk-tlb span{display:none}
  .dbk-segn{display:none}.dbk-seg{min-width:calc(var(--n) * 10px)}
  .dbk-ph{padding:14px 14px 10px}.dbk-ph h3.dbk-t{font-size:1.15rem}
  .dbk-sp{padding:16px 14px 18px}
  .dbk-foot{bottom:8px;padding:8px}.dbk-foot .btn span{display:none}.dbk-dotl{display:none}
  .dbk-legend{grid-template-columns:1fr}
