.spg-mg{display:grid;grid-template-columns:repeat(auto-fill,minmax(205px,1fr));gap:8px}
.spg-mc{all:unset;box-sizing:border-box;cursor:pointer;position:relative;display:grid;grid-template-columns:auto minmax(0,1fr);gap:1px 9px;align-items:center;padding:9px 34px 9px 10px;border:1px solid var(--line);border-radius:12px;background:var(--soft);transition:border-color .2s,transform .2s,box-shadow .2s,background .2s}
.spg-mc:hover{border-color:var(--accent);transform:translateY(-1px);box-shadow:var(--shadow)}.spg-mc:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.spg-mc.on{border-color:var(--accent);background:var(--accent-soft)}
.spg-mc b{font-size:.84rem;line-height:1.3;color:var(--text)}.spg-mc small{grid-column:2;font-size:.7rem;color:var(--muted)}
.spg-lv{grid-row:span 2;display:inline-grid;place-items:center;width:24px;height:24px;border-radius:8px;font:700 .7rem "JetBrains Mono",monospace;color:#fff;background:var(--good-fill)}
.spg-lvI{background:var(--accent-fill)}.spg-lvA{background:var(--accent-2-fill)}
.spg-ckm{position:absolute;right:9px;top:50%;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;background:var(--good-fill);color:#fff;font-style:normal;font-size:.68rem;opacity:0;transform:translateY(-50%) scale(.6);transition:opacity .25s,transform .25s}
.spg-mc.spg-done .spg-ckm{opacity:1;transform:translateY(-50%) scale(1)}
#spgPlay{margin-top:0}
.spg-top{padding:14px 14px 10px;border-bottom:1px solid var(--line);background:linear-gradient(180deg,var(--soft),var(--surface))}
.spg-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.spg-tab{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:1px;padding:9px 12px;border:1px solid var(--line);border-radius:12px;background:var(--surface);transition:border-color .2s,background .2s,box-shadow .2s;min-width:0}
.spg-tab b{font:700 .9rem "Inter Tight",sans-serif;color:var(--text)}.spg-tab small{font-size:.7rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.spg-tab:hover{border-color:var(--accent)}.spg-tab:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.spg-tab.on{border-color:var(--accent);background:var(--accent-soft);box-shadow:inset 0 -3px 0 var(--accent)}
.spg-mb{margin:10px 0 0;padding:10px 12px;border:1px solid var(--accent);border-left-width:4px;border-radius:12px;background:var(--accent-soft)}
.spg-mbh{display:flex;align-items:center;gap:8px}.spg-mbh .spg-lv{grid-row:auto;flex:none}.spg-mbh b{font-size:.9rem}
.spg-mx{all:unset;cursor:pointer;margin-left:auto;width:28px;height:28px;display:grid;place-items:center;border-radius:8px;color:var(--muted);font-size:1.15rem}
