.spg-mt{margin:6px 0 4px;font-size:.88rem;line-height:1.5}.spg-mb code{white-space:normal;overflow-wrap:anywhere}
.spg-mm{margin:4px 0;font-size:.84rem;color:var(--muted);line-height:1.5}.spg-mm.spg-ok{color:var(--good);font-weight:600}.spg-mm.spg-near{color:var(--amber)}
.spg-mhint summary{cursor:pointer;font-size:.8rem;font-weight:600;color:var(--accent)}.spg-mhint div{margin-top:6px;font-size:.82rem;line-height:1.55}
.spg-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:10px}
.spg-bar .btn{padding:6px 12px;font-size:.8rem}.spg-st{font-size:.8rem;color:var(--muted)}.spg-st b{color:var(--accent)}.spg-sp{flex:1}
.spg-msg{margin:8px 0 0;font-size:.82rem;padding:7px 10px;border-radius:10px;background:var(--soft);overflow-wrap:anywhere}
.spg-msg.spg-bad{background:var(--bad-soft);color:var(--bad)}.spg-msg.spg-good{background:var(--good-soft);color:var(--good)}
.spg-pal{margin-top:10px;border-top:1px solid var(--line);padding-top:8px}
.spg-pal summary{cursor:pointer;font-weight:600;font-size:.84rem}.spg-pal summary small{font-weight:400;color:var(--muted);margin-left:6px}
