.ldk-pill{font:600 .66rem/1.2 "JetBrains Mono",monospace;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);background:var(--accent-soft);border-radius:99px;padding:3px 9px}
.ldk-mut{color:var(--muted);font-size:.84rem}
.ldk-sp{flex:1 1 auto}
.ldk-miss{padding:16px 18px;color:var(--muted)}
.ldk .ldk-ctl{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:12px 18px 0}
.ldk-pos{font:600 .78rem "JetBrains Mono",monospace;color:var(--muted)}
.ldk-ts{font:700 .62rem/1 "JetBrains Mono",monospace;letter-spacing:.05em;text-transform:uppercase;padding:3px 7px;border-radius:99px;margin-left:6px;vertical-align:middle}
.ldk-ts.run{color:var(--accent);background:var(--accent-soft)}.ldk-ts.blk{color:var(--bad);background:var(--bad-soft)}.ldk-ts.fin{color:var(--good);background:var(--good-soft)}
.ldk-chip{display:inline-block;font:600 .74rem "JetBrains Mono",monospace;padding:2px 8px;border-radius:7px;background:var(--soft);border:1px solid var(--line);margin:2px 3px 2px 0}
.ldk-chip.add{color:var(--good);background:var(--good-soft);border-color:color-mix(in srgb,var(--good) 35%,var(--line))}
.ldk-chip.mod{color:var(--amber);background:var(--amber-soft);border-color:color-mix(in srgb,var(--amber) 35%,var(--line))}
.ldk-verd{margin:12px 18px 0;padding:10px 14px;border-radius:11px;background:var(--soft);border-left:4px solid var(--muted);font-size:.9rem}
.ldk-verd.good{background:var(--good-soft);border-left-color:var(--good)}.ldk-verd.bad{background:var(--bad-soft);border-left-color:var(--bad)}
.ldk-code{margin:10px 18px 0;padding:10px 0;background:var(--code-bg);color:var(--code-text);border:1px solid var(--code-line);border-radius:12px;font:12.5px/1.6 "JetBrains Mono",monospace;overflow:auto;max-height:440px;tab-size:4;font-variant-ligatures:none;white-space:normal}
.ldk-ln{display:block;padding:0 14px;white-space:pre;border-left:3px solid transparent;min-height:1.6em}
.ldk-ln>i{font-style:normal;display:inline-block;width:1.4em;color:var(--muted)}
.ldk-ln.add{background:color-mix(in srgb,#22c55e 16%,var(--code-bg));border-left-color:#4ade80}.ldk-ln.add>i{color:#4ade80}
.ldk-ln.del{background:color-mix(in srgb,#ef4444 14%,var(--code-bg));border-left-color:#f87171;text-decoration:line-through;text-decoration-color:#f87171}.ldk-ln.del>i{color:#f87171}
.ldk-fold{color:var(--muted);font-style:italic;background:color-mix(in srgb,var(--code-text) 5%,var(--code-bg))}
.ldk-tog{display:inline-flex;align-items:center;gap:6px;font-size:.84rem;cursor:pointer}.ldk-tog em{font-style:normal;color:var(--muted);font:600 .74rem "JetBrains Mono",monospace}
.ldk-modes{display:flex;flex-wrap:wrap;gap:6px;padding:12px 18px 0}
.ldk-modes button,.ldk-tabs [role=tab]{font:600 .82rem Inter,sans-serif;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:99px;padding:6px 13px;cursor:pointer}
.ldk-modes button[aria-pressed=true],.ldk-tabs [aria-selected=true]{color:var(--accent);background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
.ldk-modes button:focus-visible,.ldk-tabs [role=tab]:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.ldk details{border-top:0;padding:0}
.ldk-plan{margin:12px 18px 0;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.ldk .ldk-plan>summary{padding:10px 14px;font-weight:600;font-size:.88rem;color:var(--text)}
