.ldk-plan .ldk-code{margin:10px 12px 12px}
.ldk-why ul{margin:10px 18px 0;padding-left:20px;font-size:.88rem}.ldk-why li{margin:0 0 4px}
.ldk-plan .ldk-why ul{margin:10px 14px 0}
/* requirements */
.ldk-reqg{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:10px;padding:14px 18px 0}
.ldk-reqg>div{background:var(--soft);border:1px solid var(--line);border-radius:12px;padding:10px 14px 4px}
.ldk-reqg h4,.ldk-rg h4,.ldk-ask h4{margin:0 0 6px;font:700 .7rem "JetBrains Mono",monospace;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
.ldk-reqg ul{margin:0;padding-left:18px;font-size:.88rem}.ldk-reqg li{margin:0 0 6px}
.ldk-ask{margin:14px 18px 0;padding:12px 14px;border:1px dashed color-mix(in srgb,var(--accent) 45%,var(--line));border-radius:12px;background:color-mix(in srgb,var(--accent-soft) 40%,transparent)}
.ldk-askh{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.ldk-askh span{font:600 .76rem "JetBrains Mono",monospace;color:var(--accent)}
.ldk-ask p{margin:4px 0 8px}
.ldk-ask ol{margin:0;padding-left:22px;display:grid;gap:6px}
.ldk-q{font:inherit;font-size:.9rem;text-align:left;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:9px;padding:6px 10px;cursor:pointer;width:100%}
.ldk-q:hover{border-color:var(--accent)}.ldk-q.ldk-asked{border-color:color-mix(in srgb,var(--accent) 50%,var(--line))}
.ldk-q::before{content:"? ";color:var(--accent);font-weight:700}
.ldk-a{margin:6px 0 2px;padding:7px 11px;border-left:3px solid var(--accent);background:var(--surface);border-radius:0 9px 9px 0;font-size:.88rem}
/* 7-step stepper */
.ldk-clock{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;padding:14px 18px 0}
.ldk-time{font:700 1.5rem/1 "JetBrains Mono",monospace;font-variant-numeric:tabular-nums;color:var(--accent)}
.ldk-clock .btn[aria-pressed=true]{background:var(--accent-soft);color:var(--accent)}
.ldk-segs{display:flex;gap:4px;padding:12px 18px 0}
.ldk-seg{position:relative;min-width:0;height:44px;border-radius:9px;background:var(--soft);border:1px solid var(--line);overflow:hidden;cursor:pointer;padding:0;font:inherit;color:var(--muted);text-align:left}
.ldk-seg i{position:absolute;inset:0 auto 0 0;width:0;background:color-mix(in srgb,var(--accent) 20%,transparent);transition:width .3s linear}
.ldk-seg.done i{background:color-mix(in srgb,var(--good) 24%,transparent)}
.ldk-seg span{position:relative;display:block;padding:4px 7px;font-size:.74rem;line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ldk-seg span b{color:var(--text)}.ldk-seg span em{display:block;font-style:normal;font:600 .66rem "JetBrains Mono",monospace}
.ldk-seg.on{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft);color:var(--text)}
.ldk-seg:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
@media (max-width:700px){.ldk-seg span{font-size:0;padding:4px}.ldk-seg span b{font-size:.78rem}.ldk-seg span em{font-size:.6rem}}
.ldk-card{display:flex;gap:14px;align-items:flex-start;margin:12px 18px 0;padding:14px 16px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(135deg,color-mix(in srgb,var(--accent-soft) 70%,transparent),var(--surface) 70%)}
.ldk-cnum{flex:none;width:40px;height:40px;border-radius:12px;display:grid;place-items:center;font:800 1.2rem "Inter Tight",Inter,sans-serif;color:#fff;background:linear-gradient(135deg,var(--accent),var(--accent-2))}
.ldk-card h4{margin:0;font:700 1rem "Inter Tight",Inter,sans-serif}
.ldk-gen{margin:3px 0 6px;color:var(--muted);font-size:.86rem}
.ldk-note{font-size:.92rem}
/* class diagram */
.ldk-ubar{display:flex;align-items:center;gap:10px;padding:10px 18px}
.ldk-canvas{margin:0 18px;border:1px solid var(--line);border-radius:12px;max-height:620px}
.ldk-uml .lp-legend{margin:0 18px;border-top:0}
.ldk-unote{margin:8px 18px 0;padding:10px 14px;border-radius:11px;background:var(--soft);font-size:.9rem;min-height:1.4em}
