.ldk-bah.ldk-bad b{color:var(--bad)}.ldk-bah.ldk-good b{color:var(--good)}
/* follow-up */
.ldk-askb{display:flex;gap:12px;align-items:flex-start;margin:14px 18px 0}
.ldk-who{flex:none;font:700 .66rem "JetBrains Mono",monospace;letter-spacing:.06em;text-transform:uppercase;color:#fff;background:linear-gradient(135deg,var(--accent),var(--accent-2));border-radius:99px;padding:5px 10px}
.ldk-askb p{margin:0;padding:10px 14px;border-radius:4px 14px 14px 14px;background:var(--soft);border:1px solid var(--line);font-size:.95rem}
.ldk-fus{display:flex;flex-wrap:wrap;gap:6px 18px;align-items:center;padding:10px 14px 0;font-size:.84rem}
.ldk-fus em{color:var(--muted)}.ldk-plus{color:var(--good)}.ldk-minus{color:var(--bad)}
