/* race */
.ldk-rg{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.9fr) minmax(0,1fr);gap:10px;padding:14px 18px 0}
.ldk-lane,.ldk-shared{border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:var(--surface);min-width:0}
