.ldk-lane ol{list-style:none;margin:0;padding:0;display:grid;gap:4px;counter-reset:op}
.ldk-lane li{counter-increment:op;position:relative;font:12.5px/1.45 "JetBrains Mono",monospace;padding:5px 8px 5px 26px;border-radius:8px;border:1px solid transparent;color:var(--muted)}
.ldk-lane li::before{content:counter(op);position:absolute;left:8px;color:var(--muted);font-size:.7rem;top:6px}
.ldk-lane li.cur{color:var(--text);border-color:var(--accent);background:var(--accent-soft)}
.ldk-lane li.cur::after{content:"◀ next";position:absolute;right:8px;font:700 .6rem Inter,sans-serif;color:var(--accent);top:7px}
.ldk-lane li.past{color:var(--text);opacity:.6;text-decoration:line-through;text-decoration-color:color-mix(in srgb,var(--text) 30%,transparent)}
.ldk-lane li.lk{font-weight:600}
.ldk-locks{margin-top:8px}
.ldk-log{margin:10px 18px 0;padding:8px 12px 8px 34px;max-height:140px;overflow:auto;border-radius:10px;background:var(--soft);font:12px/1.6 "JetBrains Mono",monospace}
