@media (max-width:760px){.ldk-rg{grid-template-columns:minmax(0,1fr)}.ldk-shared{order:-1}.ldk-lane li.cur::after{display:none}}
/* rubric */
.ldk-rtop{display:flex;flex-wrap:wrap;align-items:center;gap:8px 14px;padding:14px 18px 0}
