.ldk-rl>li>div:first-child span{font-size:.84rem;color:var(--muted)}
.ldk-mdl{font-style:normal;font-size:.8rem;color:var(--accent)}
.ldk-rbt{display:flex;gap:4px;flex-wrap:wrap}
.ldk-rbt button{font:600 .76rem Inter,sans-serif;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:5px 9px;cursor:pointer}
