.ldk-res{margin:12px 18px 0;border:1px solid var(--line);border-radius:12px;overflow:hidden}
.ldk-res .lp-sum{border-radius:0}
.ldk-res .lp-dt{margin:6px 12px 12px}
/* choose drill */
.ldk-chs{padding:10px 18px 0;font:600 .8rem "JetBrains Mono",monospace;color:var(--accent)}
.ldk-chl{margin:8px 18px 0;padding-left:22px;display:grid;gap:10px}
.ldk-chl>li>p{margin:0 0 6px;font-size:.93rem}
