.ld7-bar .ldk-modes{padding:0}
.ld7-sel{display:flex;align-items:center;gap:8px;font-size:.85rem;color:var(--muted);min-width:0;max-width:100%}
.ld7-sel select{font:inherit;font-size:.9rem;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:9px;padding:6px 8px;max-width:min(360px,calc(100vw - 120px))}
.ld7-meta{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px;margin:10px 18px 0;font-size:.85rem}
.ld7-h{margin:18px 18px 0;font-size:.95rem}
.ld7-tip{margin:12px 18px 0;font-size:.9rem;color:var(--muted)}
.ld7-stage,.ld7-grade{border-top:1px dashed var(--line);margin-top:14px}
.ld7-stage>div>.viz,.ld7-stage>.viz,.ld7-grade .viz,.ld7-body .viz{margin:14px 18px;box-shadow:none}
.ld7-stage>div:empty{display:none}
.ld7-hint{margin-top:8px}
