.ld7-hint>summary{font-size:.82rem}
.ld7-sum{display:flex;flex-wrap:wrap;gap:4px 12px;align-items:baseline;margin:14px 18px 0;padding:10px 14px;border-radius:12px;background:var(--accent-soft);border:1px solid var(--line)}
.ld7-two{display:block}
.ld7-grade>p{margin:6px 18px 0}
.ld7-two .viz{margin:12px 18px 0}
.ld7-grade>.lp-dt{margin:12px 18px 0}
.ld7-grade .ldk-code{max-height:420px;overflow:auto}
.ld7-tw{margin:10px 0 0}
.ld7-timed>[data-k="hist"],.ld7-mock>[data-k="hist"]{padding:0 18px}
.ld7-timed>[data-k="hist"]>p,.ld7-mock>[data-k="hist"]>p{margin:8px 0 0}
.ld7-timed>.tw,.ld7-mock>.tw{margin:10px 18px 0}
.ld7-chips{display:flex;flex-wrap:wrap;gap:6px;list-style:none;margin:0;padding:12px 18px 0}
.ld7-chips button{font:600 .78rem Inter,sans-serif;color:var(--muted);background:var(--surface);border:1px solid var(--line);border-radius:99px;padding:5px 11px;cursor:pointer}
.ld7-chips li.done button{color:var(--good);border-color:color-mix(in srgb,var(--good) 40%,var(--line))}
.ld7-chips li.on button{color:#fff;background:linear-gradient(135deg,var(--accent),var(--accent-2));border-color:transparent}
.ld7-qs{margin:10px 18px 0;padding-left:22px;display:grid;gap:8px}
.ld7-rep{margin:6px 0 2px;padding:7px 11px;border-radius:0 9px 9px 0;font-size:.88rem;background:var(--surface)}
.ld7-rep.ld7-ok{border-left:3px solid var(--good);background:var(--good-soft)}
.ld7-rep.ld7-weak{border-left:3px solid var(--amber);background:var(--amber-soft)}
.ld7-ta{display:grid;gap:6px;margin:12px 18px 0;font-size:.85rem;color:var(--muted)}
.ld7-ta textarea{font:.9rem/1.5 "JetBrains Mono",monospace;color:var(--text);background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:9px 11px;resize:vertical;width:100%;box-sizing:border-box}
.ld7-types{display:flex;flex-wrap:wrap;margin:8px 18px 0}
.ld7-why,.ld7-more{margin:8px 18px 0;font-size:.88rem}
.ld7-fix{margin:12px 14px 0;display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.ld7-sig{display:flex;flex-wrap:wrap;gap:8px;margin:14px 18px 0}
.ld7-sig span{padding:6px 11px;border:1px solid var(--line);border-radius:10px;background:var(--soft);font-size:.85rem}
.ld7-card{margin:14px 18px 0;padding:14px 16px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(135deg,color-mix(in srgb,var(--accent-soft) 70%,transparent),var(--surface) 70%)}
.ld7-qn{font:600 .74rem "JetBrains Mono",monospace;color:var(--accent);text-transform:uppercase;letter-spacing:.05em}
.ld7-q{margin:6px 0 10px;font-size:1.05rem;font-weight:600}
.ld7-timer{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.ld7-timer b{font:700 1.3rem "JetBrains Mono",monospace;min-width:3.4em}
.ld7-ans{margin-top:12px;padding:10px 13px;border-left:3px solid var(--accent);background:var(--surface);border-radius:0 10px 10px 0;font-size:.92rem}
.ld7-mark{margin-top:10px}
@media (max-width:560px){.ld7-bar,.ld7-chips,.ld7-meta{padding-left:12px;padding-right:12px}.ld7-stage>div>.viz,.ld7-grade .viz,.ld7-body .viz,.ld7-two .viz{margin-left:8px;margin-right:8px}.ld7-card,.ld7-ta,.ld7-qs{margin-left:12px;margin-right:12px}}
/* end lld L07 v1 */
/* lld review+tags v1 (2026-11-08): "Asked at" company chips under every LLDK.req header (.ldk-qt, filled by study.js), M07's
   Asked-at filter, the LLD case card's link in Review today. kb/site/site-internals.md → Study tools → LLD case cards. */
.ldk-qt{margin:12px 18px 0;padding:10px 14px;border:1px solid var(--line);border-radius:12px;background:var(--surface);min-width:0}
.ldk-qt:empty{display:none}
.ldq-hd{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px;font-size:.88rem}
.ldq-hd b{font-weight:700;color:var(--text)}
.ldq-none{color:var(--muted);font-size:.84rem}
.ldk-qt .qt-box{margin-top:6px;padding-top:0;border-top:0;gap:6px}
.ldk-qt .qt-chips{margin-top:0}
.ldk-qt .qt-f input{max-width:min(260px,100%)}
.ldq-at select{max-width:min(240px,calc(100vw - 120px))}
.ldq-go{margin:10px 0 0}
.ldq-go a{font-weight:600}
@media (max-width:560px){.ldk-qt{margin-left:12px;margin-right:12px;padding:9px 11px}}
/* end lld review+tags v1 */
/* lld L10 v1 */
.ld10-help{margin:12px 18px 0;font-size:.88rem;color:var(--muted)}
.ld10-code{margin:10px 18px 0;padding:8px 0;background:var(--code-bg);color:var(--code-text);border:1px solid var(--code-line);border-radius:12px;font:12.5px/1.6 "JetBrains Mono",monospace;overflow:auto;max-height:520px;tab-size:4;font-variant-ligatures:none}
