.ld10-ln.mk{background:color-mix(in srgb,#f59e0b 16%,var(--code-bg));border-left-color:#f59e0b}
.ld10-ln.sel{background:color-mix(in srgb,#8b5cf6 26%,var(--code-bg));border-left-color:#a78bfa}
