.ld10-ln.mdl.mk>i{color:#4ade80}
.ld10-form{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:12px 18px 0;font-size:.88rem}
.ld10-form input,.ld10-form select{font:inherit;color:var(--text);background:var(--soft);border:1px solid var(--line);border-radius:9px;padding:6px 8px}
.ld10-form input{width:5em}.ld10-form select{max-width:100%}
.ld10-list{margin:10px 18px 0;padding-left:22px;display:grid;gap:4px;font-size:.88rem}
.ld10-list:empty{display:none}
.ld10-lr{font:600 .78rem "JetBrains Mono",monospace;color:var(--muted)}
.ld10-x{margin-left:6px;border:1px solid var(--line);background:var(--soft);color:var(--muted);border-radius:7px;padding:0 7px;cursor:pointer;font:inherit}
