.ld10-find{margin:10px 0 0;padding:0;list-style:none;display:grid;gap:8px}
.ld10-find>li{padding:10px 13px;border:1px solid var(--line);border-left:4px solid var(--muted);border-radius:0 11px 11px 0;background:var(--surface);font-size:.9rem}
.ld10-find>li.ld10-hit{border-left-color:var(--good);background:var(--good-soft)}
.ld10-find>li.ld10-near{border-left-color:var(--amber);background:var(--amber-soft)}
.ld10-find>li.ld10-miss{border-left-color:var(--bad);background:var(--bad-soft)}
.ld10-find p{margin:6px 0 0}.ld10-find em{font-style:normal;font-weight:600}
.ld10-fh{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px}
.ld10-ic{font-weight:700;width:1.1em}
.ld10-tags{display:flex;flex-wrap:wrap;gap:4px;align-items:center}
.ld10-risk{font:600 .72rem Inter,sans-serif;padding:2px 8px;border-radius:99px;border:1px solid var(--line);background:var(--soft)}
.ld10-r-bug{color:var(--bad)}.ld10-r-conc{color:#8b5cf6}.ld10-r-test{color:var(--accent)}.ld10-r-change{color:var(--amber)}
.ld10-h4{margin:14px 0 4px;font-size:.92rem}
.ld10-fa{margin:0;padding-left:20px;font-size:.88rem;display:grid;gap:4px}
.ld10-tabs{display:flex;flex-wrap:wrap;gap:6px;margin:12px 18px 0}
.ld10-tabs button{font:600 .82rem Inter,sans-serif;color:var(--text);background:var(--soft);border:1px solid var(--line);border-radius:99px;padding:5px 12px;cursor:pointer}
.ld10-tabs button.on{background:var(--accent);border-color:var(--accent);color:#fff}
.ld10-card{margin:12px 18px 0;padding:12px 15px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.ld10-card h4{margin:0 0 6px;font-size:1rem}.ld10-mv{margin:0 0 6px;font-size:.92rem}
.ld10-ul{margin:4px 0 0;padding-left:20px;font-size:.88rem}
.ld10-meta{margin-top:8px;display:flex;flex-wrap:wrap;align-items:center;gap:2px}
.ld10-tl{font-size:.78rem;margin-left:6px}
.ld10-card .ldk-verd{margin:10px 0 0}
.ld10-dd{margin:10px 18px 0}.ld10-dd .ldk-code{margin:8px 0 0;max-height:420px}
.ld10-fold{color:var(--muted);font-style:italic}
@media (max-width:560px){.ld10-help,.ld10-code,.ld10-form,.ld10-list,.ld10-res,.ld10-tabs,.ld10-card,.ld10-dd{margin-left:12px;margin-right:12px}.ld10-ln>i{width:2.4em;padding-right:.5em}}
