/* dsa bank workspace v1 (assets/labs/dsa/labs-dsa-bank.js, 2026-11-08): body.dbk-ws turns #dbkLab into a full-window workspace under the nav
   (≥ 900 px): grid side | timeline / bench / footer; the bench scrolls by itself, the page does not. Problem list .dbk-side (.dbk-sd*),
   progress ring .dbk-ring, ⇤ hides it (body.dbk-noside). Outside the workspace .dbk-side is not shown and the lab looks as before. */
.dbk-side{display:none}
.dbk-wsb[hidden]{display:none}
body.dbk-ws{overflow:hidden}
body.dbk-ws .dbk-lab{position:fixed;z-index:24;top:var(--dbk-top,53px);left:0;right:0;bottom:0;width:auto;margin:0;font-size:15px;
  display:grid;grid-template-columns:var(--dbk-sw,312px) minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto;grid-template-areas:"side tl" "side bench" "side foot";
  background:radial-gradient(1200px 500px at 70% -10%,color-mix(in srgb,var(--accent) 7%,transparent),transparent 70%),var(--bg)}
body.dbk-ws.dbk-noside .dbk-lab{grid-template-columns:minmax(0,1fr);grid-template-areas:"tl" "bench" "foot"}
body.dbk-ws.dbk-noside .dbk-side{display:none}
body.dbk-ws #toc,body.dbk-ws #tocBtn{display:none}
body.dbk-ws .dbk-tl{grid-area:tl;position:relative;top:auto;margin:0;border:0;border-bottom:1px solid var(--line);border-radius:0;box-shadow:none;padding:10px 22px 8px}
body.dbk-ws:not(.dbk-noside) .dbk-tl [data-t="list"]{display:none}
body.dbk-ws .dbk-drawer{display:none}
body.dbk-ws .dbk-bench{grid-area:bench;margin:0;overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable;padding:20px clamp(16px,2.2vw,36px) 36px}
body.dbk-ws article.dbk-p{max-width:1560px;margin:0 auto;scroll-margin-top:0}
body.dbk-ws .dbk-foot{grid-area:foot;position:relative;bottom:auto;margin:0;border:0;border-top:1px solid var(--line);border-radius:0;box-shadow:none;padding:10px 22px}
body.dbk-ws .dbk-aside,body.dbk-ws .dbk-task{top:14px}
body.dbk-ws .dbk-ph{padding:20px 26px 16px}
body.dbk-ws .dbk-t{font-size:1.45rem}

body.dbk-ws .dbk-side{grid-area:side;display:flex;flex-direction:column;min-height:0;background:color-mix(in srgb,var(--surface) 92%,var(--bg));border-right:1px solid var(--line)}
.dbk-sdh{display:flex;align-items:center;gap:12px;padding:16px 14px 12px 16px}
.dbk-ring{position:relative;flex:none;width:46px;height:46px}
.dbk-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.dbk-ring circle{fill:none;stroke:var(--soft);stroke-width:4.5}
.dbk-ring .dbk-ringv{stroke:var(--good);stroke-linecap:round;stroke-dasharray:0 100;transition:stroke-dasharray .6s cubic-bezier(.2,.7,.2,1)}
.dbk-ringp{position:absolute;inset:0;display:grid;place-items:center;font:700 .7rem "JetBrains Mono",monospace;color:var(--text)}
.dbk-sdtw{display:flex;flex-direction:column;min-width:0;flex:1}
.dbk-sdt{font:800 1.08rem "Inter Tight",Inter,sans-serif;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dbk-sds{font-size:.74rem;color:var(--muted);white-space:nowrap}
.dbk-sdx{flex:none;width:30px;height:30px;border-radius:9px;border:1px solid var(--line);background:var(--soft);color:var(--muted);cursor:pointer;font-size:.9rem}
.dbk-sdx:hover{color:var(--text);border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
.dbk-sdq{display:flex;align-items:center;gap:8px;margin:0 14px 10px;padding:0 12px;height:38px;border:1px solid var(--line);border-radius:11px;background:var(--bg);color:var(--muted)}
.dbk-sdq:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 22%,transparent)}
.dbk-sdq input{flex:1;min-width:0;border:0;outline:0;background:none;color:var(--text);font:500 .86rem Inter,sans-serif}
.dbk-sdf{display:flex;flex-wrap:wrap;gap:5px;padding:0 14px 12px;border-bottom:1px solid var(--line)}
.dbk-sdc{font:600 .74rem Inter,sans-serif;color:var(--muted);background:none;border:1px solid var(--line);border-radius:99px;padding:3px 9px;cursor:pointer}
.dbk-sdc:hover{color:var(--text)}
.dbk-sdc[aria-pressed="true"]{color:var(--accent);background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
.dbk-sdu{margin-left:auto}
.dbk-sdl{position:relative;flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:6px 8px 14px;scrollbar-width:thin}
.dbk-sdg ol{list-style:none;margin:0 0 6px;padding:0}
.dbk-sdg.dbk-shut ol{display:none}
.dbk-sdgh{position:sticky;top:-6px;z-index:1;width:100%;display:grid;grid-template-columns:auto 1fr auto;grid-template-rows:auto auto;align-items:center;gap:3px 8px;
  text-align:left;background:color-mix(in srgb,var(--surface) 92%,var(--bg));border:0;border-radius:10px;padding:10px 8px 7px;cursor:pointer;color:var(--text)}
.dbk-sdgh b{font:700 .84rem "Inter Tight",Inter,sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dbk-sdgh em{font:600 .7rem "JetBrains Mono",monospace;font-style:normal;color:var(--muted)}
.dbk-sdgh em::after{content:" ▾";display:inline-block;transition:transform .2s}
.dbk-sdgh[aria-expanded="false"] em::after{transform:rotate(-90deg)}
.dbk-sdgb{grid-column:1/-1;height:3px;border-radius:9px;background:var(--soft);overflow:hidden}
.dbk-sdgb u{display:block;height:100%;width:0;background:var(--good);border-radius:inherit;transition:width .6s}
.dbk-sdgh:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.dbk-sdi{position:relative;width:100%;display:grid;grid-template-columns:12px 24px minmax(0,1fr);align-items:center;gap:8px;text-align:left;
  font:500 .85rem/1.3 Inter,sans-serif;color:color-mix(in srgb,var(--text) 86%,var(--muted));background:none;border:0;border-radius:9px;padding:7px 10px 7px 12px;cursor:pointer}
.dbk-sdi:hover{background:var(--soft);color:var(--text)}
.dbk-sdi:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.dbk-sdi.dbk-cur{background:var(--accent-soft);color:var(--text);font-weight:650}
.dbk-sdi.dbk-cur::before{content:"";position:absolute;left:2px;top:7px;bottom:7px;width:3px;border-radius:3px;background:var(--accent)}
.dbk-sdi i{width:10px;height:10px;border-radius:50%;border:2px solid color-mix(in srgb,var(--muted) 55%,var(--line))}
.dbk-sdi[data-st="1"] i{background:var(--amber);border-color:var(--amber)}
.dbk-sdi[data-st="2"] i{background:var(--good);border-color:var(--good)}
.dbk-sdi[data-st="2"] .dbk-sdtt{color:var(--muted)}
.dbk-sdn{font:600 .7rem "JetBrains Mono",monospace;color:var(--muted)}
.dbk-sdtt{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}
.dbk-sdnone{margin:18px 10px;font-size:.84rem;color:var(--muted)}
.dbk-sdft{display:flex;gap:6px;padding:10px 12px;border-top:1px solid var(--line)}
.dbk-sdb{flex:1;font:600 .76rem Inter,sans-serif;color:var(--text);background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:7px 8px;cursor:pointer;white-space:nowrap}
.dbk-sdb:hover{border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
@media (max-width:1180px){body.dbk-ws .dbk-lab{--dbk-sw:272px}}
@media (prefers-reduced-motion:reduce){.dbk-ring .dbk-ringv,.dbk-sdgb u,.dbk-sdgh em::after{transition:none}}
html.no-motion .dbk-ring .dbk-ringv,html.no-motion .dbk-sdgb u{transition:none}
/* end dsa bank workspace v1 */
/* dsa bank practice tools v1 (assets/labs/dsa/labs-dsa-bank.js, 2026-11-08): interview clock .dbk-clock, mock round banner .dbk-mock + result
   .dbk-mres + toast .dbk-toast, sidebar extras (.dbk-sdf2 company / Blind 75, row marks .dbk-sdm, .dbk-sdlast), hidden-test verdict .dbk-hid,
   stage-4 splitter .dbk-split (workspace only), notes .dbk-nb / .dbk-note, Big-O check .dbk-bigo, locked stage tabs .dbk-lock */
.dbk-clock{display:flex;align-items:center;gap:2px;padding:3px 4px 3px 10px;border:1px solid var(--line);border-radius:10px;background:var(--soft);font:600 .8rem Inter,sans-serif;color:var(--muted);white-space:nowrap}
.dbk-ckv{font:700 .86rem "JetBrains Mono",monospace;color:var(--text);min-width:3.4em;text-align:right}
.dbk-ckt{font:500 .74rem "JetBrains Mono",monospace;margin-right:4px}
.dbk-clock button{width:24px;height:24px;padding:0;border:0;border-radius:7px;background:none;color:var(--muted);cursor:pointer;font-size:.78rem}
.dbk-clock button:hover{background:var(--surface);color:var(--text)}.dbk-clock button[hidden]{display:none}
.dbk-clock.dbk-ckwarn{border-color:color-mix(in srgb,var(--amber) 55%,var(--line))}.dbk-clock.dbk-ckwarn .dbk-ckv{color:var(--amber)}
.dbk-clock.dbk-ckover{border-color:color-mix(in srgb,var(--bad) 55%,var(--line));background:color-mix(in srgb,var(--bad) 8%,var(--soft))}.dbk-clock.dbk-ckover .dbk-ckv{color:var(--bad)}
.dbk-clock.dbk-ckdone{border-color:color-mix(in srgb,var(--good) 45%,var(--line))}.dbk-clock.dbk-ckdone .dbk-ckv,.dbk-clock.dbk-ckdone .dbk-ckt{color:var(--good)}
@media (max-width:700px){.dbk-ckt{display:none}}
.dbk-mock{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;margin:-2px 0 8px;padding:7px 10px;border-radius:12px;font-size:.8rem;
  background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 16%,var(--surface)),color-mix(in srgb,var(--accent-2) 10%,var(--surface)));border:1px solid color-mix(in srgb,var(--accent) 35%,var(--line))}
.dbk-mock[hidden]{display:none}
.dbk-mock>b{font:800 .84rem "Inter Tight",Inter,sans-serif;color:var(--accent)}
.dbk-mkt{font:700 .9rem "JetBrains Mono",monospace;color:var(--text);margin-right:4px}.dbk-mkt.dbk-mklow{color:var(--bad)}
.dbk-mkp,.dbk-mke{font:600 .76rem Inter,sans-serif;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:99px;padding:4px 11px;cursor:pointer;max-width:260px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dbk-mkp.on{border-color:var(--accent);color:var(--accent)}.dbk-mkp.ok{color:var(--good)}
.dbk-mke{margin-left:auto;color:var(--bad)}
.dbk-sb.dbk-lock{opacity:.4;cursor:not-allowed}.dbk-sb.dbk-lock span::after{content:" \1F512";font-size:.75em}
.dbk-toast{position:absolute;z-index:30;left:50%;bottom:76px;transform:translateX(-50%);max-width:min(520px,90%);padding:10px 16px;border-radius:12px;background:var(--text);color:var(--bg);font:500 .84rem/1.4 Inter,sans-serif;box-shadow:0 12px 32px rgba(0,0,0,.25)}
.dbk-toast[hidden]{display:none}
body:not(.dbk-ws) .dbk-toast{position:fixed}
.dbk-mres{position:absolute;z-index:31;inset:0;display:grid;place-items:center;background:color-mix(in srgb,var(--bg) 60%,transparent);backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px);padding:16px}
body:not(.dbk-ws) .dbk-mres{position:fixed;z-index:60}
.dbk-mrc{width:min(460px,100%);background:var(--surface);border:1px solid var(--line);border-radius:20px;box-shadow:0 24px 60px rgba(0,0,0,.3);padding:22px 24px}
.dbk-mrc h3{margin:6px 0 12px;font:800 1.5rem "Inter Tight",Inter,sans-serif}
.dbk-mrc ol{list-style:none;margin:0;padding:0;border:1px solid var(--line);border-radius:12px;overflow:hidden}
.dbk-mrc li{display:grid;grid-template-columns:22px minmax(0,1fr) auto;gap:8px;padding:9px 12px;border-top:1px solid var(--line);font-size:.88rem}
.dbk-mrc li:first-child{border-top:0}.dbk-mrc li.ok b{color:var(--good)}.dbk-mrc li.no b{color:var(--bad)}
.dbk-mrc li em{font:600 .76rem "JetBrains Mono",monospace;font-style:normal;color:var(--muted)}
.dbk-mra{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}
/* sidebar extras */
.dbk-sdf2{padding-top:0;align-items:center}
.dbk-sdco{flex:1;min-width:0}
.dbk-sdco .sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.dbk-sdco select{width:100%;font:500 .76rem Inter,sans-serif;color:var(--text);background:var(--bg);border:1px solid var(--line);border-radius:99px;padding:4px 8px;cursor:pointer}
.dbk-sdi{grid-template-columns:12px 24px minmax(0,1fr) auto}
.dbk-sdm{display:flex;gap:4px;align-items:center}
.dbk-sdm em{font:600 .66rem "JetBrains Mono",monospace;font-style:normal;color:var(--muted)}
.dbk-sdm .dbk-due{color:var(--amber);border:1px solid color-mix(in srgb,var(--amber) 50%,transparent);border-radius:99px;padding:0 5px;font-family:Inter,sans-serif}
.dbk-sdm .dbk-tm{color:var(--good)}
.dbk-sdlast{margin:0;padding:6px 14px 0;font-size:.72rem;color:var(--muted);border-top:1px solid var(--line)}
.dbk-sdlast[hidden]{display:none}
.dbk-sdlast+.dbk-sdft{border-top:0}
.dbk-sdmk{color:var(--accent)}
/* hidden tests */
.dbk-hid{margin:8px 0;font-weight:600}.dbk-hid .muted{font-weight:500;color:var(--muted)}
.dbk-hid.dbk-vrun{color:var(--text)}.dbk-hid .jr-spin{margin-left:8px}
.dbk-hl{list-style:none;margin:8px 0 4px;padding:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;font-weight:500;color:var(--text)}
.dbk-hl li{display:grid;grid-template-columns:62px minmax(0,1fr) minmax(0,1fr);gap:8px;padding:6px 10px;border-top:1px solid var(--line);font-size:.78rem;background:color-mix(in srgb,var(--bad) 5%,transparent);overflow-wrap:anywhere}
.dbk-hl li:first-child{border-top:0}.dbk-hl b{color:var(--bad)}
@media (max-width:640px){.dbk-hl li{grid-template-columns:minmax(0,1fr)}}
/* stage-4 splitter (workspace) */
.dbk-split{display:none}
body.dbk-ws .dbk-s4:not([hidden]){grid-template-columns:var(--dbk-l,minmax(0,.8fr)) 12px minmax(0,1.2fr);column-gap:8px}
body.dbk-ws .dbk-split{display:block;position:relative;cursor:col-resize;border-radius:8px;touch-action:none;align-self:stretch;min-height:200px}
body.dbk-ws .dbk-split::before{content:"";position:absolute;left:5px;top:0;bottom:0;width:2px;border-radius:2px;background:var(--line);transition:background .2s}
body.dbk-ws .dbk-split::after{content:"";position:absolute;left:2px;top:50%;width:8px;height:40px;margin-top:-20px;border-radius:6px;background:var(--soft);border:1px solid var(--line)}
body.dbk-ws .dbk-split:hover::before,body.dbk-ws .dbk-split:focus-visible::before,body.dbk-drag .dbk-split::before{background:var(--accent)}
body.dbk-ws .dbk-split:focus-visible{outline:none}
body.dbk-drag,body.dbk-drag *{cursor:col-resize!important;user-select:none}
body.dbk-ws .dbk-task{position:sticky;top:0;align-self:start;max-height:calc(100vh - var(--dbk-top,53px) - 190px);overflow:auto;scrollbar-width:thin;padding-right:4px}
/* notes */
.dbk-nb.dbk-nbon{color:var(--accent);border-color:color-mix(in srgb,var(--accent) 45%,var(--line));background:var(--accent-soft)}
.dbk-note{padding:12px 22px 14px;border-top:1px solid var(--line);background:color-mix(in srgb,var(--amber-soft) 60%,var(--surface))}
.dbk-note[hidden]{display:none}
.dbk-note label{display:flex;flex-direction:column;gap:6px}
.dbk-note label span{font:700 .72rem Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--amber)}
.dbk-note textarea{width:100%;box-sizing:border-box;resize:vertical;min-height:70px;font:500 .9rem/1.5 Inter,sans-serif;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:8px 10px}
.dbk-note textarea:focus{outline:none;border-color:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 20%,transparent)}
.dbk-note small{display:block;margin-top:5px;font-size:.72rem;color:var(--muted)}
/* Big-O check */
.dbk-bigo{margin:12px 0;padding:12px 14px;border:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));border-radius:14px;background:color-mix(in srgb,var(--accent-soft) 55%,var(--surface))}
.dbk-bigo h5{margin:0 0 8px;font:700 .86rem "Inter Tight",Inter,sans-serif}
.dbk-bor{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:6px 0}
.dbk-bor>span{width:52px;font:600 .74rem Inter,sans-serif;color:var(--muted)}
.dbk-boc{font:600 .8rem "JetBrains Mono",monospace;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:99px;padding:4px 11px;cursor:pointer}
.dbk-boc:hover:not(:disabled){border-color:var(--accent)}
.dbk-boc:disabled{cursor:default}
.dbk-boc.dbk-ok{color:var(--good);border-color:var(--good);background:var(--good-soft)}
.dbk-boc.dbk-no{color:var(--bad);text-decoration:line-through;opacity:.7}
.dbk-bom{margin:6px 0 0;font-size:.82rem;color:var(--muted)}.dbk-bom b{color:var(--text)}
/* end dsa bank practice tools v1 */
